INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "确认", "is_correct": true, "explanation": "正确：“请你再确认一下时间”中，“确认”表示核对并肯定，符合句意。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”后接节日、胜利等，不能接“时间”。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”后接食物、饮品，不能接“时间”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：请人“再忘记一下时间”没有意义，与句子的请求不合。"}], "explanations": {"确认": "正确：“请你再确认一下时间”中，“确认”表示核对并肯定，符合句意。", "庆祝": "搭配：“庆祝”后接节日、胜利等，不能接“时间”。", "品尝": "搭配：“品尝”后接食物、饮品，不能接“时间”。", "忘记": "语义：请人“再忘记一下时间”没有意义，与句子的请求不合。"}, "sentence_index": 0, "correct_answer": "确认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在学校确认了一个好朋友。", "explanation": "这里应该用〈认识〉。确认是把事情弄清楚并肯定下来，结识人要用认识。"}, {"text": "我在超市确认了一个西瓜。", "explanation": "这里应该用〈挑选〉。确认不用于挑选物品，选西瓜要用挑选。"}, {"text": "妈妈每天确认生病的爷爷。", "explanation": "这里应该用〈照顾〉。确认是核实、肯定事实，照料病人要用照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确认", "is_correct": true, "explanation": "正确：“警察确认了那个人的身份”中，“确认”表示核实并肯定，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”后接场所、展览等，不能接“身份”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植指栽培植物，与警察核实人的身份无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是身体的动作，与核实身份无关，句子不通。"}], "explanations": {"确认": "正确：“警察确认了那个人的身份”中，“确认”表示核实并肯定，符合句意。", "参观": "搭配：“参观”后接场所、展览等，不能接“身份”。", "种植": "语义：种植指栽培植物，与警察核实人的身份无关。", "跳舞": "语义：跳舞是身体的动作，与核实身份无关，句子不通。"}, "sentence_index": 6, "correct_answer": "确认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我给朋友确认了一本书。", "explanation": "这里应该用〈寄〉。确认是核实、肯定，给朋友寄东西要用寄。"}, {"text": "妈妈确认了很多衣服。", "explanation": "这里应该用〈洗〉。确认不用于清洗衣物，洗衣服要用洗。"}, {"text": "我确认了一杯牛奶。", "explanation": "这里应该用〈喝〉。确认指肯定事实，喝牛奶要用喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你打电话确认了航班。", "corrected_sentence": "请你打电话确认一下航班。", "error_description": "体标错误：祈使句“请你……”不能带表示完成的“了”，应把“了”改为“一下”，正确说法是「请你打电话确认一下航班」，“一下”表示稍微确认一下。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经确认过这个订单过。", "corrected_sentence": "我已经确认过这个订单了。", "error_description": "体标错误：“过”表示动作的经历，只用一次，放在动词“确认”后；句末表示完成的应是“了”，不能用“过”。应把句末的“过”改为“了”，正确说法是「我已经确认过这个订单了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
