INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "听讲话或音乐的人。", "primary_collocate": null, "pronunciation": "tīng zhòng", "ipa": "tʰiŋ˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师讲得很有意思，听众都笑了。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室里坐满了听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听众问了他三个问题。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的音乐厅里只有十位听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我最忠实的听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场讲座的听众大多是学生。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听众听完故事，心里很感动。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看听众，才开始讲话。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听众太多，后面的人只能站着。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听众们安静下来，等着他开口。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "聽眾", "label": "繁体"}, {"form": "听众席", "label": "复合"}], "register": "中性", "sense_fingerprint": "在场听别人讲话或音乐的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听众", "is_correct": true, "explanation": "正确：听众是在场听讲话的人，老师讲课后笑的正是这些听的人。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物件，不会笑。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是物件，不能作“笑”的主语。"}, {"text": "讲座", "is_correct": false, "explanation": "搭配：“笑”的主语须是人，讲座不能笑。"}], "explanations": {"听众": "正确：听众是在场听讲话的人，老师讲课后笑的正是这些听的人。", "黑板": "语义：黑板是物件，不会笑。", "课本": "语义：课本是物件，不能作“笑”的主语。", "讲座": "搭配：“笑”的主语须是人，讲座不能笑。"}, "sentence_index": 0, "correct_answer": "听众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景区里到处都是听众。", "explanation": "这里应该用〈游客〉。听众指在场听讲话或音乐的人，景区里的是游客。"}, {"text": "这份报纸的听众很多。", "explanation": "这里应该用〈读者〉。听众指听的人，看报纸的是读者。"}, {"text": "听众在酒店里负责洗碗。", "explanation": "这里应该用〈服务员〉。听众指听讲话或音乐的人，在酒店洗碗的是服务员，不能用“听众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听众", "is_correct": true, "explanation": "正确：听众是听故事的人，听完之后才会心里感动。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴没有感情，不会“心里很感动”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“听完故事”需要有听觉的主体，窗户不能“听”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有心，无法被感动。"}], "explanations": {"听众": "正确：听众是听故事的人，听完之后才会心里感动。", "钢琴": "语义：钢琴没有感情，不会“心里很感动”。", "窗户": "搭配：“听完故事”需要有听觉的主体，窗户不能“听”。", "石头": "语义：石头没有心，无法被感动。"}, "sentence_index": 6, "correct_answer": "听众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影请来了三位听众。", "explanation": "这里应该用〈演员〉。听众指听讲话或音乐的人，电影里参演的是演员，不能用“听众”。"}, {"text": "听众们在场上拼命奔跑。", "explanation": "这里应该用〈运动员〉。听众是听的人，在场上奔跑的是运动员。"}, {"text": "路口的听众认真地指挥交通。", "explanation": "这里应该用〈警察〉。听众指听讲话或音乐的人，指挥交通的是警察，不能用“听众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里坐着一只听众。", "corrected_sentence": "会议室里坐着一位听众。", "error_description": "错误在量词：听众指人，应用“位”或“个”，不能用“只”。正确说法是“一位听众”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场音乐会听众都很安静。", "corrected_sentence": "那场音乐会的听众都很安静。", "error_description": "错误在定语标记：“那场音乐会”修饰“听众”时要加“的”，应说“那场音乐会的听众”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
