INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24526, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "当众对听众讲话或讲述的人。", "primary_collocate": null, "pronunciation": "jiǎng shù zhě", "ipa": "tɕjɑŋ˨˩ ʂu˥˩ ʈʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "讲述者站在台上，说起自己的旅行。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位讲述者说话很慢，大家都听得懂。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们安静地看着讲述者。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位讲述者是个爱笑的老人。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲述者讲到高兴的地方，自己先笑了。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，每位讲述者只有五分钟。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是今天最受欢迎的讲述者。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲述者提高声音，后面的人才听清楚。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲述者说完后，大家都鼓起了掌。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上请一位讲述者介绍自己的家乡。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "講述者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "当场对听的人说话讲话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲述者", "is_correct": true, "explanation": "正确：讲述者是当场对听的人说话的人，能站在台上说起自己的旅行。"}, {"text": "听众", "is_correct": false, "explanation": "语义：听众是听的人，不会站在台上说起自己的旅行。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空没有生命，既不能站立，也不能说话。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“说起自己的旅行”要求有说话能力的主语，桌子不能作主语。"}], "explanations": {"讲述者": "正确：讲述者是当场对听的人说话的人，能站在台上说起自己的旅行。", "听众": "语义：听众是听的人，不会站在台上说起自己的旅行。", "天空": "语义：天空没有生命，既不能站立，也不能说话。", "桌子": "搭配：“说起自己的旅行”要求有说话能力的主语，桌子不能作主语。"}, "sentence_index": 0, "correct_answer": "讲述者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台下坐满了讲述者，大家都安静地听着。", "explanation": "这里应该用〈听众〉。讲述者是当场开口讲话的人，安静坐着听的是听众。"}, {"text": "晚会上请了一位讲述者来修理音响。", "explanation": "这里应该用〈技术人员〉。讲述者指说话的人，修理音响的是技术人员，不能用“讲述者”。"}, {"text": "场上的讲述者正在踢球，大家都在为他加油。", "explanation": "这里应该用〈运动员〉。讲述者是当众讲话的人，踢球的是运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲述者", "is_correct": true, "explanation": "正确：讲述者是当场对听的人讲话的人，才可能成为最受欢迎的人。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是人，无法被评为“最受欢迎的”对象。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“他是……的”要求指人，心情不能用来指人。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是物件，句中的“他”不能等同于作业。"}], "explanations": {"讲述者": "正确：讲述者是当场对听的人讲话的人，才可能成为最受欢迎的人。", "天空": "语义：天空不是人，无法被评为“最受欢迎的”对象。", "心情": "搭配：“他是……的”要求指人，心情不能用来指人。", "作业": "语义：作业是物件，句中的“他”不能等同于作业。"}, "sentence_index": 6, "correct_answer": "讲述者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一整天都没开口，却被选为今天的讲述者。", "explanation": "这里应该用〈旁观者〉。讲述者指当场开口讲话的人，一整天没开口的只能算旁观者，不能叫讲述者。"}, {"text": "这个讲述者在大厅里默默地打扫卫生。", "explanation": "这里应该用〈清洁工〉。讲述者指说话的人，在大厅里打扫卫生的是清洁工，不能用“讲述者”。"}, {"text": "讲述者在厨房里忙着做菜。", "explanation": "这里应该用〈厨师〉。讲述者指当场讲话的人，做菜的是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台上站着一只讲述者，他很幽默。", "corrected_sentence": "台上站着一位讲述者，他很幽默。", "error_description": "错误在量词：讲述者指人，应用“位”，不能用“只”。正确说法是“一位讲述者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场演讲讲述者很幽默。", "corrected_sentence": "这场演讲的讲述者很幽默。", "error_description": "错误在定语标记：“这场演讲”修饰“讲述者”时要加“的”，应说“这场演讲的讲述者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
