INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一件事，中间不停，一直连着。", "primary_collocate": null, "pronunciation": "lián xù xìng", "ipa": "ljɛn˧˥ ɕy˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "跑步要有连续性，每天跑才有用。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电视剧的连续性很强，每天晚上都有新的一集。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事缺少连续性，今天学，明天就不学了。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雨打断了比赛的连续性。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看书时老有人叫我，阅读的连续性就差了。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片的画面连续性很好，看起来很流畅。", "target_word": "连续性", "complexity_tier": "T3", "furigana": "zhè bù jìlùpiàn de huàmiàn liánxùxìng hěn hǎo, kàn qǐlái hěn liúchàng", "sentence_source": "generated"}, {"text": "写作文要注意句子之间的连续性。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条公路的连续性很好，中间没有红绿灯。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的连续性不能断，所以我们轮流休息。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话没有连续性，前一句和后一句不一样。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連續性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "中间不停、一直连着的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，跑步不具有颜色，“跑步要有颜色”不通。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指中间不停、一直连着，“跑步要有连续性”符合句意。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，跑步不具有重量，与句意不符。"}, {"text": "甜味", "is_correct": false, "explanation": "搭配：“有”后不能接“甜味”，跑步不具有味道。"}], "explanations": {"颜色": "语义：“颜色”指色彩，跑步不具有颜色，“跑步要有颜色”不通。", "连续性": "“连续性”指中间不停、一直连着，“跑步要有连续性”符合句意。", "重量": "语义：“重量”指物体的轻重，跑步不具有重量，与句意不符。", "甜味": "搭配：“有”后不能接“甜味”，跑步不具有味道。"}, "sentence_index": 0, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶酒的连续性很高，口感很醇。", "explanation": "这里应该用〈纯度〉。连续性指中间不停、一直连着，酒的纯净程度要说纯度。"}, {"text": "这座雕像的连续性很好，人们都很喜欢它。", "explanation": "这里应该用〈艺术性〉。连续性指不间断，雕像的艺术价值应说艺术性。"}, {"text": "这张照片的连续性很高，细节很清楚。", "explanation": "这里应该用〈清晰度〉。连续性指不间断，照片细节清楚要说清晰度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬度", "is_correct": false, "explanation": "搭配：“硬度”用于材料、物体，句子之间不能说硬度。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指外形，句子之间的联系不能说成形状，句意不通。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体所占的空间，不能说句子之间的体积。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指前后不间断地连着，“写作文要注意句子之间的连续性”符合句意。"}], "explanations": {"硬度": "搭配：“硬度”用于材料、物体，句子之间不能说硬度。", "形状": "语义：“形状”指外形，句子之间的联系不能说成形状，句意不通。", "体积": "搭配：“体积”指物体所占的空间，不能说句子之间的体积。", "连续性": "“连续性”指前后不间断地连着，“写作文要注意句子之间的连续性”符合句意。"}, "sentence_index": 6, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的连续性很高，看得清杯底。", "explanation": "这里应该用〈透明度〉。连续性指不间断，水清澈到能看清杯底要说透明度。"}, {"text": "这间屋子的连续性很高，有点闷。", "explanation": "这里应该用〈湿度〉。连续性指不间断，空气潮湿、发闷要说湿度。"}, {"text": "这辆车的连续性很快，几分钟就到了。", "explanation": "这里应该用〈速度〉。连续性指不间断，车跑得快要说速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产线必须连续性。", "corrected_sentence": "这条生产线必须有连续性。", "error_description": "缺少动词：“连续性”作宾语需要动词“有”；正确为“必须有连续性”，“必须连续性”缺少动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说的话不有连续性，每句都跳来跳去。", "corrected_sentence": "他说的话没有连续性，每句都跳来跳去。", "error_description": "否定词错误：“有”应用“没有”否定，不能用“不”；“不有连续性”错误，正确为“没有连续性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。"}, {"text": "秩序", "is_correct": false, "explanation": "与“勇气”无反义关系，“秩序”指有条理的正常状态。"}, {"text": "责任", "is_correct": false, "explanation": "与“勇气”无反义关系，“责任”指应当承担的义务。"}, {"text": "友谊", "is_correct": false, "explanation": "与“勇气”无反义关系，“友谊”指朋友之间的感情。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。", "秩序": "与“勇气”无反义关系，“秩序”指有条理的正常状态。", "责任": "与“勇气”无反义关系，“责任”指应当承担的义务。", "友谊": "与“勇气”无反义关系，“友谊”指朋友之间的感情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。"}, {"text": "桌子", "is_correct": false, "explanation": "与“勇气”无反义关系，“桌子”是家具。"}, {"text": "河流", "is_correct": false, "explanation": "与“勇气”无反义关系，“河流”是自然地理事物。"}, {"text": "节日", "is_correct": false, "explanation": "与“勇气”无反义关系，“节日”指特定的庆祝日子。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。", "桌子": "与“勇气”无反义关系，“桌子”是家具。", "河流": "与“勇气”无反义关系，“河流”是自然地理事物。", "节日": "与“勇气”无反义关系，“节日”指特定的庆祝日子。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做害怕的事不哭，就是胆子大。", "primary_collocate": null, "pronunciation": "yǒng qì", "ipa": "jʊŋ˨˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "小明打针时没有哭，真有勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有勇气一个人睡觉。", "target_word": "勇气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟不怕黑，他很有勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友鼓起勇气，跳进了水里。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，我今天很有勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次骑车摔倒，也没有哭，真有勇气。", "target_word": "勇气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩有勇气去看大狗。", "target_word": "勇气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师夸小红有勇气，因为她敢一个人上台。", "target_word": "勇气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想有勇气一个人去上学。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他需要勇气，才敢上台唱歌。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股勇气", "label": "量词"}, {"form": "勇氣", "label": "繁体"}], "register": "通用", "sense_fingerprint": "小孩做害怕的事时不哭、胆子大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。yǒng qì，指做害怕的事时不哭、胆子大。"}, {"text": "涌起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是“涌起”，指冒出、升起。"}, {"text": "充气", "is_correct": false, "explanation": "chōng 与 yǒng 声母不同，意思是“把气体充进去”。"}, {"text": "中气", "is_correct": false, "explanation": "zhōng 与 yǒng 声母不同，意思是“中气”，指说话或呼吸时的底气。"}], "explanations": {"勇气": "正确。yǒng qì，指做害怕的事时不哭、胆子大。", "涌起": "qǐ（第三声）与 qì（第四声）声调不同，意思是“涌起”，指冒出、升起。", "充气": "chōng 与 yǒng 声母不同，意思是“把气体充进去”。", "中气": "zhōng 与 yǒng 声母不同，意思是“中气”，指说话或呼吸时的底气。"}, "sentence_index": null, "correct_answer": "勇气"}, "level_3": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。句中夸小明打针不哭，这里应是“勇气”。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指体力，与打针时不哭所体现的胆量不同。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：句中说“没有哭”，又说“真有”，不能用“眼泪”作为被夸赞的品质。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“真有”后接“体温”不能表示赞扬，与这种评价不搭配。"}], "explanations": {"勇气": "正确。句中夸小明打针不哭，这里应是“勇气”。", "力气": "语义：“力气”指体力，与打针时不哭所体现的胆量不同。", "眼泪": "语义：句中说“没有哭”，又说“真有”，不能用“眼泪”作为被夸赞的品质。", "体温": "搭配：“真有”后接“体温”不能表示赞扬，与这种评价不搭配。"}, "sentence_index": 0, "correct_answer": "勇气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈很有勇气，一遍遍地陪我练习写字。", "explanation": "这里应该用〈耐心〉。勇气指敢做害怕的事的胆量，反复陪伴练习要说“耐心”，不说“很有勇气”。"}, {"text": "弟弟勇气大，一个人能扛起箱子。", "explanation": "这里应该用〈力气〉。扛箱子靠体力，勇气不能说明体力。"}, {"text": "他今天勇气很好，考试时猜中了好几道题。", "explanation": "这里应该用〈运气〉。猜中题目靠运气，勇气指敢做害怕的事的胆量，不能说“勇气很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。“有勇气”后接“去看大狗”，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装书的用品，不能与“去看大狗”的胆量搭配。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：“尾巴”是身体部位，句中无法用它表示去看大狗的条件。"}, {"text": "帽子", "is_correct": false, "explanation": "搭配：“有帽子”可说，但“去看大狗”需要的是胆量，不能用帽子代替。"}], "explanations": {"勇气": "正确。“有勇气”后接“去看大狗”，符合句意。", "书包": "语义：“书包”是装书的用品，不能与“去看大狗”的胆量搭配。", "尾巴": "语义：“尾巴”是身体部位，句中无法用它表示去看大狗的条件。", "帽子": "搭配：“有帽子”可说，但“去看大狗”需要的是胆量，不能用帽子代替。"}, "sentence_index": 6, "correct_answer": "勇气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他数学勇气很好，每次都考第一。", "explanation": "这里应该用〈成绩〉。勇气不能描述学科水平，数学好要说“成绩好”。"}, {"text": "他的勇气写得很漂亮。", "explanation": "这里应该用〈字〉。勇气是精神品质，不能用来说字写得好。"}, {"text": "他勇气很好，从来不跟别人吵架。", "explanation": "这里应该用〈脾气〉。性情温和、不轻易与人争吵要说“脾气好”，勇气指敢做害怕的事，不能用来形容性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小宝拿出一个勇气，自己走进了医院。", "corrected_sentence": "小宝拿出一股勇气，自己走进了医院。", "error_description": "量词错误：“勇气”的量词是“股”，应说“一股勇气”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于鼓上勇气，自己去看医生。", "corrected_sentence": "他终于鼓起勇气，自己去看医生。", "error_description": "补语错误：“鼓”与“勇气”之间的结果补语应为“起”，说“鼓起勇气”，不能用“上”说“鼓上勇气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
