INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "传说就是很久以前人们讲的故事。", "primary_collocate": null, "pronunciation": "chuán shuō", "ipa": "ʈʂʰwan˧˥ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "这个传说是爷爷小时候听来的。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢长城的传说。", "target_word": "传说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们写一个中国的传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里有很多关于龙的传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个湖有一个有名的传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们坐在树下听传说。", "target_word": "传说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个传说的结尾让人很难过。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个地方都有自己的传说。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这个传说画成了一本小书。", "target_word": "传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前的传说，现在还有人在讲。", "target_word": "传说", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "则", "label": "量词"}, {"form": "民间传说", "label": "复合"}, {"form": "神话传说", "label": "复合"}, {"form": "傳說", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很久以前人们讲的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传说", "is_correct": true, "explanation": "正确：“听来的”搭配口耳相传的故事，“传说”符合“很久以前人们讲的故事”的意思。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不能“听来”，句意不通。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒不能被“听来”，与“爷爷小时候”的语境矛盾。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“听来”搭配消息、故事等，不搭配螺丝这类物件。"}], "explanations": {"传说": "正确：“听来的”搭配口耳相传的故事，“传说”符合“很久以前人们讲的故事”的意思。", "冰箱": "语义：冰箱是电器，不能“听来”，句意不通。", "病毒": "语义：病毒不能被“听来”，与“爷爷小时候”的语境矛盾。", "螺丝": "搭配：“听来”搭配消息、故事等，不搭配螺丝这类物件。"}, "sentence_index": 0, "correct_answer": "传说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给孩子吃了一个传说。", "explanation": "这里应该用〈苹果〉。〈传说〉是讲述的故事，不能用“吃”。"}, {"text": "我今天收到了一条重要的传说。", "explanation": "这里应该用〈通知〉。〈传说〉是很久以前流传的故事，不是可以收到的消息。"}, {"text": "他在会议上提出了一个新传说。", "explanation": "这里应该用〈方案〉。〈传说〉是民间流传的故事，不是可以在会议上提出的计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传说", "is_correct": true, "explanation": "正确：“传说的结尾”指传说故事的末尾，与“让人很难过”相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温没有结尾，“体温的结尾让人很难过”句意不通。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“结尾”搭配叙事作品，不搭配水泥这类建材。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是物理量，没有“让人很难过”的结尾，语义不通。"}], "explanations": {"传说": "正确：“传说的结尾”指传说故事的末尾，与“让人很难过”相符。", "体温": "语义：体温没有结尾，“体温的结尾让人很难过”句意不通。", "水泥": "搭配：“结尾”搭配叙事作品，不搭配水泥这类建材。", "电压": "语义：电压是物理量，没有“让人很难过”的结尾，语义不通。"}, "sentence_index": 6, "correct_answer": "传说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是确凿的传说。", "explanation": "这里应该用〈证据〉。传说是流传下来的叙述，不能用“确凿”来形容。"}, {"text": "老师布置的传说我已经做完了。", "explanation": "这里应该用〈作业〉。〈传说〉是民间流传的故事，不能说“做完”。"}, {"text": "他昨天打了一个传说给我。", "explanation": "这里应该用〈电话〉。〈传说〉是流传下来的故事，不能用“打”给人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里，爷爷给我讲了一张古老的传说。", "corrected_sentence": "夜里，爷爷给我讲了一个古老的传说。", "error_description": "量词错误：〈传说〉应搭配〈个〉或〈则〉，〈张〉用于纸张、桌子等平面物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人给我们讲了一个很美传说。", "corrected_sentence": "老人给我们讲了一个很美的传说。", "error_description": "结构错误：〈很美〉修饰名词时要加〈的〉，应说“很美的传说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
