INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时节就是一年里的某个时候，比如春天、夏天。", "primary_collocate": null, "pronunciation": "shí jié", "ipa": "ʂɻ̩˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "春天是播种的时节。", "target_word": "时节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "七月是荔枝上市的时节。", "target_word": "时节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个时节，北方已经下雪了。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年这个时节，我们都去海边玩。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "樱花盛开的时节，公园里人很多。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了落叶的时节，路上铺满黄叶。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天是最适合爬山的时节。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "梅雨时节，衣服总是干不了。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她最喜欢春暖花开的时节。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暑假正是游泳的最好时节。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "時節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时节：一年里的某个时候，如春天、夏天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指一年里的某个时候，是本题的目标词。"}, {"text": "十戒", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。"}, {"text": "石阶", "is_correct": false, "explanation": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。"}, {"text": "世界", "is_correct": false, "explanation": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。"}, {"text": "十级", "is_correct": false, "explanation": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}], "explanations": {"时节": "时节（shí jié）指一年里的某个时候，是本题的目标词。", "十戒": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。", "石阶": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。", "世界": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。", "十级": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指一年中的某个时候，符合“春天是播种的……”的语境。"}, {"text": "田地", "is_correct": false, "explanation": "语义：“田地”指土地，不表示时间，“春天是播种的田地”不成立。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”指器物，不表示一年中的某个时候。"}, {"text": "农具", "is_correct": false, "explanation": "语义：“农具”指耕作用的器具，不表示时间，“春天是播种的农具”不成立。"}], "explanations": {"时节": "正确：“时节”指一年中的某个时候，符合“春天是播种的……”的语境。", "田地": "语义：“田地”指土地，不表示时间，“春天是播种的田地”不成立。", "工具": "语义：“工具”指器物，不表示一年中的某个时候。", "农具": "语义：“农具”指耕作用的器具，不表示时间，“春天是播种的农具”不成立。"}, "sentence_index": 0, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一只凉快的时节，适合郊游。", "explanation": "这里应该用〈个〉。时节前用“个”，“只”多用于动物或单件小物，不能修饰时节。"}, {"text": "火车到站的时节是下午三点。", "explanation": "这里应该用〈时刻〉。时节指一年中的某段时候，不指具体的某个钟点。"}, {"text": "我们定好的时节是下周三。", "explanation": "这里应该用〈日期〉。时节指一年里的某个时候，不指某一天；约定具体哪一天要说“日期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指一年里的某个时候，是本题的目标词。"}, {"text": "十届", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。"}, {"text": "诗界", "is_correct": false, "explanation": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。"}, {"text": "失节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。"}, {"text": "诗节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。"}], "explanations": {"时节": "时节（shí jié）指一年里的某个时候，是本题的目标词。", "十届": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。", "诗界": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。", "失节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。", "诗节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指一年中适合做某事的时候，与“最适合爬山”相合。"}, {"text": "人群", "is_correct": false, "explanation": "语义：“人群”指人，不指时间，“最适合爬山的人群”不成立。"}, {"text": "对象", "is_correct": false, "explanation": "语义：“对象”指所针对的人或事物，不表示季节，“最适合爬山的对象”不成立。"}, {"text": "时辰", "is_correct": false, "explanation": "语域：“时辰”是古代的计时单位，书面化，不用于描述季节。"}], "explanations": {"时节": "正确：“时节”指一年中适合做某事的时候，与“最适合爬山”相合。", "人群": "语义：“人群”指人，不指时间，“最适合爬山的人群”不成立。", "对象": "语义：“对象”指所针对的人或事物，不表示季节，“最适合爬山的对象”不成立。", "时辰": "语域：“时辰”是古代的计时单位，书面化，不用于描述季节。"}, "sentence_index": 6, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司第三时节的利润增加了。", "explanation": "这里应该用〈季度〉。时节不与“第三”这样的序数搭配来表示第几个季度。"}, {"text": "这项工作要花很多时节。", "explanation": "这里应该用〈时间〉。时节指一年中的某段时候，不能像时间那样用“很多”来计量时长。"}, {"text": "秦朝时节修建了长城的一部分。", "explanation": "这里应该用〈时期〉。历史阶段要说时期，时节多指一年中的某段时候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只适合游泳的时节。", "corrected_sentence": "这是一个适合游泳的时节。", "error_description": "量词错误：“时节”前应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在秋天的时节上，天气慢慢变凉。", "corrected_sentence": "在秋天的时节里，天气慢慢变凉。", "error_description": "方位词错误：“时节”是时间段，表示范围内应用“里”，“时节上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24544, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "灵活", "is_correct": true, "explanation": "灵活：能变通、不呆板，与僵化相对，适用于身体和想法。"}, {"text": "嘈杂", "is_correct": false, "explanation": "无关：嘈杂形容声音杂乱，与僵化没有反义关系。"}, {"text": "跳跃", "is_correct": false, "explanation": "无关：跳跃是动作，与僵化不构成反义。"}, {"text": "温暖", "is_correct": false, "explanation": "无关：温暖形容温度，与僵化不相对。"}], "correct_answer": "灵活", "explanations": {"灵活": "灵活：能变通、不呆板，与僵化相对，适用于身体和想法。", "嘈杂": "无关：嘈杂形容声音杂乱，与僵化没有反义关系。", "跳跃": "无关：跳跃是动作，与僵化不构成反义。", "温暖": "无关：温暖形容温度，与僵化不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24544, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "灵活", "is_correct": true, "explanation": "灵活：不呆板、能变通，与僵化相对。"}, {"text": "飘扬", "is_correct": false, "explanation": "无关：飘扬形容旗帜等随风摆动，与僵化没有反义关系。"}, {"text": "湿润", "is_correct": false, "explanation": "无关：湿润形容潮湿，与僵化不相对。"}, {"text": "清脆", "is_correct": false, "explanation": "无关：清脆形容声音，与僵化不构成反义。"}], "correct_answer": "灵活", "explanations": {"灵活": "灵活：不呆板、能变通，与僵化相对。", "飘扬": "无关：飘扬形容旗帜等随风摆动，与僵化没有反义关系。", "湿润": "无关：湿润形容潮湿，与僵化不相对。", "清脆": "无关：清脆形容声音，与僵化不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得硬邦邦，不能动；也指想法固定不变，不灵活。", "primary_collocate": null, "pronunciation": "jiāng huà", "ipa": "tɕjɑŋ˥ xu̯ɑ˥˩", "syllable_count": 2, "sentences": [{"text": "关节长时间不活动，就容易僵化。", "target_word": "僵化", "complexity_tier": "T3", "furigana": "guānjié cháng shíjiān bù huódòng, jiù róngyì jiānghuà.", "sentence_source": "generated"}, {"text": "这种病会让肌肉逐渐僵化。", "target_word": "僵化", "complexity_tier": "T3", "furigana": "zhè zhǒng bìng huì ràng jīròu zhújiàn jiānghuà.", "sentence_source": "generated"}, {"text": "他的想法一直不变，越来越僵化。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼死后，身体很快就会僵化。", "target_word": "僵化", "complexity_tier": "T3", "furigana": "yú sǐ hòu, shēntǐ hěn kuài jiù huì jiānghuà.", "sentence_source": "generated"}, {"text": "思想僵化的人，总是不听别人的话。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法太僵化了，我们换一种试试。", "target_word": "僵化", "complexity_tier": "T3", "furigana": "zhè ge bànfǎ tài jiānghuà le, wǒmen huàn yì zhǒng shìshi.", "sentence_source": "generated"}, {"text": "长期伏案工作，颈椎容易僵化。", "target_word": "僵化", "complexity_tier": "T3", "furigana": "cháng qī fú àn gōngzuò, jǐngzhuī róngyì jiānghuà.", "sentence_source": "generated"}, {"text": "他的表情僵化了，半天说不出话。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的观念僵化，不容易接受新东西。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习方法僵化，成绩就提高得很慢。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "僵化了", "label": "体标"}], "register": "中性", "sense_fingerprint": "僵化：身体或事物变硬不能动；想法固定不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24544, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化（jiānghuà）：身体或事物变硬不能动，也指想法固定不变。"}, {"text": "讲话", "is_correct": false, "explanation": "讲话（jiǎnghuà）第一个音节为第三声，与 jiāng（第一声）声调不同，意思是说话。"}, {"text": "强化", "is_correct": false, "explanation": "强化（qiánghuà）声母为 q，与 j 不同，意思是加强。"}, {"text": "钢化", "is_correct": false, "explanation": "钢化（gānghuà）声母为 g，与 j 不同，意思是经过处理使材料更坚硬。"}, {"text": "姜花", "is_correct": false, "explanation": "姜花（jiānghuā）末字为第一声 huā，与 huà（第四声）声调不同，意思是一种植物。"}], "explanations": {"僵化": "僵化（jiānghuà）：身体或事物变硬不能动，也指想法固定不变。", "讲话": "讲话（jiǎnghuà）第一个音节为第三声，与 jiāng（第一声）声调不同，意思是说话。", "强化": "强化（qiánghuà）声母为 q，与 j 不同，意思是加强。", "钢化": "钢化（gānghuà）声母为 g，与 j 不同，意思是经过处理使材料更坚硬。", "姜花": "姜花（jiānghuā）末字为第一声 huā，与 huà（第四声）声调不同，意思是一种植物。"}, "sentence_index": null, "correct_answer": "僵化"}, "level_3": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化：关节因长时间不动变硬，不能灵活活动，句中合理。"}, {"text": "生长", "is_correct": false, "explanation": "语义：关节不会生长，“容易生长”与句意不符。"}, {"text": "发亮", "is_correct": false, "explanation": "语义：关节不能发亮，“容易发亮”说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：关节与唱歌没有搭配关系，“容易唱歌”不成立。"}], "explanations": {"僵化": "僵化：关节因长时间不动变硬，不能灵活活动，句中合理。", "生长": "语义：关节不会生长，“容易生长”与句意不符。", "发亮": "语义：关节不能发亮，“容易发亮”说不通。", "唱歌": "搭配：关节与唱歌没有搭配关系，“容易唱歌”不成立。"}, "sentence_index": 0, "correct_answer": "僵化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰块在太阳下很快僵化了。", "explanation": "这里把〈僵化〉当成〈冻结〉（水变成冰、变硬）的意思来用于冰块；冰块在太阳下是融化，不是变硬不动。"}, {"text": "这件衣服的颜色很僵化，我不太喜欢。", "explanation": "这里把〈僵化〉当成〈呆板〉来形容颜色；颜色可以呆板，但僵化只用于身体或思想、方法等，不能用于颜色。"}, {"text": "河水不断僵化，一直向东流。", "explanation": "这里把〈僵化〉当成〈结冰〉（水变硬）的意思来用于河水；河水是流动的，不会变硬，所以不能说僵化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化：长期保持一个姿势，颈椎变硬不能活动，句中合理。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：颈椎不会发烧，“容易发烧”与句意不符。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：颈椎与散步没有搭配关系，“容易散步”说不通。"}, {"text": "进步", "is_correct": false, "explanation": "语义：颈椎不会进步，“容易进步”与句意不符。"}], "explanations": {"僵化": "僵化：长期保持一个姿势，颈椎变硬不能活动，句中合理。", "发烧": "语义：颈椎不会发烧，“容易发烧”与句意不符。", "散步": "搭配：颈椎与散步没有搭配关系，“容易散步”说不通。", "进步": "语义：颈椎不会进步，“容易进步”与句意不符。"}, "sentence_index": 6, "correct_answer": "僵化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的光很僵化，屋子里很暗。", "explanation": "这里把〈僵化〉当成〈昏暗〉（描写光线的）来用；光线不会变得死板，僵化不能用来形容光。"}, {"text": "这碗汤的味道很僵化，大家都喝完了。", "explanation": "这里把〈僵化〉当成〈变味〉（味道走样）来用；味道不会变硬，僵化不能描述味觉。"}, {"text": "这把椅子的高度很僵化，一直没有变过。", "explanation": "这里把〈僵化〉当成〈稳定〉（不变）来形容高度；高度是尺寸，不会变得死板，僵化不用于描述尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长时间不动的话，关节就容易僵化着。", "corrected_sentence": "长时间不动的话，关节就容易僵化。", "error_description": "体标错误：“僵化”表示逐渐发生的变化，不能加“着”表示进行中的状态；此处应说“容易僵化”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的表情僵化地很厉害，大家都很担心。", "corrected_sentence": "他的表情僵化得很厉害，大家都很担心。", "error_description": "错误在补语标记：表示程度的补语要用结构助词“得”，不能用“地”；应说“僵化得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歉收", "is_correct": true, "explanation": "正确。“歉收”指农作物收成不好，与“丰收”相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“丰收”无反义关系，“睡觉”是休息的行为。"}, {"text": "跑步", "is_correct": false, "explanation": "与“丰收”无反义关系，“跑步”是一种体育运动。"}, {"text": "画画", "is_correct": false, "explanation": "与“丰收”无反义关系，“画画”指用笔或颜料作画。"}], "correct_answer": "歉收", "explanations": {"歉收": "正确。“歉收”指农作物收成不好，与“丰收”相反。", "睡觉": "与“丰收”无反义关系，“睡觉”是休息的行为。", "跑步": "与“丰收”无反义关系，“跑步”是一种体育运动。", "画画": "与“丰收”无反义关系，“画画”指用笔或颜料作画。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歉收", "is_correct": true, "explanation": "正确。“歉收”指农作物收成不好，与“丰收”相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“丰收”无反义关系，“跳舞”是一种身体活动。"}, {"text": "读书", "is_correct": false, "explanation": "与“丰收”无反义关系，“读书”指阅读书籍。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“丰收”无反义关系，“洗澡”是清洁身体的行为。"}], "correct_answer": "歉收", "explanations": {"歉收": "正确。“歉收”指农作物收成不好，与“丰收”相反。", "跳舞": "与“丰收”无反义关系，“跳舞”是一种身体活动。", "读书": "与“丰收”无反义关系，“读书”指阅读书籍。", "洗澡": "与“丰收”无反义关系，“洗澡”是清洁身体的行为。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "农民伯伯种的东西都收回家了，有很多。", "primary_collocate": null, "pronunciation": "fēng shōu", "ipa": "fɤŋ˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "农民伯伯今年丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天到了，田里的玉米丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷种的菜丰收了，吃不完。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "稻子丰收，农民伯伯很高兴。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年苹果丰收，树上挂满了红苹果。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丰收以后，大家一起吃新米饭。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，今年我们家的地丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下过雨，小麦长得好，一定会丰收。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天田里金黄一片，真是大丰收。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们帮农民伯伯庆祝丰收，一起收玉米。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丰收了", "label": "体标"}, {"form": "豐收", "label": "繁体"}], "register": "通用", "sense_fingerprint": "农民种的东西收回家，收成很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丰收", "is_correct": true, "explanation": "正确。“农民伯伯今年丰收了”是描述农事的结果，符合句意。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物开出花朵，主语不能是人。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能以“农民伯伯”为主语。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，不用于人。"}], "explanations": {"丰收": "正确。“农民伯伯今年丰收了”是描述农事的结果，符合句意。", "开花": "语义：“开花”指植物开出花朵，主语不能是人。", "下雨": "语义：“下雨”是天气现象，不能以“农民伯伯”为主语。", "生锈": "语义：“生锈”指金属被氧化，不用于人。"}, "sentence_index": 0, "correct_answer": "丰收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试考得很丰收。", "explanation": "这里应该用〈好〉。丰收用于农作物的收成，考试成绩要说“好”。"}, {"text": "这个孩子长得很丰收。", "explanation": "这里应该用〈健壮〉。丰收用于收成，不说人长得丰收，应说“健壮”。"}, {"text": "这座城市这几年丰收得很快。", "explanation": "这里应该用〈发展〉。丰收指农作物或成果的收成，城市的变化要说“发展”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丰收", "is_correct": true, "explanation": "正确。“今年我们家的地丰收了”描述农作物的收成，符合句意。"}, {"text": "搬家", "is_correct": false, "explanation": "搭配：“地”不能主动搬家，与“地”作主语的搭配不当。"}, {"text": "装修", "is_correct": false, "explanation": "语义：“装修”指房屋的修饰，不能用来说地的结果。"}, {"text": "出嫁", "is_correct": false, "explanation": "语义：“出嫁”指女子结婚，与“地”不相符。"}], "explanations": {"丰收": "正确。“今年我们家的地丰收了”描述农作物的收成，符合句意。", "搬家": "搭配：“地”不能主动搬家，与“地”作主语的搭配不当。", "装修": "语义：“装修”指房屋的修饰，不能用来说地的结果。", "出嫁": "语义：“出嫁”指女子结婚，与“地”不相符。"}, "sentence_index": 6, "correct_answer": "丰收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的能力很丰收，工作很出色。", "explanation": "这里应该用〈强〉。丰收只用于农作物或成果的收成，形容能力要说“强”，不能说“很丰收”。"}, {"text": "这个节日，大家都很丰收。", "explanation": "这里应该用〈快乐〉。丰收用于农作物或成果，不能描述人的心情。"}, {"text": "运动员们训练得很丰收。", "explanation": "这里应该用〈辛苦〉。丰收不描述训练的状态，训练的艰苦要说“辛苦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的稻子丰收着，农民都很开心。", "corrected_sentence": "今年的稻子丰收了，农民都很开心。", "error_description": "体标错误：表示收成已经完成要用“了”，说“丰收了”，不能用“着”说“丰收着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年我们村的玉米把丰收了。", "corrected_sentence": "今年我们村的玉米丰收了。", "error_description": "多余的“把”：“丰收”是不及物动词，不能用于“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
