INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫来用。", "primary_collocate": null, "pronunciation": "diào yòng", "ipa": "tjɑʊ̯˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "经理调用了三个人去帮忙。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总部调用了十辆车来运货。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察调用附近的人手去找孩子。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出差要用车，可以调用公司的车。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长调用了几个队员守在门口。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校调用了全部老师来照顾学生。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院调用了附近的医生来帮忙。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司从仓库调用了一批材料运到工地。", "target_word": "调用", "complexity_tier": "T3", "furigana": "gōng sī cóng cāng kù diào yòng le yī pī cái liào yùn dào gōng dì。", "sentence_source": "generated"}, {"text": "灾区需要帮助，政府调用了军队。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房人手不够，老板调用了服务员。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "调用了", "label": "体标"}, {"form": "调用过", "label": "体标"}, {"form": "調用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "调用：把人员、车辆、物资叫来使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调用", "is_correct": true, "explanation": "调用（diào yòng）指把人员、车辆、物资叫来使用，是本题的目标词。"}, {"text": "调运", "is_correct": false, "explanation": "第二音节 yùn 与 yòng 韵母不同（un 与 ong），声调相同，意思是调运物资。"}, {"text": "调养", "is_correct": false, "explanation": "第二音节 yǎng（第三声）与 yòng（第四声）韵母与声调都不同，意思是调养身体。"}, {"text": "调研", "is_correct": false, "explanation": "第二音节 yán（第二声）与 yòng 韵母与声调都不同，意思是调查研究。"}], "explanations": {"调用": "调用（diào yòng）指把人员、车辆、物资叫来使用，是本题的目标词。", "调运": "第二音节 yùn 与 yòng 韵母不同（un 与 ong），声调相同，意思是调运物资。", "调养": "第二音节 yǎng（第三声）与 yòng（第四声）韵母与声调都不同，意思是调养身体。", "调研": "第二音节 yán（第二声）与 yòng 韵母与声调都不同，意思是调查研究。"}, "sentence_index": null, "correct_answer": "调用"}, "level_3": {"options": [{"text": "调用", "is_correct": true, "explanation": "正确：“调用”表示调派人员，符合“经理……三个人去帮忙”的语境，只有它能填入空格。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”是解雇，与“去帮忙”的意思相矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器或物品，不能用于人。"}, {"text": "收购", "is_correct": false, "explanation": "搭配：“收购”用于物资或产业，不能用于人。"}], "explanations": {"调用": "正确：“调用”表示调派人员，符合“经理……三个人去帮忙”的语境，只有它能填入空格。", "辞退": "语义：“辞退”是解雇，与“去帮忙”的意思相矛盾。", "修理": "搭配：“修理”用于机器或物品，不能用于人。", "收购": "搭配：“收购”用于物资或产业，不能用于人。"}, "sentence_index": 0, "correct_answer": "调用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察调用了案件的经过。", "explanation": "这里应该用〈调查〉。调用指叫来人员或车辆等供自己使用，查看案件情况要说“调查”。"}, {"text": "他把旧衣服调用了。", "explanation": "这里应该用〈扔〉。调用不表示丢弃，丢掉东西要说“扔”。"}, {"text": "他调用了一件礼物。", "explanation": "这里应该用〈挑选〉。调用指调配已有的人员或物资，选择物品要说“挑选”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调用", "is_correct": true, "explanation": "正确：“调用”表示调派人员，符合“医院……医生来帮忙”的语境，只有它能填入空格。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：“逮捕”是抓人，与“来帮忙”的意思相矛盾。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“宣传”用于事物或观念，不能说“宣传医生”来帮忙。"}, {"text": "解剖", "is_correct": false, "explanation": "语义：“解剖”指剖开研究，与“来帮忙”的意思不相符。"}], "explanations": {"调用": "正确：“调用”表示调派人员，符合“医院……医生来帮忙”的语境，只有它能填入空格。", "逮捕": "语义：“逮捕”是抓人，与“来帮忙”的意思相矛盾。", "宣传": "搭配：“宣传”用于事物或观念，不能说“宣传医生”来帮忙。", "解剖": "语义：“解剖”指剖开研究，与“来帮忙”的意思不相符。"}, "sentence_index": 6, "correct_answer": "调用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他调用了房租。", "explanation": "这里应该用〈支付〉。调用不用于付款，付钱要说“支付”。"}, {"text": "他向老板调用了工作进度。", "explanation": "这里应该用〈报告〉。调用不表示汇报，汇报情况要说“报告”。"}, {"text": "他调用了一封信。", "explanation": "这里应该用〈写〉。调用不表示书写，写信要说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理昨天调用着三个人去帮忙。", "corrected_sentence": "经理昨天调用了三个人去帮忙。", "error_description": "体标错误：“昨天”指已完成的过去，“调用”的动作已经完成，应用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂昨天从仓库调用着一批零件。", "corrected_sentence": "工厂昨天从仓库调用了一批零件。", "error_description": "体标错误：“调用”指已经完成的动作，应用“了”；用“着”表示动作正在进行，与句意不符，应说“调用了一批零件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "口头", "is_correct": true, "explanation": "反义：书面指用写下来的话表示，口头指用说出来的话表示，两者相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“书面”没有反义关系，形容山坡或坡度很陡。"}, {"text": "柔和", "is_correct": false, "explanation": "与“书面”没有反义关系，形容光线或声音温和。"}, {"text": "湿润", "is_correct": false, "explanation": "与“书面”没有反义关系，形容含有水分。"}], "correct_answer": "口头", "explanations": {"口头": "反义：书面指用写下来的话表示，口头指用说出来的话表示，两者相对。", "陡峭": "与“书面”没有反义关系，形容山坡或坡度很陡。", "柔和": "与“书面”没有反义关系，形容光线或声音温和。", "湿润": "与“书面”没有反义关系，形容含有水分。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "口头", "is_correct": true, "explanation": "反义：书面指用写下来的话表示，口头指用说出来的话表示，两者相对。"}, {"text": "迟缓", "is_correct": false, "explanation": "与“书面”没有反义关系，形容动作或反应慢。"}, {"text": "狭窄", "is_correct": false, "explanation": "与“书面”没有反义关系，形容空间小。"}, {"text": "厚重", "is_correct": false, "explanation": "与“书面”没有反义关系，形容厚实或有分量。"}], "correct_answer": "口头", "explanations": {"口头": "反义：书面指用写下来的话表示，口头指用说出来的话表示，两者相对。", "迟缓": "与“书面”没有反义关系，形容动作或反应慢。", "狭窄": "与“书面”没有反义关系，形容空间小。", "厚重": "与“书面”没有反义关系，形容厚实或有分量。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用写下来的话表示的", "primary_collocate": null, "pronunciation": "shū miàn", "ipa": "ʂu˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "经理要我们提交书面材料。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书面通知已经发给每个人了。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事做了书面说明。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板同意了我的书面请假。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口头说不清楚，请写成书面的。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有书面证明吗？", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求家长书面同意。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把规定写成书面文件。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前要先交书面报名表。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一封书面道歉信。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "书面语", "label": "复合"}, {"form": "書面", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "用写下来的话表示的（书面材料、书面证明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57556918-9c49-4ffb-99f3-aee62b027b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书面", "is_correct": true, "explanation": "正确：书面指用写下来的话表示，修饰“材料”，与句意相符。"}, {"text": "口语", "is_correct": false, "explanation": "语域：“口语”属于说出来的语体，与写下来的“材料”冲突。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”多形容环境或声音，不能修饰“材料”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型，不能修饰“材料”。"}], "explanations": {"书面": "正确：书面指用写下来的话表示，修饰“材料”，与句意相符。", "口语": "语域：“口语”属于说出来的语体，与写下来的“材料”冲突。", "寂静": "搭配：“寂静”多形容环境或声音，不能修饰“材料”。", "高大": "体貌：“高大”形容体型，不能修饰“材料”。"}, "sentence_index": 0, "correct_answer": "书面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他书面地打断了老师的讲话。", "explanation": "这里应该用〈当面〉。打断讲话是当面进行的口头动作，“书面”指写下来的，两者矛盾。"}, {"text": "这块蛋糕很书面。", "explanation": "这里应该用〈精致〉。书面指用文字表达，不能形容蛋糕；蛋糕的精美要用“精致”。"}, {"text": "这场婚礼很书面。", "explanation": "这里应该用〈正式〉。书面指写下的，不指庄重；婚礼的庄重要用“正式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书面", "is_correct": true, "explanation": "正确：书面同意指用写下来的方式表示同意，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能修饰“同意”。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，与“同意”无关。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”多形容水或食物的温度，不能修饰“同意”。"}], "explanations": {"书面": "正确：书面同意指用写下来的方式表示同意，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，不能修饰“同意”。", "辛辣": "语义：“辛辣”形容味道，与“同意”无关。", "滚烫": "搭配：“滚烫”多形容水或食物的温度，不能修饰“同意”。"}, "sentence_index": 6, "correct_answer": "书面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他书面地和我握了手。", "explanation": "这里应该用〈热情〉。书面指写下来，不能修饰握手这样的身体动作；握手的态度要用“热情”。"}, {"text": "这辆车很书面。", "explanation": "这里应该用〈高级〉。书面指文字形式，不能形容车的档次；车的档次要用“高级”。"}, {"text": "她的笑容很书面。", "explanation": "这里应该用〈灿烂〉。书面指写下来的文字，不能形容笑容；笑容的样子要用“灿烂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经交了一书面材料。", "corrected_sentence": "他已经交了一份书面材料。", "error_description": "量词缺失：数量短语“一”后要加量词，“材料”应用“份”计量，应说“一份书面材料”，不能直接说“一书面材料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我收到了一份的书面通知。", "corrected_sentence": "我收到了一份书面通知。", "error_description": "结构助词错误：“一份”后不能直接加“的”，应说“一份书面通知”，“的”不能插在数量短语与修饰语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
