INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西没有了，完全不见了。", "primary_collocate": null, "pronunciation": "xiāo wáng", "ipa": "ɕiɑʊ˥ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种鸟在我们这里已经消亡了。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个古老的文明为什么会消亡？", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多老手艺正在消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个古老的部落在一百年前消亡了。", "target_word": "消亡", "complexity_tier": "T3", "furigana": "zhè ge gǔ lǎo de bù luò zài yì bǎi nián qián xiāo wáng le.", "sentence_source": "generated"}, {"text": "没有人学，这门手艺就会消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的风俗正在一点一点消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种昆虫几乎已经消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个古老的民族早已消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的老市场慢慢消亡了。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人保护，这片湿地会慢慢消亡。", "target_word": "消亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "消亡：书面动词，东西完全没有了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57556918-9c49-4ffb-99f3-aee62b027b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确答案：消亡（xiāo wáng），指东西完全不存在了。"}, {"text": "小王", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小王（年幼的国王或对人的称呼）。"}, {"text": "消防", "is_correct": false, "explanation": "fáng 与 wáng 声母不同（f 与 w），意思是消防（预防和扑救火灾）。"}, {"text": "妖王", "is_correct": false, "explanation": "yāo（第一声）与 xiāo 首音不同（y 与 x），意思是妖王（妖怪之王）。"}], "explanations": {"消亡": "正确答案：消亡（xiāo wáng），指东西完全不存在了。", "小王": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小王（年幼的国王或对人的称呼）。", "消防": "fáng 与 wáng 声母不同（f 与 w），意思是消防（预防和扑救火灾）。", "妖王": "yāo（第一声）与 xiāo 首音不同（y 与 x），意思是妖王（妖怪之王）。"}, "sentence_index": null, "correct_answer": "消亡"}, "level_3": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确：“消亡”指东西完全不存在了，与句中“已经……了”搭配自然。"}, {"text": "盛行", "is_correct": false, "explanation": "搭配：“盛行”用于风气、习俗、思潮等，不用于说鸟，“这种鸟已经盛行了”不通。"}, {"text": "逃亡", "is_correct": false, "explanation": "语义：“逃亡”指人为躲避追捕或战乱而离开，不用于鸟类在某地消失。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变为液体，多用于冰雪、黄油等，不用于鸟类。"}], "explanations": {"消亡": "正确：“消亡”指东西完全不存在了，与句中“已经……了”搭配自然。", "盛行": "搭配：“盛行”用于风气、习俗、思潮等，不用于说鸟，“这种鸟已经盛行了”不通。", "逃亡": "语义：“逃亡”指人为躲避追捕或战乱而离开，不用于鸟类在某地消失。", "融化": "语义：“融化”指固体遇热变为液体，多用于冰雪、黄油等，不用于鸟类。"}, "sentence_index": 0, "correct_answer": "消亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在昨天深夜消亡了。", "explanation": "这里应该用〈死亡〉。消亡用于事物不复存在，不用于人的去世。"}, {"text": "灯光在夜里消亡了。", "explanation": "这里应该用〈熄灭〉。灯光停止发亮用熄灭，消亡不用于此。"}, {"text": "声音渐渐消亡了。", "explanation": "这里应该用〈消逝〉。声音逐渐远去、听不见用消逝，消亡不用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24554, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确答案：消亡（xiāo wáng），指东西完全不存在了。"}, {"text": "销往", "is_correct": false, "explanation": "wǎng（第三声）与 wáng（第二声）声调不同，意思是销往（卖到某地）。"}, {"text": "消长", "is_correct": false, "explanation": "cháng（第二声）与 wáng 声母不同（ch 与 w），意思是消长（增减与盛衰）。"}, {"text": "先王", "is_correct": false, "explanation": "xiān（第一声）与 xiāo 韵母不同（ian 与 iao），意思是先王（已故的君王）。"}], "explanations": {"消亡": "正确答案：消亡（xiāo wáng），指东西完全不存在了。", "销往": "wǎng（第三声）与 wáng（第二声）声调不同，意思是销往（卖到某地）。", "消长": "cháng（第二声）与 wáng 声母不同（ch 与 w），意思是消长（增减与盛衰）。", "先王": "xiān（第一声）与 xiāo 韵母不同（ian 与 iao），意思是先王（已故的君王）。"}, "sentence_index": null, "correct_answer": "消亡"}, "level_3": {"options": [{"text": "消亡", "is_correct": true, "explanation": "正确：“消亡”指东西完全不存在了，与“几乎已经”搭配自然。"}, {"text": "加剧", "is_correct": false, "explanation": "语义：“加剧”多指矛盾、问题、疾病等负面情况加重，不用于昆虫。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书籍、报刊，不能说“这种昆虫几乎已经出版了”。"}, {"text": "扑灭", "is_correct": false, "explanation": "配价：“扑灭”是及物动词，需要施事和受事，不能说“这种昆虫几乎已经扑灭了”（应说“被扑灭”）。"}], "explanations": {"消亡": "正确：“消亡”指东西完全不存在了，与“几乎已经”搭配自然。", "加剧": "语义：“加剧”多指矛盾、问题、疾病等负面情况加重，不用于昆虫。", "出版": "搭配：“出版”的对象是书籍、报刊，不能说“这种昆虫几乎已经出版了”。", "扑灭": "配价：“扑灭”是及物动词，需要施事和受事，不能说“这种昆虫几乎已经扑灭了”（应说“被扑灭”）。"}, "sentence_index": 6, "correct_answer": "消亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "潮水慢慢消亡了。", "explanation": "这里应该用〈消退〉。潮水、热度、肿胀逐渐减退用消退；消亡只用于事物彻底不存在。"}, {"text": "雨渐渐消亡了。", "explanation": "这里应该用〈停歇〉。雨、风等停止用停歇，消亡不用于自然现象的暂时停止。"}, {"text": "观众渐渐消亡了。", "explanation": "这里应该用〈散去〉。观众、人群离开用散去，消亡不用于人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那种鸟在山里被消亡了。", "corrected_sentence": "那种鸟在山里消亡了。", "error_description": "错误：“被消亡”。“消亡”是不及物动词，不能加“被”构成被动句；应说“那种鸟在山里消亡了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种昆虫把消亡了。", "corrected_sentence": "这种昆虫消亡了。", "error_description": "错误：“把消亡”。“消亡”是不及物动词，不能用于把字句；应去掉“把”，说“这种昆虫消亡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
