INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24558, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情没有发生，比如‘我没有去’。", "primary_collocate": null, "pronunciation": "bìng wèi", "ipa": "pɪŋ˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我并未去过那家餐馆。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应了，却并未来。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚我并未睡着。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我并未看完。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹并未收到你的信。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们并未按时到达。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车并未晚点。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板并未同意我的请求。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店今天并未开门。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我并未忘记我们的约定。", "target_word": "并未", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "并未：书面副词，表示事情没有发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57556918-9c49-4ffb-99f3-aee62b027b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并未", "is_correct": true, "explanation": "正确：“并未”否定“去过”这类经历，表示事情没有发生。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，与“去过”表示的经历不搭配。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将发生，与“去过”已有的经历矛盾。"}, {"text": "将", "is_correct": false, "explanation": "语义：“将”指将来，与“去过”已有的经历矛盾。"}], "explanations": {"并未": "正确：“并未”否定“去过”这类经历，表示事情没有发生。", "正在": "搭配：“正在”表示动作进行中，与“去过”表示的经历不搭配。", "马上": "语义：“马上”表示即将发生，与“去过”已有的经历矛盾。", "将": "语义：“将”指将来，与“去过”已有的经历矛盾。"}, "sentence_index": 0, "correct_answer": "并未"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这并未是我的书。", "explanation": "这里应该用〈并不是〉。并未表示事情没有发生，判断句“是……”的否定要用〈并不是〉。"}, {"text": "明天他并未来。", "explanation": "这里应该用〈不会〉。并未用于已经发生的事，“明天”指将来，要用〈不会〉。"}, {"text": "他并未太喜欢运动。", "explanation": "这里应该用〈不太〉。并未否定已经发生的状态，“太喜欢”是程度搭配，要用〈不太〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并未", "is_correct": true, "explanation": "正确：“并未”否定“晚点”这一已发生的结果，表示火车没有误点。"}, {"text": "亲自", "is_correct": false, "explanation": "配价：“亲自”要求施事者是人，火车不能亲自晚点。"}, {"text": "故意", "is_correct": false, "explanation": "语义：火车没有意志，不能“故意”晚点。"}, {"text": "由于", "is_correct": false, "explanation": "语法：“由于”引出原因，需接结果分句，不能直接放在“火车”后修饰“晚点”，句子不成立。"}], "explanations": {"并未": "正确：“并未”否定“晚点”这一已发生的结果，表示火车没有误点。", "亲自": "配价：“亲自”要求施事者是人，火车不能亲自晚点。", "故意": "语义：火车没有意志，不能“故意”晚点。", "由于": "语法：“由于”引出原因，需接结果分句，不能直接放在“火车”后修饰“晚点”，句子不成立。"}, "sentence_index": 6, "correct_answer": "并未"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "要是下雨，我们就并未去公园。", "explanation": "这里应该用〈不〉。并未只否定已经发生的事，假设中的将来情况要用〈不〉。"}, {"text": "我并未太会游泳。", "explanation": "这里应该用〈不太会〉。并未只否定已经发生的事，“太会游泳”是程度搭配，要用〈不太会〉。"}, {"text": "我每天都并未太喝水。", "explanation": "这里应该用〈不太〉。并未否定已经发生的动作，“太”表示程度，要用〈不太〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他也没并未来过这里。", "corrected_sentence": "他也并未来过这里。", "error_description": "“没并未”双重否定：“并未”已表示否定，前面不能再加“没”，应为“他也并未来过这里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很并未忘记他的生日。", "corrected_sentence": "我并未忘记他的生日。", "error_description": "“很并未”错误：“并未”是否定副词，不能受程度副词“很”修饰，应去掉“很”，为“我并未忘记他的生日”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
