INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以听节目、故事和谈话的手机上的东西。", "primary_collocate": null, "pronunciation": "bō kè", "ipa": "pwo˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我手机里有一个听故事的播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在手机上打开播客，听了一个故事。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用手机上的播客学英语。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个播客很好听，我每天都听。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐地铁的时候，我喜欢听播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你手机里有没有好听的播客？", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在播客上听到了一场有趣的谈话。", "target_word": "播客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸睡觉前总要听一会儿播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把新的播客下载到了手机里。", "target_word": "播客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个播客里有很多讲给孩子听的故事。", "target_word": "播客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "期", "label": "量词"}, {"form": "播客软件", "label": "复合"}], "register": "口语", "sense_fingerprint": "播客：手机上用来听节目、故事和谈话的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40485493-8204-4e56-be10-c71e2455482f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客指手机上可以收听节目和故事的内容。"}, {"text": "博客", "is_correct": false, "explanation": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。"}, {"text": "播音", "is_correct": false, "explanation": "“播音”的第二音节是 yīn，与 kè 的声母和韵母都不同，意思是播送声音。"}, {"text": "播报", "is_correct": false, "explanation": "“播报”的第二音节是 bào，与 kè 不同，意思是播送新闻或报道。"}, {"text": "播放", "is_correct": false, "explanation": "“播放”的第二音节是 fàng，与 kè 不同，意思是放送影音内容。"}, {"text": "拨开", "is_correct": false, "explanation": "“拨开”的第二音节是 kāi，与 kè 不同，意思是用手把东西分开。"}, {"text": "播出", "is_correct": false, "explanation": "“播出”的第二音节是 chū，与 kè 不同，意思是把节目播送出去。"}], "explanations": {"播客": "正确：播客指手机上可以收听节目和故事的内容。", "博客": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。", "播音": "“播音”的第二音节是 yīn，与 kè 的声母和韵母都不同，意思是播送声音。", "播报": "“播报”的第二音节是 bào，与 kè 不同，意思是播送新闻或报道。", "播放": "“播放”的第二音节是 fàng，与 kè 不同，意思是放送影音内容。", "拨开": "“拨开”的第二音节是 kāi，与 kè 不同，意思是用手把东西分开。", "播出": "“播出”的第二音节是 chū，与 kè 不同，意思是把节目播送出去。"}, "sentence_index": null, "correct_answer": "播客"}, "level_3": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客是手机上可以收听故事和节目的内容，与“听故事的”相合。"}, {"text": "相册", "is_correct": false, "explanation": "语义：相册用来存放照片，不能用来听故事。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能播放故事，也不能存在于手机里。"}, {"text": "讲台", "is_correct": false, "explanation": "搭配：“手机里有一个……”需要可以装在手机中的内容，“讲台”不能与之搭配。"}], "explanations": {"播客": "正确：播客是手机上可以收听故事和节目的内容，与“听故事的”相合。", "相册": "语义：相册用来存放照片，不能用来听故事。", "冰箱": "语义：冰箱是家用电器，不能播放故事，也不能存在于手机里。", "讲台": "搭配：“手机里有一个……”需要可以装在手机中的内容，“讲台”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "播客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天在地铁站门口把播客卖给路人。", "explanation": "这里应该用〈报纸〉。报纸是实物，可以在地铁站卖给路人；播客是手机上的节目，不能这样卖。"}, {"text": "我每天用播客看电影。", "explanation": "这里应该用〈视频〉。播客是音频节目，只能用来收听，不能当视频来看电影。"}, {"text": "我把播客放在厨房的桌子上。", "explanation": "这里应该用〈音箱〉。音箱是实物，可以放在桌子上；播客是手机上的内容，不是实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24560, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客指手机上可以收听的节目和故事。"}, {"text": "拨款", "is_correct": false, "explanation": "“拨款”的第二音节是 kuǎn，与 kè 的韵母和声调都不同，意思是拨给资金。"}, {"text": "菠菜", "is_correct": false, "explanation": "“菠菜”的第二音节是 cài，与 kè 不同，意思是一种蔬菜。"}, {"text": "波浪", "is_correct": false, "explanation": "“波浪”的第二音节是 làng，与 kè 不同，意思是水面起伏的水流。"}, {"text": "播种", "is_correct": false, "explanation": "“播种”的第二音节是 zhǒng，与 kè 不同，意思是把种子撒到土里。"}, {"text": "博客", "is_correct": false, "explanation": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。"}], "explanations": {"播客": "正确：播客指手机上可以收听的节目和故事。", "拨款": "“拨款”的第二音节是 kuǎn，与 kè 的韵母和声调都不同，意思是拨给资金。", "菠菜": "“菠菜”的第二音节是 cài，与 kè 不同，意思是一种蔬菜。", "波浪": "“波浪”的第二音节是 làng，与 kè 不同，意思是水面起伏的水流。", "播种": "“播种”的第二音节是 zhǒng，与 kè 不同，意思是把种子撒到土里。", "博客": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。"}, "sentence_index": null, "correct_answer": "播客"}, "level_3": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客是手机上可以收听节目的内容，“在播客上听到”符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是盛放花的器皿，不能发出谈话的声音，句中“听到”一场谈话说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是用来写字的，不会发出可以听到的谈话。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图用来查看位置，不能播放谈话。"}], "explanations": {"播客": "正确：播客是手机上可以收听节目的内容，“在播客上听到”符合句意。", "花瓶": "语义：花瓶是盛放花的器皿，不能发出谈话的声音，句中“听到”一场谈话说不通。", "黑板": "语义：黑板是用来写字的，不会发出可以听到的谈话。", "地图": "语义：地图用来查看位置，不能播放谈话。"}, "sentence_index": 6, "correct_answer": "播客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个播客里有很多讲给孩子看的图画。", "explanation": "这里应该用〈绘本〉。绘本有图画可以看，播客只有声音，没有可看的图画。"}, {"text": "这个播客每天早上九点开门营业。", "explanation": "这里应该用〈商店〉。“开门营业”是商店的事，播客是节目，不是营业场所。"}, {"text": "孩子饿了，我先让他吃这个播客。", "explanation": "这里应该用〈零食〉。“吃”只能用于食物，播客是节目，不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的手机上下载了一张听书的播客。", "corrected_sentence": "我的手机上下载了一个听书的播客。", "error_description": "量词错误：“一张听书的播客”应改为“一个听书的播客”。“张”用于平面物品，播客是手机上的节目，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天晚上都听一本播客，学习新词。", "corrected_sentence": "我每天晚上都听一个播客，学习新词。", "error_description": "量词错误：“一本播客”应改为“一个播客”。“本”用于书籍，播客是手机上的节目，应用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
