INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24564, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用嘴说出来，不是用笔写。", "primary_collocate": null, "pronunciation": "kǒu shù", "ipa": "kʰou̯˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "请你口述答案，不用写在纸上。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手受伤了，只好口述，让朋友帮他写。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信是爸爸口述，我帮他写的。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小不会写字，只能口述想法。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人口述了一生的经历，女儿认真地记着。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我口述作文，不用写在本子上。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机口述了事故的经过，警察在旁边写着。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把想法口述给秘书，秘书马上打了出来。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话比写字快，所以常常口述文章。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你口述，我来写，这样我们很快就能做完。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口述了", "label": "体标"}, {"form": "口述过", "label": "体标"}, {"form": "口述史", "label": "复合"}], "register": "中性", "sense_fingerprint": "口述：用嘴说出来，而不是动笔写", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口述", "is_correct": true, "explanation": "口述：用嘴说出来，与后句「不用写在纸上」相符。"}, {"text": "书写", "is_correct": false, "explanation": "语义：「书写」指用笔写字，与后句「不用写在纸上」矛盾。"}, {"text": "抄写", "is_correct": false, "explanation": "语义：「抄写」是照着原文写下，与「不用写在纸上」矛盾。"}, {"text": "默写", "is_correct": false, "explanation": "语义：「默写」是凭记忆写出来，与「不用写在纸上」矛盾。"}], "explanations": {"口述": "口述：用嘴说出来，与后句「不用写在纸上」相符。", "书写": "语义：「书写」指用笔写字，与后句「不用写在纸上」矛盾。", "抄写": "语义：「抄写」是照着原文写下，与「不用写在纸上」矛盾。", "默写": "语义：「默写」是凭记忆写出来，与「不用写在纸上」矛盾。"}, "sentence_index": 0, "correct_answer": "口述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他口述了一幅画。", "explanation": "这里应该用〈画〉。画是用笔或颜料作图，「口述」是用嘴说出话语，不能用来指作画。"}, {"text": "他用笔口述了这个故事。", "explanation": "这里应该用〈写〉。写是用笔记录文字，「口述」是用嘴说出，「用笔」与「口述」相矛盾，故此处应说写。"}, {"text": "他用手口述了这个故事。", "explanation": "这里应该用〈比划〉。比划是用手势表达，「口述」是用嘴说出，「用手」与「口述」相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口述", "is_correct": true, "explanation": "口述：用嘴说出来，此句中指司机口头讲述事故经过，与后句「警察在旁边写着」相符。"}, {"text": "签署", "is_correct": false, "explanation": "搭配：「签署」用于文件、协议，不能用于「事故的经过」。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：「装订」用于书册、文件，与「事故的经过」搭配不通。"}, {"text": "报销", "is_correct": false, "explanation": "语义：「报销」指凭票据领回费用，事故经过不能报销，句意不通。"}], "explanations": {"口述": "口述：用嘴说出来，此句中指司机口头讲述事故经过，与后句「警察在旁边写着」相符。", "签署": "搭配：「签署」用于文件、协议，不能用于「事故的经过」。", "装订": "搭配：「装订」用于书册、文件，与「事故的经过」搭配不通。", "报销": "语义：「报销」指凭票据领回费用，事故经过不能报销，句意不通。"}, "sentence_index": 6, "correct_answer": "口述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈口述了一个苹果。", "explanation": "这里应该用〈吃〉。吃是把食物送入口中，「口述」只用于说出话语或内容，苹果是实物，不能口述。"}, {"text": "老师口述了一瓶牛奶。", "explanation": "这里应该用〈端〉。端是用手托着实物，「口述」只用于说出话语或内容，牛奶是实物，不能口述。"}, {"text": "他口述了一把椅子。", "explanation": "这里应该用〈搬〉。搬是移动实物，「口述」只用于说出话语或内容，椅子是实物，不能口述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他口述很清楚。", "corrected_sentence": "他口述得很清楚。", "error_description": "补语错误：状态补语前要加「得」，应说「口述得很清楚」，不说「口述很清楚」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机把事故经过口述了警察。", "corrected_sentence": "司机把事故经过口述给了警察。", "error_description": "漏掉了介词「给」：「口述」后要用「给」引出听话的人，应说「口述给了警察」，不能直接说「口述了警察」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
