INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回归就是回到原来的地方。", "primary_collocate": null, "pronunciation": "huí guī", "ipa": "xweɪ˧˥ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "鲑鱼长大后会回归出生的河流。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，燕子回归旧巢。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行结束，我们回归自己的城市。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退休后回归故乡。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长带着船员回归港口。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船顺利回归地球。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离家二十年，他终于回归老家。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祖父晚年时回归了自己的童年小镇。", "target_word": "回归", "complexity_tier": "T3", "furigana": "zǔ fù wǎn nián shí huí guī le zì jǐ de tóng nián xiǎo zhèn.", "sentence_source": "generated"}, {"text": "大雁秋天会回归南方。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束，难民陆续回归家园。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "回归：动词，回到原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57556918-9c49-4ffb-99f3-aee62b027b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确：“回归”指回到原来的地方，鲑鱼回到出生的河流，符合语境。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：“诞生”是不及物动词，不带宾语，不能说“会诞生出生的河流”。"}, {"text": "生育", "is_correct": false, "explanation": "搭配：“生育”的对象是后代，河流不能被“生育”。"}, {"text": "盛行", "is_correct": false, "explanation": "搭配：“盛行”用于风气、潮流，不能用于鱼类与河流的关系。"}], "explanations": {"回归": "正确：“回归”指回到原来的地方，鲑鱼回到出生的河流，符合语境。", "诞生": "配价：“诞生”是不及物动词，不带宾语，不能说“会诞生出生的河流”。", "生育": "搭配：“生育”的对象是后代，河流不能被“生育”。", "盛行": "搭配：“盛行”用于风气、潮流，不能用于鱼类与河流的关系。"}, "sentence_index": 0, "correct_answer": "回归"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次回归这座陌生的小城。", "explanation": "这里应该用〈抵达〉。回归指回到原来的地方，这座小城他从未去过，不能说回归；第一次到某地应说抵达。"}, {"text": "她在海边回归了一周。", "explanation": "这里应该用〈逗留〉。回归表示回到原处，不表示在某地停留多久。"}, {"text": "他们回归了新的时代。", "explanation": "这里应该用〈进入〉。回归指回到原来的状态，开启新的时代应说进入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确：“回归”指回到原来的地方，与“离家二十年”后回到老家相合。"}, {"text": "替代", "is_correct": false, "explanation": "语义：“替代”要说明替代了谁或什么，“他终于替代老家”与语境不符。"}, {"text": "降临", "is_correct": false, "explanation": "搭配：“降临”多与夜幕、幸福、灾难等从外而来的事搭配，不用于人回到老家。"}, {"text": "侵入", "is_correct": false, "explanation": "语义：“侵入”含入侵之意，与离家多年后正当回去的情况不合。"}], "explanations": {"回归": "正确：“回归”指回到原来的地方，与“离家二十年”后回到老家相合。", "替代": "语义：“替代”要说明替代了谁或什么，“他终于替代老家”与语境不符。", "降临": "搭配：“降临”多与夜幕、幸福、灾难等从外而来的事搭配，不用于人回到老家。", "侵入": "语义：“侵入”含入侵之意，与离家多年后正当回去的情况不合。"}, "sentence_index": 6, "correct_answer": "回归"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把借来的自行车回归给了朋友。", "explanation": "这里应该用〈归还〉。回归指事物自己回到原处，不用于把借来的东西还给别人；归还借物要用归还。"}, {"text": "老板今天回归了员工的工资。", "explanation": "这里应该用〈发放〉。回归指回到原处，不表示把工资发给员工；给员工发工资要用发放。"}, {"text": "老师把批改好的作业回归了学生。", "explanation": "这里应该用〈发还〉。回归指回到原来的位置，不表示把作业发还给学生；把批改好的作业还给学生要用发还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小船终于被回归港口了。", "corrected_sentence": "小船终于回归港口了。", "error_description": "错误：“被回归”。“回归”是不及物动词，不能加“被”构成被动句；应说“小船终于回归港口了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母晚年时回归老家来了。", "corrected_sentence": "祖母晚年时回归老家了。", "error_description": "错误：“回归……来”。“回归”表示回到原处，不带“来”；“来”属于“回来”，应去掉，说“祖母晚年时回归老家了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24570, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
