INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人在那个地方。", "primary_collocate": null, "pronunciation": "zài chǎng", "ipa": "tsaɪ̯˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他昨天不在场，没看到比赛。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在场的时候，同学们都很安静。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在场的朋友们一起鼓掌。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出事时我不在场，所以不清楚。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次聚会，大家都在场。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有你在场，我就放心了。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在场的时候，没有人说话。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好多记者都在场，等着拍照。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子打针时，妈妈一直在场。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你当时在场吗？", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "在场的", "label": "定语形式"}, {"form": "不在场", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "在场：人就在那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40485493-8204-4e56-be10-c71e2455482f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方。"}, {"text": "在唱", "is_correct": false, "explanation": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}, {"text": "再长", "is_correct": false, "explanation": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。"}, {"text": "在上", "is_correct": false, "explanation": "“在上”的第二音节是 shàng，与 chǎng 不同，意思是在上面。"}, {"text": "在做", "is_correct": false, "explanation": "“在做”的第二音节是 zuò，与 chǎng 不同，意思是正在做事。"}], "explanations": {"在场": "正确：在场指人处在那个地方。", "在唱": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。", "再长": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。", "在上": "“在上”的第二音节是 shàng，与 chǎng 不同，意思是在上面。", "在做": "“在做”的第二音节是 zuò，与 chǎng 不同，意思是正在做事。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方，这里指没有到比赛现场，与“没看到比赛”一致。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：“不缺席”表示人到了，与“没看到比赛”自相矛盾。"}, {"text": "投票", "is_correct": false, "explanation": "语义：投票与看比赛无关，句意不通。"}, {"text": "作曲", "is_correct": false, "explanation": "搭配：“没看到比赛”的原因应与比赛相关，“作曲”与之没有搭配关系。"}], "explanations": {"在场": "正确：在场指人处在那个地方，这里指没有到比赛现场，与“没看到比赛”一致。", "缺席": "语义：“不缺席”表示人到了，与“没看到比赛”自相矛盾。", "投票": "语义：投票与看比赛无关，句意不通。", "作曲": "搭配：“没看到比赛”的原因应与比赛相关，“作曲”与之没有搭配关系。"}, "sentence_index": 0, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河在场，把两岸隔开了。", "explanation": "这里应该用〈横在〉。在场只用于人，河流不能“在场”，应说“横在”。"}, {"text": "那台电脑在场，一直开着。", "explanation": "这里应该用〈放着〉。在场只用于人；电脑是物品，应说“放着”。"}, {"text": "那棵大树在场，挡住了阳光。", "explanation": "这里应该用〈立着〉。在场只用于人；大树是植物，应说“立着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方。"}, {"text": "再说", "is_correct": false, "explanation": "“再说”的第二音节是 shuō，与 chǎng 不同，意思是之后再讲。"}, {"text": "在家", "is_correct": false, "explanation": "“在家”的第二音节是 jiā，与 chǎng 不同，意思是待在家里。"}, {"text": "在学", "is_correct": false, "explanation": "“在学”的第二音节是 xué，与 chǎng 不同，意思是正在学习。"}, {"text": "在写", "is_correct": false, "explanation": "“在写”的第二音节是 xiě，与 chǎng 不同，意思是正在书写。"}, {"text": "在唱", "is_correct": false, "explanation": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}], "explanations": {"在场": "正确：在场指人处在那个地方。", "再说": "“再说”的第二音节是 shuō，与 chǎng 不同，意思是之后再讲。", "在家": "“在家”的第二音节是 jiā，与 chǎng 不同，意思是待在家里。", "在学": "“在学”的第二音节是 xué，与 chǎng 不同，意思是正在学习。", "在写": "“在写”的第二音节是 xiě，与 chǎng 不同，意思是正在书写。", "在唱": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方，这里说他在场时没有人说话，符合句意。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”用于活动、展览等，不能说“他开幕的时候”，句子不通。"}, {"text": "吵架", "is_correct": false, "explanation": "搭配：“没有人说话”与“吵架”的情境不相容，不能与之搭配。"}, {"text": "玩耍", "is_correct": false, "explanation": "语域：“玩耍”较口语化，与句中的叙述语境不协调。"}], "explanations": {"在场": "正确：在场指人处在那个地方，这里说他在场时没有人说话，符合句意。", "开幕": "搭配：“开幕”用于活动、展览等，不能说“他开幕的时候”，句子不通。", "吵架": "搭配：“没有人说话”与“吵架”的情境不相容，不能与之搭配。", "玩耍": "语域：“玩耍”较口语化，与句中的叙述语境不协调。"}, "sentence_index": 6, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那张桌子也在场，看着大家吵架。", "explanation": "这里不能用〈在场〉。在场只用于人，指人亲身处在某地；桌子是物品，应说“放在”。"}, {"text": "这盆花昨天一直在场。", "explanation": "这里不能用〈在场〉。在场只用于人；花是植物，不能亲身处在某地，应说“摆在”。"}, {"text": "这块石头在场，没人注意到。", "explanation": "这里不能用〈在场〉。在场只用于人；石头是物品，应说“落在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹那天很在场，错过了表演。", "corrected_sentence": "我妹妹那天不在场，错过了表演。", "error_description": "否定词错误：“很在场”应改为“不在场”。“在场”不能用程度副词“很”修饰；表示人没有到场，要用否定词“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开庭那天，律师和证人都在场上。", "corrected_sentence": "开庭那天，律师和证人都在场。", "error_description": "多余的方位词：“在场上”指在场地或球场上，开庭的场合应说“在场”，不加“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
