INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "摸起来的感觉。", "primary_collocate": null, "pronunciation": "zhì gǎn", "ipa": "ʈʂɻ̩˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条毛巾摸起来，质感又软又厚。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这本书纸张的质感，摸着很舒服。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮沙发的质感比布沙发硬一点。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸桌子，想知道木头的质感。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料的质感很差，摸起来很滑。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿的衣服要选质感软的布。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭着眼睛，用手指感受石头的质感。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块丝巾的质感很细，像水一样。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机壳的质感粗粗的，不容易滑掉。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我爱穿羊毛衫，它的质感很暖。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "質感", "label": "繁体"}, {"form": "一种质感", "label": "量词"}], "register": "中性", "sense_fingerprint": "用手触摸物体时的软硬粗细等感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40485493-8204-4e56-be10-c71e2455482f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指摸起来的感觉，与「摸起来」「又软又厚」相呼应，说的是毛巾的触感。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：「颜色」是视觉上的色彩，不能用手摸出来，也不能说「又软又厚」。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：「亮度」指光线的明暗，与「摸起来」所指的触觉不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「价格」不能和「软」「厚」搭配，句中说的是毛巾的触感，不是价钱。"}], "explanations": {"质感": "「质感」指摸起来的感觉，与「摸起来」「又软又厚」相呼应，说的是毛巾的触感。", "颜色": "体貌：「颜色」是视觉上的色彩，不能用手摸出来，也不能说「又软又厚」。", "亮度": "语义：「亮度」指光线的明暗，与「摸起来」所指的触觉不符。", "价格": "搭配：「价格」不能和「软」「厚」搭配，句中说的是毛巾的触感，不是价钱。"}, "sentence_index": 0, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台收音机的质感很大，隔壁都听得见。", "explanation": "这里应该用〈音量〉。「质感」指摸起来的感觉，不能用来说声音的大小；声音的大小要用「音量」。"}, {"text": "这杯水的质感很高，要小心烫。", "explanation": "这里应该用〈温度〉。「质感」指摸起来的感觉，不能用来说水的冷热，「温度」才是。"}, {"text": "这个箱子的质感很大，搬起来很费力。", "explanation": "这里应该用〈重量〉。「质感」指表面的感觉，不能用来说物体的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指摸起来的软硬粗细等感觉，闭着眼睛用手指去感受，正好对应触觉。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」靠口和鼻子感知，用手指感受不到味道。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：「寿命」指存在的年限，不能用手指去感受。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：「感受」后面接「数量」说不通，石头的数量不能靠手指感受。"}], "explanations": {"质感": "「质感」指摸起来的软硬粗细等感觉，闭着眼睛用手指去感受，正好对应触觉。", "味道": "语义：「味道」靠口和鼻子感知，用手指感受不到味道。", "寿命": "语义：「寿命」指存在的年限，不能用手指去感受。", "数量": "搭配：「感受」后面接「数量」说不通，石头的数量不能靠手指感受。"}, "sentence_index": 6, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件羊毛衫的质感很鲜艳，我很喜欢。", "explanation": "这里应该用〈颜色〉。「质感」指摸起来的感觉，不能用来形容颜色鲜不鲜艳。"}, {"text": "这件羊毛衫的质感很长，穿了三年也没坏。", "explanation": "这里应该用〈寿命〉。「质感」不能用来说衣服能穿多久，「寿命」才是。"}, {"text": "这碗汤的质感很鲜，我喝了两碗。", "explanation": "这里应该用〈味道〉。「质感」指摸起来的感觉，不能用来说食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条毛巾有一颗很软的质感，摸起来很舒服。", "corrected_sentence": "这条毛巾有一种很软的质感，摸起来很舒服。", "error_description": "「质感」是抽象名词，量词应用「种」。「颗」用于圆形的小东西，用来计量「质感」是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子有一颗光滑的质感，摸起来很舒服。", "corrected_sentence": "这张桌子有一种光滑的质感，摸起来很舒服。", "error_description": "量词错误：「质感」是抽象名词，量词应用「种」，不能用「颗」。「颗」用于圆形的小东西，不能用来计量「质感」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
