INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一种话变成另一种话。", "primary_collocate": null, "pronunciation": "zhuǎn yì", "ipa": "ʈʂwan˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "请你把他的话转译成中文。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在会上给外国客人转译老板的话。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友不会英文，我来帮他转译。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游一边走一边用英文转译景点的介绍。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把奶奶的方言转译成普通话。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话太长，我不会转译。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说的话，护士帮病人转译了。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把外语歌词转译给妈妈听。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转译得很快，大家都听懂了。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，小王负责转译客人的话。", "target_word": "转译", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轉譯", "label": "繁体"}, {"form": "转译了", "label": "体标"}, {"form": "转译过", "label": "体标"}], "register": "中性", "sense_fingerprint": "口头把一种话换成另一种话说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40485493-8204-4e56-be10-c71e2455482f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转译", "is_correct": true, "explanation": "「转译」指口头把一种话换成另一种话说出来，这里要求把他的话换成中文说。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指用水加热做熟食物，与把话换成另一种语言无关。"}, {"text": "染", "is_correct": false, "explanation": "搭配：「染」的对象是布料、头发等，不能和「他的话」搭配。"}, {"text": "折叠", "is_correct": false, "explanation": "语义：「折叠」指把东西叠起来，不能用来说把话换成中文。"}], "explanations": {"转译": "「转译」指口头把一种话换成另一种话说出来，这里要求把他的话换成中文说。", "煮": "语义：「煮」指用水加热做熟食物，与把话换成另一种语言无关。", "染": "搭配：「染」的对象是布料、头发等，不能和「他的话」搭配。", "折叠": "语义：「折叠」指把东西叠起来，不能用来说把话换成中文。"}, "sentence_index": 0, "correct_answer": "转译"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你把我的问候转译给他。", "explanation": "这里应该用〈转达〉。「转译」要把一种语言的话换成另一种语言说出来，这里只是传递问候，没有语言转换。"}, {"text": "我把这家店转译给了朋友。", "explanation": "这里应该用〈转让〉。「转译」指把一种话变成另一种话，店铺的买卖或产权转给别人要用「转让」。"}, {"text": "妈妈让我把这盒饼干转译给爸爸。", "explanation": "这里应该用〈转交〉。「转译」指把一种话变成另一种话，把东西交给别人要用「转交」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转译", "is_correct": true, "explanation": "「转译」指口头把一种话换成另一种话，护士把医生的专业话换成病人能听懂的话，正是这个意思。"}, {"text": "烘干", "is_correct": false, "explanation": "搭配：「烘干」的对象是潮湿的东西，不能说「帮病人烘干」这样的话。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：「点燃」指使物体燃烧，与把话换成另一种话毫不相干。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：「熄灭」指火或光不再亮，用在这句话里说不通，话语不能被熄灭。"}], "explanations": {"转译": "「转译」指口头把一种话换成另一种话，护士把医生的专业话换成病人能听懂的话，正是这个意思。", "烘干": "搭配：「烘干」的对象是潮湿的东西，不能说「帮病人烘干」这样的话。", "点燃": "语义：「点燃」指使物体燃烧，与把话换成另一种话毫不相干。", "熄灭": "语义：「熄灭」指火或光不再亮，用在这句话里说不通，话语不能被熄灭。"}, "sentence_index": 6, "correct_answer": "转译"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛被电视台转译到了全国各地。", "explanation": "这里应该用〈转播〉。「转译」指把一种话变成另一种话，比赛画面传送到各地要用「转播」。"}, {"text": "电话已经转译到了经理室。", "explanation": "这里应该用〈转接〉。「转译」指把一种话换成另一种话说，电话转到别处要用「转接」。"}, {"text": "我把这笔钱转译给了弟弟。", "explanation": "这里应该用〈转账〉。「转译」指把一种话变成另一种话，钱款转给别人要用「转账」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我帮爷爷把普通话转译了方言。", "corrected_sentence": "我帮爷爷把普通话转译成了方言。", "error_description": "「转译」后面要加结果补语「成」，应说「转译成了方言」；漏掉「成」就不对了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈已经把这段话转译了过。", "corrected_sentence": "妈妈已经把这段话转译过了。", "error_description": "体标顺序错误：应说「转译过了」，「了」和「过」的顺序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
