INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法是说话写文章的规则。", "primary_collocate": null, "pronunciation": "yǔ fǎ", "ipa": "y˨˩˦ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "说话和写文章都要注意语法。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的语法很好，写的句子都很通顺。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇作文的语法没有错，老师给了高分。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的语法不好，常常写错句子。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不学语法，也能自然地学会说话。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想说的我明白，但语法不太对。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章前，先把语法复习一遍。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老师讲语法讲得很清楚。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国朋友说中文时，语法有时候会出错。", "target_word": "语法", "complexity_tier": "T3", "furigana": "wài guó péng you shuō zhōng wén shí, yǔ fǎ yǒu shí hou huì chū cuò.", "sentence_source": "generated"}, {"text": "学语法很难，但是它能帮你写好文章。", "target_word": "语法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語法", "label": "繁体"}, {"form": "语法书", "label": "复合"}, {"form": "语法错误", "label": "复合"}], "register": "中性", "sense_fingerprint": "语法：说话和写文章要遵守的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语法", "is_correct": true, "explanation": "正确：「语法」指说话和写文章要遵守的规则，与这句话的语境相符。"}, {"text": "发音", "is_correct": false, "explanation": "语义：「发音」指声音，写文章不涉及发音，与句中「写文章」的语境不合。"}, {"text": "标点", "is_correct": false, "explanation": "语义：「标点」只用于书面，说话时不用标点，与句中「说话」的语境不合。"}, {"text": "字体", "is_correct": false, "explanation": "语义：「字体」是书面文字的字形，说话时不涉及字体，与句中「说话」的语境不合。"}], "explanations": {"语法": "正确：「语法」指说话和写文章要遵守的规则，与这句话的语境相符。", "发音": "语义：「发音」指声音，写文章不涉及发音，与句中「写文章」的语境不合。", "标点": "语义：「标点」只用于书面，说话时不用标点，与句中「说话」的语境不合。", "字体": "语义：「字体」是书面文字的字形，说话时不涉及字体，与句中「说话」的语境不合。"}, "sentence_index": 0, "correct_answer": "语法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话的语法很温和，大家都喜欢。", "explanation": "这里应该用〈语气〉。「语法」指说话和写作的规则，不能用来形容说话的态度与口吻。"}, {"text": "这个歌手的语法很好听。", "explanation": "这里应该用〈声音〉。「语法」是规则，不能用来形容声音好听与否。"}, {"text": "这个观点很有语法。", "explanation": "这里应该用〈见解〉。「语法」指说话和写作的规则，不能用来形容观点是否有见解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语法", "is_correct": true, "explanation": "正确：「语法」是写文章前要复习的规则，与这句话的语境相符。"}, {"text": "语调", "is_correct": false, "explanation": "语义：「语调」指说话时声音的高低变化，写文章前复习它与句意不合。"}, {"text": "语速", "is_correct": false, "explanation": "语义：「语速」指说话的快慢，与写文章前的准备工作无关。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：「复习」通常接知识、课文，不说「复习口音」。"}], "explanations": {"语法": "正确：「语法」是写文章前要复习的规则，与这句话的语境相符。", "语调": "语义：「语调」指说话时声音的高低变化，写文章前复习它与句意不合。", "语速": "语义：「语速」指说话的快慢，与写文章前的准备工作无关。", "口音": "搭配：「复习」通常接知识、课文，不说「复习口音」。"}, "sentence_index": 6, "correct_answer": "语法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的语法很鲜，大家都喜欢。", "explanation": "这里应该用〈味道〉。「语法」指规则，不能用来形容汤的味道鲜不鲜。"}, {"text": "她对孩子很有语法。", "explanation": "这里应该用〈感情〉。「语法」是语言规则，不能指对孩子的情感。"}, {"text": "这位老师的语法很开放。", "explanation": "这里应该用〈思想〉。「语法」是语言的规则，不能用来形容一个人的观念是否开放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前学了过语法。", "corrected_sentence": "他以前学过语法。", "error_description": "错误形式：「学了过语法」；正确形式：「学过语法」。「过」和「了」都是体标，不能叠加在同一个动词后面，表示经历只用「过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地语法基础很扎实。", "corrected_sentence": "他的语法基础很扎实。", "error_description": "错误形式：「他地语法基础很扎实」；正确形式：「他的语法基础很扎实」。定语标记要用「的」，「地」用于修饰动词、形容词，不能用在名词前，应说「他的语法基础」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
