INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西支起来放好。", "primary_collocate": null, "pronunciation": "jià shè", "ipa": "tɕja˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他在湖边架设好了相机。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师在草地上架设三脚架。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把摄像机架设在窗边，拍外面的雪。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在教室前面架设了画架。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，工作人员在场边架设好了话筒。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在阳台上架设一个望远镜。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在沙滩上架设好帐篷，准备过夜。", "target_word": "架设", "complexity_tier": "T3", "furigana": "yóu kè men zài shā tān shàng jià shè hǎo zhàng peng, zhǔn bèi guò yè.", "sentence_source": "generated"}, {"text": "他先架设好投影仪，大家才开始开会。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在床边架设输液架。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把鱼竿架设在石头上，等着鱼来。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架设了", "label": "完成体"}, {"form": "架设过", "label": "经历体"}, {"form": "架设好", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "把相机、支架等东西支起来放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24586, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "架设", "is_correct": true, "explanation": "架设 jià shè：把相机、支架等东西支起来放好，是目标词。"}, {"text": "假设", "is_correct": false, "explanation": "假设 jiǎ shè 与 架设 jià shè 的第一个音节声调不同（jiǎ 为第三声，jià 为第四声），意思是假定、设想。"}, {"text": "建设", "is_correct": false, "explanation": "建设 jiàn shè 与 架设 jià shè 的第一个音节韵母不同（jiàn 多一个 n，与 jià 的 a 不同），意思是建立、建造。"}, {"text": "架势", "is_correct": false, "explanation": "架势 jià shì 与 架设 jià shè 的第二个音节韵母不同（shì 为 i，shè 为 e），意思是姿态、样子。"}], "explanations": {"架设": "架设 jià shè：把相机、支架等东西支起来放好，是目标词。", "假设": "假设 jiǎ shè 与 架设 jià shè 的第一个音节声调不同（jiǎ 为第三声，jià 为第四声），意思是假定、设想。", "建设": "建设 jiàn shè 与 架设 jià shè 的第一个音节韵母不同（jiàn 多一个 n，与 jià 的 a 不同），意思是建立、建造。", "架势": "架势 jià shì 与 架设 jià shè 的第二个音节韵母不同（shì 为 i，shè 为 e），意思是姿态、样子。"}, "sentence_index": null, "correct_answer": "架设"}, "level_3": {"options": [{"text": "架设", "is_correct": true, "explanation": "正确：“架设好了相机”指把相机支起来放好，与句中在湖边的动作相合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象应是食物，不能说“煮相机”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指把植物栽进土里，与“相机”和句意不合。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食材，不能用于“相机”。"}], "explanations": {"架设": "正确：“架设好了相机”指把相机支起来放好，与句中在湖边的动作相合。", "煮": "搭配：“煮”的对象应是食物，不能说“煮相机”。", "种植": "语义：“种植”指把植物栽进土里，与“相机”和句意不合。", "烹饪": "搭配：“烹饪”的对象是食材，不能用于“相机”。"}, "sentence_index": 0, "correct_answer": "架设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上架设了很多书。", "explanation": "这里应该用〈放置〉。架设指把器材支起来安放，书应放进书架，不能说架设。"}, {"text": "妈妈把水果架设在桌上。", "explanation": "这里应该用〈摆放〉。架设强调把器材支起，水果应说摆放在桌上。"}, {"text": "他把画架设在墙上。", "explanation": "这里应该用〈挂〉。挂用于画、衣服等悬挂物，画不能用架设。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "架设", "is_correct": true, "explanation": "正确：“架设好帐篷”指把帐篷支起来，与“准备过夜”的语境相合。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆好帐篷”指把帐篷拆开，与“准备过夜”的目的相反。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指点火焚烧，与“准备过夜”要用帐篷的意思相反，句子说不通。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”的对象是土或地下的东西，不能用于“帐篷”，句子说不通。"}], "explanations": {"架设": "正确：“架设好帐篷”指把帐篷支起来，与“准备过夜”的语境相合。", "拆": "语义：“拆好帐篷”指把帐篷拆开，与“准备过夜”的目的相反。", "烧": "语义：“烧”指点火焚烧，与“准备过夜”要用帐篷的意思相反，句子说不通。", "挖": "搭配：“挖”的对象是土或地下的东西，不能用于“帐篷”，句子说不通。"}, "sentence_index": 6, "correct_answer": "架设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把孩子架设在肩上，去看游行。", "explanation": "这里应该用〈扛〉。架设指把器材支起安放，不用于人；把孩子抬到肩上应说〈扛〉。"}, {"text": "他把脚架设在椅子上，舒服地躺着。", "explanation": "这里应该用〈搁〉。架设指把器材支起安放，不用于脚；脚搭在椅子上应说〈搁〉。"}, {"text": "她把胳膊架设在窗台上，望着外面。", "explanation": "这里应该用〈搁〉。架设指把器材支起安放，不用于胳膊；胳膊搭在窗台上应说〈搁〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "摄影师在山顶架设着了一架望远镜。", "corrected_sentence": "摄影师在山顶架设了一架望远镜。", "error_description": "体貌错误：“着”表示状态持续，与表示动作完成的“了”不能同时用于此句。应说“架设了一架望远镜”，不能说“架设着了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在讲台前架设了好投影仪。", "corrected_sentence": "老师在讲台前架设好了投影仪。", "error_description": "补语位置错误：“好”是结果补语，应说“架设好了”，不能说“架设了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
