INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加或减少。", "primary_collocate": null, "pronunciation": "zēng shān", "ipa": "tsəŋ˥˥ ʂan˥˥", "syllable_count": 2, "sentences": [{"text": "公司每年都会增删一些课程。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜单每个月都增删几种菜。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆根据读者的需要，增删书的种类。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格里的人名，你可以自己增删。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课人数不同，我们要增删桌椅。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店会按季节增删商品。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行以前，先增删要带的东西。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每学期都会增删几门选修课。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的名单老是变，老师要不停增删。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的软件，你想增删都可以。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增删了", "label": "体标"}, {"form": "增删过", "label": "体标"}, {"form": "增刪", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把项目、人数、物品等加多或减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路等建筑，不能说修建课程。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房间、房屋，课程不能装修。"}, {"text": "增删", "is_correct": true, "explanation": "“增删”指加入或删去，“公司每年都会增删一些课程”符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉已有的建筑或设施，与课程的增减不符。"}], "explanations": {"修建": "搭配：“修建”用于房屋、道路等建筑，不能说修建课程。", "装修": "搭配：“装修”用于房间、房屋，课程不能装修。", "增删": "“增删”指加入或删去，“公司每年都会增删一些课程”符合句意。", "拆除": "语义：“拆除”指拆掉已有的建筑或设施，与课程的增减不符。"}, "sentence_index": 0, "correct_answer": "增删"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人增删了一条新路。", "explanation": "这里应该用〈修建〉。增删针对内容、项目等，道路要修建，不能增删。"}, {"text": "他增删了那块石头。", "explanation": "这里应该用〈粉碎〉。增删用于可以逐项加减的项目，石头被打碎要用粉碎。"}, {"text": "天上增删了一场雨。", "explanation": "这里应该用〈下〉。增删用于可以逐项加减的项目，下雨不能增删。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”针对食物，不能用于一般物品。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”是彻底毁掉，旅行前不会先毁掉要带的东西，句意不通。"}, {"text": "增删", "is_correct": true, "explanation": "“增删”指加入或删去，“旅行以前，先增删要带的东西”符合句意。"}, {"text": "焚烧", "is_correct": false, "explanation": "语义：“焚烧”是烧毁，与旅行前整理行李的语境不符。"}], "explanations": {"吃掉": "搭配：“吃掉”针对食物，不能用于一般物品。", "销毁": "语义：“销毁”是彻底毁掉，旅行前不会先毁掉要带的东西，句意不通。", "增删": "“增删”指加入或删去，“旅行以前，先增删要带的东西”符合句意。", "焚烧": "语义：“焚烧”是烧毁，与旅行前整理行李的语境不符。"}, "sentence_index": 6, "correct_answer": "增删"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师傅增删了那辆旧汽车。", "explanation": "这里应该用〈修理〉。增删用于内容、项目，旧汽车要修理，不能增删。"}, {"text": "她增删了一片花园。", "explanation": "这里应该用〈浇灌〉。增删针对可以逐项加减的项目，花园要浇灌，不能增删。"}, {"text": "他增删了整面墙。", "explanation": "这里应该用〈粉刷〉。增删用于内容、项目，墙要粉刷，不能说增删。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们又增删着几次课程。", "corrected_sentence": "他们又增删过几次课程。", "error_description": "体标应用“过”而非“着”：“增删过几次”表示已完成的几次动作，“增删着几次”表示持续状态，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他增删的很快。", "corrected_sentence": "他增删得很快。", "error_description": "补语标记应用“得”，不能用“的”；正确为“增删得很快”，“增删的很快”错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "影像就是拍下来的画面，比如照片或电视上的图。", "primary_collocate": null, "pronunciation": "yǐng xiàng", "ipa": "iŋ˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "电视上的影像很清楚。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这段旧影像里，奶奶还是个年轻姑娘。", "target_word": "影像", "complexity_tier": "T3", "furigana": "yǐng xiàng", "sentence_source": "generated"}, {"text": "这段影像拍得有点晃，画面不稳定。", "target_word": "影像", "complexity_tier": "T3", "furigana": "yǐng xiàng", "sentence_source": "generated"}, {"text": "屏幕坏了，影像一直在闪。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机留下了孩子的影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院的大屏幕影像特别大。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着旧影像，想起了老家。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影像和声音没有同步，看着很别扭。", "target_word": "影像", "complexity_tier": "T3", "furigana": "yǐng xiàng", "sentence_source": "generated"}, {"text": "请你把这些影像发给我。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用相机拍下了湖面上月亮的影像。", "target_word": "影像", "complexity_tier": "T3", "furigana": "yǐng xiàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段影像", "label": "量词"}, {"form": "影像资料", "label": "复合"}], "register": "中性", "sense_fingerprint": "拍下来的画面，照片或电视上的图（电视影像、旧影像）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57556918-9c49-4ffb-99f3-aee62b027b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像，指拍下来的画面。"}, {"text": "印象", "is_correct": false, "explanation": "yìn xiàng 与 yǐng xiàng 第一音节韵母不同（n 与 ng），声调也不同，意思是给人留下的感受。"}, {"text": "影响", "is_correct": false, "explanation": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。"}, {"text": "引向", "is_correct": false, "explanation": "yǐn 与 yǐng 韵母不同（in 与 ing），意思是引导朝某个方向。"}, {"text": "迎向", "is_correct": false, "explanation": "yíng 与 yǐng 声调不同（第二声与第三声），意思是迎着某个方向。"}], "explanations": {"影像": "正确：影像，指拍下来的画面。", "印象": "yìn xiàng 与 yǐng xiàng 第一音节韵母不同（n 与 ng），声调也不同，意思是给人留下的感受。", "影响": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。", "引向": "yǐn 与 yǐng 韵母不同（in 与 ing），意思是引导朝某个方向。", "迎向": "yíng 与 yǐng 声调不同（第二声与第三声），意思是迎着某个方向。"}, "sentence_index": null, "correct_answer": "影像"}, "level_3": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像指电视上播放的画面，可以说“很清楚”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是嗅觉感受，不能在电视上呈现，也谈不上清楚与否。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“清楚”形容画面等可见的内容，不能修饰温度。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是数值，与电视画面无关，“电视上的体重很清楚”说不通。"}], "explanations": {"影像": "正确：影像指电视上播放的画面，可以说“很清楚”。", "味道": "语义：味道是嗅觉感受，不能在电视上呈现，也谈不上清楚与否。", "温度": "搭配：“清楚”形容画面等可见的内容，不能修饰温度。", "体重": "语义：体重是数值，与电视画面无关，“电视上的体重很清楚”说不通。"}, "sentence_index": 0, "correct_answer": "影像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在电影院看了一部很好看的影像。", "explanation": "这里应该用〈影片〉。影像指拍下的画面，在电影院看的整部作品要用〈影片〉，量词“部”也搭配〈影片〉。"}, {"text": "这件事对他的成长有很大影像。", "explanation": "这里应该用〈影响〉。影像指画面，“有很大……”说的是作用，要用〈影响〉。"}, {"text": "我每天早上用影像刷牙。", "explanation": "这里应该用〈牙膏〉。刷牙要用牙膏，影像是拍下来的画面，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像，指拍下来的画面。"}, {"text": "景象", "is_correct": false, "explanation": "jǐng 与 yǐng 声母不同（j 与零声母），声调相同，意思是景色、场面。"}, {"text": "英雄", "is_correct": false, "explanation": "yīng xióng 与 yǐng xiàng 声调与韵母都有差别，但听感接近，意思是勇敢出众的人。"}, {"text": "引线", "is_correct": false, "explanation": "yǐn xiàn 与 yǐng xiàng 两个音节都只差韵尾（n 与 ng），声调相同，意思是导线或引火的线。"}], "explanations": {"影像": "正确：影像，指拍下来的画面。", "景象": "jǐng 与 yǐng 声母不同（j 与零声母），声调相同，意思是景色、场面。", "英雄": "yīng xióng 与 yǐng xiàng 声调与韵母都有差别，但听感接近，意思是勇敢出众的人。", "引线": "yǐn xiàn 与 yǐng xiàng 两个音节都只差韵尾（n 与 ng），声调相同，意思是导线或引火的线。"}, "sentence_index": null, "correct_answer": "影像"}, "level_3": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像指拍下的旧画面，“看着”的对象是可见的画面。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律是听觉的，不能用“看着”。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“看着”的对象应是可见的事物，“声音”不能被看。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不能被看到，与“看着”搭配不当。"}], "explanations": {"影像": "正确：影像指拍下的旧画面，“看着”的对象是可见的画面。", "旋律": "语义：旋律是听觉的，不能用“看着”。", "声音": "配价：“看着”的对象应是可见的事物，“声音”不能被看。", "气味": "语义：气味不能被看到，与“看着”搭配不当。"}, "sentence_index": 6, "correct_answer": "影像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把影像倒进杯子里喝了。", "explanation": "这里应该用〈果汁〉。影像是拍下来的画面，不是可以倒进杯子里喝的饮料。"}, {"text": "他用影像搭了一张桌子。", "explanation": "这里应该用〈木板〉。影像是拍下来的画面，不能用来搭桌子。"}, {"text": "电视上出现了一只影像。", "explanation": "这里应该用〈段〉。影像的量词是“段”，“只”不能用于影像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段影像拍很模糊。", "corrected_sentence": "这段影像拍得很模糊。", "error_description": "“拍很模糊”缺少结构助词“得”，应为“拍得很模糊”，用“得”连接动词与补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这只影像删掉了。", "corrected_sentence": "我把这段影像删掉了。", "error_description": "“这只影像”量词错误：影像的量词是“段”，“只”不能用于影像，应为“这段影像”，即“我把这段影像删掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
