INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物根本的、起决定作用的性质。", "primary_collocate": null, "pronunciation": "gēn běn xìng", "ipa": "kən˥ pən˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "钱不是幸福的根本性因素。", "target_word": "根本性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，学习态度是根本性的。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先找出根本性的原因，再想办法。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个根本性的错误让整个计划失败了。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水对农业来说是根本性的条件。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人们担心的是根本性的问题，不是小事。", "target_word": "根本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好语言，根本性的办法是多听多说。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们没有看到事情根本性的一面。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起小细节，我更关心根本性的东西。", "target_word": "根本性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，这种病的根本性原因还没有找到。", "target_word": "根本性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "根本性:根本的、起决定作用的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a818043-95f1-4634-87a5-2d86d4a18143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根本性", "is_correct": true, "explanation": "根本性：指最根本的因素，与句中“钱不是……的因素”的否定判断相合，作“因素”的定语。"}, {"text": "抽象性", "is_correct": false, "explanation": "语义：“钱”是具体之物，“抽象性”与之不合，句子谈的是具体的因素。"}, {"text": "随意性", "is_correct": false, "explanation": "搭配：“随意性”指任意、不受约束，不能用来修饰“因素”。"}, {"text": "可读性", "is_correct": false, "explanation": "语义：“可读性”指文章等易于阅读的程度，与“钱”和“幸福”无关，句意不通。"}], "explanations": {"根本性": "根本性：指最根本的因素，与句中“钱不是……的因素”的否定判断相合，作“因素”的定语。", "抽象性": "语义：“钱”是具体之物，“抽象性”与之不合，句子谈的是具体的因素。", "随意性": "搭配：“随意性”指任意、不受约束，不能用来修饰“因素”。", "可读性": "语义：“可读性”指文章等易于阅读的程度，与“钱”和“幸福”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "根本性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加比赛的根本性越来越多。", "explanation": "这里应该用〈人数〉。“根本性”指事物最本质的特性，不能说数量越来越多，人数要说“人数”。"}, {"text": "这箱苹果的根本性很重。", "explanation": "这里应该用〈重量〉。“根本性”不表示轻重，形容轻重要说“重量”。"}, {"text": "今天的根本性很低。", "explanation": "这里应该用〈温度〉。“根本性”不表示冷热，形容冷热要说“温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根本性", "is_correct": true, "explanation": "根本性：指最根本的办法，与“学好语言”的核心方法相合，作“办法”的定语。"}, {"text": "临时性", "is_correct": false, "explanation": "语义：“临时性”指暂时的、应急的，与“多听多说”这种长期积累相悖。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指碰巧发生，不能作为学好语言的办法。"}, {"text": "低效性", "is_correct": false, "explanation": "语义：“低效性”指效率低，与“学好语言”的有效办法相悖，句意矛盾。"}], "explanations": {"根本性": "根本性：指最根本的办法，与“学好语言”的核心方法相合，作“办法”的定语。", "临时性": "语义：“临时性”指暂时的、应急的，与“多听多说”这种长期积累相悖。", "偶然性": "语义：“偶然性”指碰巧发生，不能作为学好语言的办法。", "低效性": "语义：“低效性”指效率低，与“学好语言”的有效办法相悖，句意矛盾。"}, "sentence_index": 6, "correct_answer": "根本性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项工程的根本性很快。", "explanation": "这里应该用〈进度〉。“根本性”指事物的本质特性，不表示快慢，说工程的快慢要用“进度”。"}, {"text": "这首歌的根本性很大。", "explanation": "这里应该用〈音量〉。“根本性”不表示声音的大小，说声音大小要用“音量”。"}, {"text": "今天空气的根本性很高。", "explanation": "这里应该用〈湿度〉。“根本性”不表示干湿程度，说空气的干湿要用“湿度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们应该先抓住很根本性的问题。", "corrected_sentence": "他们应该先抓住根本性的问题。", "error_description": "错误在“很”：“根本性”是名词，不能被“很”修饰；应为“根本性的问题”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要想一个根本性得办法。", "corrected_sentence": "我们要想一个根本性的办法。", "error_description": "错误在结构助词：“根本性”修饰名词“办法”时应用“的”，不能用“得”（“得”用于补语）。应为“一个根本性的办法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
