INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里让男生和女生不一样的一个部分，用来生小宝宝。", "primary_collocate": null, "pronunciation": "xìng gōng néng", "ipa": "ɕiŋ˥˩ kʊŋ˥ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "男生和女生的性功能不一样。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长大以后，性功能会慢慢发育。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，性功能让人可以生小宝宝。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈告诉我，性功能是身体的一部分。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男生和女生的身体不同，是因为性功能不同。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，性功能是身体的私密部分，要好好保护。", "target_word": "性功能", "complexity_tier": "T3", "furigana": "lǎo shī shuō, xìng gōng néng shì shēn tǐ de sī mì bù fen, yào hǎo hǎo bǎo hù.", "sentence_source": "generated"}, {"text": "医生给孩子讲了性功能是做什么的。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着，男生和女生的性功能长在不同的地方。", "target_word": "性功能", "complexity_tier": "T3", "furigana": "shū shàng xiě zhe, nán shēng hé nǚ shēng de xìng gōng néng zhǎng zài bù tóng de dì fang.", "sentence_source": "generated"}, {"text": "动物也有性功能，所以能生小动物。", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“为什么我们的性功能不一样？”", "target_word": "性功能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "给孩子讲解的、男女身体不同且能生宝宝的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性功能", "is_correct": true, "explanation": "正确：指男女身体中不同的部分，符合句意。"}, {"text": "电压", "is_correct": false, "explanation": "语义：「电压」是电路中的物理量，与男女身体的差异无关，句子不通。"}, {"text": "功率", "is_correct": false, "explanation": "搭配：功率是机器或电器的指标，不用来说人的身体差异。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机是机械部件，与男女的身体构造无关。"}], "explanations": {"性功能": "正确：指男女身体中不同的部分，符合句意。", "电压": "语义：「电压」是电路中的物理量，与男女身体的差异无关，句子不通。", "功率": "搭配：功率是机器或电器的指标，不用来说人的身体差异。", "发动机": "语义：发动机是机械部件，与男女的身体构造无关。"}, "sentence_index": 0, "correct_answer": "性功能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的性功能是女的。", "explanation": "这里应该用〈性别〉。性别说男或女；性功能指身体中的部分，不能说它是男的或女的。"}, {"text": "她对我的性功能很深。", "explanation": "这里应该用〈感情〉。感情指人与人之间的情意；性功能只指身体里的生殖部分，不能用来说对人的情意。"}, {"text": "性功能负责把血液送到全身。", "explanation": "这里应该用〈心脏〉。性功能只指男女身体中与生育有关的部分，不负责输送血液。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性功能", "is_correct": true, "explanation": "正确：指男女身体中与生育有关的部分，符合句意。"}, {"text": "生殖隔离", "is_correct": false, "explanation": "语域：生殖隔离是生物学术语，不适合对孩子讲解，语域不符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票是金融概念，与身体部分无关，句子不成立。"}, {"text": "核武器", "is_correct": false, "explanation": "语义：核武器与孩子的身体知识无关，句子不成立。"}], "explanations": {"性功能": "正确：指男女身体中与生育有关的部分，符合句意。", "生殖隔离": "语域：生殖隔离是生物学术语，不适合对孩子讲解，语域不符。", "股票": "语义：股票是金融概念，与身体部分无关，句子不成立。", "核武器": "语义：核武器与孩子的身体知识无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "性功能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玻璃的性功能很好，看东西很清楚。", "explanation": "这里应该用〈透光性〉。透光性指物体让光通过的性质；性功能只指身体里的生殖部分，不能用来说玻璃。"}, {"text": "狗的性功能很灵，能闻到很远的味道。", "explanation": "这里应该用〈鼻子〉。鼻子负责嗅觉；性功能不负责闻味道。"}, {"text": "他的性功能很巧，能做很精细的活。", "explanation": "这里应该用〈手〉。手巧指动手能力强；性功能不能表示做活的技巧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "男孩和女孩的身体里有一只不同的性功能。", "corrected_sentence": "男孩和女孩的身体里有一种不同的性功能。", "error_description": "量词错误：性功能应与量词“种”搭配，“只”不用于此。正确为“一种不同的性功能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书性功能讲得很清楚。", "corrected_sentence": "这本书对性功能讲得很清楚。", "error_description": "漏掉了介词：应为“对性功能讲得很清楚”，“对”引出讲述的对象，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
