INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存在论是哲学的一个分支，研究「存在」本身，追问事物是否真的存在。", "primary_collocate": null, "pronunciation": "cún zài lùn", "ipa": "tsʰuən˧˥ tsaɪ˥˩ luən˥˩", "syllable_count": 3, "sentences": [{"text": "存在论会问：桌子是不是真的在这里？", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用存在论的办法，问月亮是不是真的存在。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论想知道，梦里的东西算不算真的有。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问鬼是不是真的有，这是存在论的问题。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论关心的是：这个东西到底在不在？", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用存在论的问题让我们想了很久。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了存在论以后，他常问自己周围的东西是真的吗。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个存在论的问题很简单：房间里有没有人？", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上用存在论讨论过独角兽。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论只问一件事：它是不是真的在那里。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存在論", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "追问一个东西是否真的存在的思考方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b46a45-2baa-4fa4-b1e2-7adacd8bb984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存在论", "is_correct": true, "explanation": "正确：存在论是追问事物是否真的存在的思考方式，可以“会问”桌子是否真的在这里。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单列出可以点的菜，不会问桌子是不是真的在这里。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报报告天气情况，不能提出“桌子是不是真的在这里”的问题。"}, {"text": "身高", "is_correct": false, "explanation": "配价：“会问”要求能提问的主体，“身高”不能作“会问”的主语。"}], "explanations": {"存在论": "正确：存在论是追问事物是否真的存在的思考方式，可以“会问”桌子是否真的在这里。", "菜单": "语义：菜单列出可以点的菜，不会问桌子是不是真的在这里。", "天气预报": "语义：天气预报报告天气情况，不能提出“桌子是不是真的在这里”的问题。", "身高": "配价：“会问”要求能提问的主体，“身高”不能作“会问”的主语。"}, "sentence_index": 0, "correct_answer": "存在论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "存在论研究人如何获得可靠的知识。", "explanation": "这里应该用〈认识论〉。存在论追问事物是否真的存在，获得可靠知识的方式属于认识论。"}, {"text": "存在论研究人的情绪和行为。", "explanation": "这里应该用〈心理学〉。情绪和行为属于心理学，存在论追问的是事物是否存在。"}, {"text": "存在论研究古代王朝的兴衰。", "explanation": "这里应该用〈历史学〉。古代王朝的兴衰属于历史学，存在论追问的是事物是否真的存在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存在论", "is_correct": true, "explanation": "正确：存在论是可以学习的哲学思考方式，与“学了……以后，他常问自己周围的东西是真的吗”相合。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“学”后面接知识或技能，不能说“学了食堂”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以学习的内容，也不会引出这种哲学式的追问。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不是学习的对象，与“常问自己周围的东西是真的吗”的意思无关。"}], "explanations": {"存在论": "正确：存在论是可以学习的哲学思考方式，与“学了……以后，他常问自己周围的东西是真的吗”相合。", "食堂": "搭配：“学”后面接知识或技能，不能说“学了食堂”。", "感冒": "语义：感冒是一种疾病，不是可以学习的内容，也不会引出这种哲学式的追问。", "体温": "语义：体温是身体的温度，不是学习的对象，与“常问自己周围的东西是真的吗”的意思无关。"}, "sentence_index": 6, "correct_answer": "存在论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "存在论研究人与社会的关系。", "explanation": "这里应该用〈社会学〉。人与社会的关系属于社会学，存在论追问的是事物是否真的存在。"}, {"text": "存在论研究国家与权力的运行。", "explanation": "这里应该用〈政治学〉。国家与权力的运行属于政治学，存在论只问事物是否真的存在。"}, {"text": "存在论研究植物如何生长。", "explanation": "这里应该用〈植物学〉。植物如何生长属于植物学，存在论研究的是「存在」本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读了一本关于存在论书。", "corrected_sentence": "我读了一本关于存在论的书。", "error_description": "“关于存在论”修饰“书”时要加“的”，应说“关于存在论的书”，漏掉“的”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我过学存在论。", "corrected_sentence": "我学过存在论。", "error_description": "表示经历的“过”应紧跟动词“学”，说“学过存在论”，不能放在动词前说“过学存在论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
