INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "考古是挖出很久以前的东西，看看人们以前怎么生活。", "primary_collocate": null, "pronunciation": "kǎo gǔ", "ipa": "kʰɑʊ˨˩˦ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们在山上考古。", "target_word": "考古", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家在这里考古已经三年了。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带学生去河边考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "挖地时发现了旧陶器，专家决定在这里考古。", "target_word": "考古", "complexity_tier": "T3", "furigana": "wā dì shí fā xiàn le jiù táo qì, zhuān jiā jué dìng zài zhè lǐ kǎo gǔ.", "sentence_source": "generated"}, {"text": "他们在古城里考古，挖出了很多罐子。", "target_word": "考古", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想长大后去沙漠考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考古的人每天都要挖土。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天太热，今天不能去考古了。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一边考古，一边写记录。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月我们要去西安考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "考古学", "label": "复合"}, {"form": "考古学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "挖掘古代东西来了解古人生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '576e64ee-f9ee-4e44-b7e0-41b533bdad60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘地铁", "is_correct": false, "explanation": "语义：地铁是城市交通，不能在山上「乘地铁」。"}, {"text": "逛超市", "is_correct": false, "explanation": "语义：超市是城镇的商业场所，「在山上逛超市」与场所不合。"}, {"text": "考古", "is_correct": true, "explanation": "正确：「在山上考古」指在山区挖掘古物，符合句意。"}, {"text": "考古学", "is_correct": false, "explanation": "语法：「考古学」是学科名词，不能直接作「在山上」后的谓语。"}], "explanations": {"乘地铁": "语义：地铁是城市交通，不能在山上「乘地铁」。", "逛超市": "语义：超市是城镇的商业场所，「在山上逛超市」与场所不合。", "考古": "正确：「在山上考古」指在山区挖掘古物，符合句意。", "考古学": "语法：「考古学」是学科名词，不能直接作「在山上」后的谓语。"}, "sentence_index": 0, "correct_answer": "考古"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在院子里考古了一根水管。", "explanation": "这里应该用〈挖〉。「考古」指挖掘古代遗存，挖水管等现代物件要用「挖」。"}, {"text": "专家去山区考古地质情况。", "explanation": "这里应该用〈考察〉。「考古」的对象是古代遗存，不能用来考察地质。"}, {"text": "他把弟弟考古了一下。", "explanation": "这里应该用〈观察〉。「考古」只用于挖掘古代遗存，不能用于人，这里的意思是「观察」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写作", "is_correct": false, "explanation": "语义：写作与挖土无关，「写作的人每天都要挖土」不合常理。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋不需要挖土，句意不通。"}, {"text": "考古", "is_correct": true, "explanation": "正确：「考古的人」指从事挖掘研究的人，每天都要挖土，符合句意。"}, {"text": "撰著", "is_correct": false, "explanation": "语域：「撰著」是书面语，与口语句的语域不合，且与挖土无关。"}], "explanations": {"写作": "语义：写作与挖土无关，「写作的人每天都要挖土」不合常理。", "下棋": "语义：下棋不需要挖土，句意不通。", "考古": "正确：「考古的人」指从事挖掘研究的人，每天都要挖土，符合句意。", "撰著": "语域：「撰著」是书面语，与口语句的语域不合，且与挖土无关。"}, "sentence_index": 6, "correct_answer": "考古"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们下个月打算考古这条马路。", "explanation": "这里应该用〈修建〉。「考古」指挖掘古代遗存，不能用来指修建现代马路。"}, {"text": "他们在超市考古。", "explanation": "考古要在遗址、古墓等地方进行，超市不是考古的场所，这是场所用错了。"}, {"text": "我们正在考古古代的哲学思想。", "explanation": "这里应该用〈研究〉。「考古」指挖掘古代遗存，不能用来指研究抽象的哲学思想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们昨天山上考古了。", "corrected_sentence": "他们昨天在山上考古了。", "error_description": "介词遗漏：表示处所的「山上」作状语时需要介词「在」，应说「在山上考古」，不能省略「在」直接说「山上考古」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们去年考古了三个次。", "corrected_sentence": "他们去年考古了三次。", "error_description": "量词错误：「次」是动词「考古」的动量词，不能与「个」叠用，应说「考古了三次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
