INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "瓶子是一种容器，可以装水或饮料。", "primary_collocate": null, "pronunciation": "píng zi", "ipa": "pʰiŋ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "桌子上有一个空瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把瓶子里的水喝完了。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子是玻璃做的。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了两个新瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别打破那个瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用旧瓶子种了一朵花。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子太滑，他没拿住。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把瓶子放在冰箱里。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子里装着半瓶牛奶。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里拿着一个红瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "装水或饮料的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7846ece-b54f-4e87-9fd6-ee570f2cbede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瓶子", "is_correct": true, "explanation": "正确：“桌子上有一个空……”中，“瓶子”是可以放在桌上的空容器。"}, {"text": "人", "is_correct": false, "explanation": "语义：“桌子上”放的东西不能是人，且“空”的人说不通，句意不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“桌子上”不能放下房间，“房间”与“桌子上”不搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以盛放的东西，“空”的雨说不通。"}], "explanations": {"瓶子": "正确：“桌子上有一个空……”中，“瓶子”是可以放在桌上的空容器。", "人": "语义：“桌子上”放的东西不能是人，且“空”的人说不通，句意不通。", "房间": "搭配：“桌子上”不能放下房间，“房间”与“桌子上”不搭配。", "雨": "语义：雨不是可以盛放的东西，“空”的雨说不通。"}, "sentence_index": 0, "correct_answer": "瓶子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把两个新瓶子穿在脚上。", "explanation": "这里应该用〈拖鞋〉。瓶子不能穿在脚上，穿在脚上的要用〈拖鞋〉这类鞋子。"}, {"text": "妈妈用新瓶子煮了两碗粥。", "explanation": "这里应该用〈锅〉。粥要用锅煮，瓶子口小，不能加热煮粥。"}, {"text": "妈妈用新瓶子切菜。", "explanation": "这里应该用〈菜刀〉。瓶子没有刃，不能切菜，切菜要用菜刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瓶子", "is_correct": true, "explanation": "正确：“瓶子太滑，他没拿住”中，“瓶子”是可以拿在手里的东西。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“拿住”不能搭配“房子”，房子拿不住，不能说“太滑”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能太滑，也拿不住，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不能被“拿住”，与“太滑”搭配不通。"}], "explanations": {"瓶子": "正确：“瓶子太滑，他没拿住”中，“瓶子”是可以拿在手里的东西。", "房子": "搭配：“拿住”不能搭配“房子”，房子拿不住，不能说“太滑”。", "天空": "语义：天空不能太滑，也拿不住，句意不通。", "心情": "语义：心情不能被“拿住”，与“太滑”搭配不通。"}, "sentence_index": 6, "correct_answer": "瓶子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把衣服装进瓶子里了。", "explanation": "这里应该用〈箱子〉。衣服体积大，瓶子口小，装不进去。"}, {"text": "她用瓶子洗衣服。", "explanation": "这里应该用〈盆〉。洗衣服要用能盛水的盆，瓶子口小，不便洗衣服。"}, {"text": "我们在瓶子里游泳。", "explanation": "这里应该用〈游泳池〉。人不能在瓶子里游泳，游泳要在能容纳人的水池里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在超市里买了一瓶子饮料。", "corrected_sentence": "我在超市里买了一瓶饮料。", "error_description": "错误：“瓶子”是名词，不能用作数词后的量词，应说“一瓶饮料”，用量词“瓶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一张脏瓶子洗干净了。", "corrected_sentence": "他把脏瓶子洗干净了。", "error_description": "量词错误：“瓶子”前用了量词“张”，“张”用于纸张、桌子等扁平物品，不能用于瓶子。应去掉“一张”，说“脏瓶子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸做的小盒子。", "primary_collocate": null, "pronunciation": "zhǐ hé", "ipa": "ʈʂɻ̩˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我有一个红色的小纸盒。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从纸盒里拿出一支笔。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把玩具放进纸盒里。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸盒是我自己做的。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的纸盒里有几块饼干。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用漂亮的纸盒装礼物。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸盒太小，放不下这本书。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每人发了一个纸盒。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找到了一个旧纸盒。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纸盒打开了，里面是糖。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "纸做的小盒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7846ece-b54f-4e87-9fd6-ee570f2cbede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸盒", "is_correct": true, "explanation": "正确。“纸盒”是纸做的小盒子，与“红色的小”的描述相符。"}, {"text": "大厦", "is_correct": false, "explanation": "语义：“小”与“大厦”的大体积相矛盾，“小大厦”不成立。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是黑色的，与“红色的”冲突，“红色的小黑板”不成立。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不能是“红色的小”的实物，句意不通。"}], "explanations": {"纸盒": "正确。“纸盒”是纸做的小盒子，与“红色的小”的描述相符。", "大厦": "语义：“小”与“大厦”的大体积相矛盾，“小大厦”不成立。", "黑板": "语义：黑板是黑色的，与“红色的”冲突，“红色的小黑板”不成立。", "时间": "语义：“时间”是抽象概念，不能是“红色的小”的实物，句意不通。"}, "sentence_index": 0, "correct_answer": "纸盒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用纸盒烧开了一壶水。", "explanation": "这里应该用〈水壶〉。纸盒不能加热，烧水要用能耐热的水壶。"}, {"text": "她把项链放进纸盒，锁好了盖子。", "explanation": "这里应该用〈首饰盒〉。纸盒没有锁，不能“锁好”；能上锁的是首饰盒这类有锁的盒子。"}, {"text": "他把纸盒洗干净还给了食堂。", "explanation": "这里应该用〈饭盒〉。纸盒多为一次性纸制品，不能洗干净归还；饭盒可以清洗后循环使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸盒", "is_correct": true, "explanation": "正确。“纸盒”是能装东西的容器，“太小，放不下这本书”符合它的特点。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被装进或放下东西，“放不下这本书”与它无关，句子荒谬。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法被放在某处，“太小”也与大海的特点相矛盾。"}, {"text": "玉宇", "is_correct": false, "explanation": "语域：“玉宇”是书面雅语，口语中不用，且指天空，同样无法装下书。"}], "explanations": {"纸盒": "正确。“纸盒”是能装东西的容器，“太小，放不下这本书”符合它的特点。", "天空": "语义：天空不能被装进或放下东西，“放不下这本书”与它无关，句子荒谬。", "大海": "语义：大海无法被放在某处，“太小”也与大海的特点相矛盾。", "玉宇": "语域：“玉宇”是书面雅语，口语中不用，且指天空，同样无法装下书。"}, "sentence_index": 6, "correct_answer": "纸盒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把纸盒吃掉了。", "explanation": "语义：这里把“纸盒”误当成了〈食物〉。纸盒是纸做的器物，不能用“吃”。"}, {"text": "那个纸盒在草地上散步。", "explanation": "语义：这里把“纸盒”误当成了〈有生命的行动者〉。纸盒是器物，不会自己“散步”。"}, {"text": "我的纸盒昨天参加了期末考试。", "explanation": "语义：这里把“纸盒”误当成了〈学生〉。纸盒是器物，不能“参加考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把剪刀放进了那张纸盒里。", "corrected_sentence": "我把剪刀放进了那个纸盒里。", "error_description": "量词错误：纸盒是立体容器，应用量词“个”。“张”用于纸张、桌子等扁平物品，“那张纸盒”应改为“那个纸盒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有两纸盒。", "corrected_sentence": "桌上有两个纸盒。", "error_description": "量词缺失：数词“两”后面要加量词，“纸盒”应说“两个纸盒”，不能省去“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
