INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "废纸是不能用来写字的旧纸。", "primary_collocate": null, "pronunciation": "fèi zhǐ", "ipa": "fei˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张纸已经很旧了，只能当废纸。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那些旧报纸不能写字，只是废纸。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷用废纸包好了旧书。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这堆废纸又脏又旧，不能再写字了。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把废纸折成小船，放进水里。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们用废纸做了一个小房子。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纸箱旁边放着一些废纸。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用废纸擦干净了桌子。", "target_word": "废纸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗台上放着一张废纸，上面有一点脏东西。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废纸太旧了，不能写字，也不能画画。", "target_word": "废纸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "堆", "label": "量词"}, {"form": "廢紙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又旧又不能写字的纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '734ba1be-1b8e-436a-b024-5fdfa984a06b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废纸", "is_correct": true, "explanation": "正确：句中指已经很旧、只能当废品的纸，正是废纸。"}, {"text": "房子", "is_correct": false, "explanation": "语义：纸是很薄的东西，旧纸不能当房子，与“只能当”的语境不符。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是用来颁发的荣誉物，旧纸不能当奖杯。"}, {"text": "公文", "is_correct": false, "explanation": "语域：公文是正式的公务文书，与“已经很旧、只能当废品”的语境不协调。"}], "explanations": {"废纸": "正确：句中指已经很旧、只能当废品的纸，正是废纸。", "房子": "语义：纸是很薄的东西，旧纸不能当房子，与“只能当”的语境不符。", "奖杯": "语义：奖杯是用来颁发的荣誉物，旧纸不能当奖杯。", "公文": "语域：公文是正式的公务文书，与“已经很旧、只能当废品”的语境不协调。"}, "sentence_index": 0, "correct_answer": "废纸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张废纸是崭新的，表面很平整，还没有用过。", "explanation": "这里应该用〈新纸〉。废纸是旧的、没用的纸，不能说成崭新、没用过的，那要说〈新纸〉。"}, {"text": "爸爸每天早上都在读废纸。", "explanation": "这里应该用〈报纸〉。废纸已经旧得没有阅读价值，读的应是报纸。"}, {"text": "妹妹拿着一张废纸，走进图书馆借书。", "explanation": "这里应该用〈借书证〉。废纸没有证明身份的作用，借书要出示借书证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废纸", "is_correct": true, "explanation": "正确：句中指放在纸箱旁边的旧纸，正是废纸。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是大型乐器，不会成堆放在纸箱旁边。"}, {"text": "哲学", "is_correct": false, "explanation": "语义：哲学是抽象的学问，不能像东西一样放在纸箱旁边。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是抽象的情感，不能像纸一样放在纸箱旁边。"}], "explanations": {"废纸": "正确：句中指放在纸箱旁边的旧纸，正是废纸。", "钢琴": "语义：钢琴是大型乐器，不会成堆放在纸箱旁边。", "哲学": "语义：哲学是抽象的学问，不能像东西一样放在纸箱旁边。", "友谊": "语义：友谊是抽象的情感，不能像纸一样放在纸箱旁边。"}, "sentence_index": 6, "correct_answer": "废纸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把废纸存进了银行。", "explanation": "这里应该用〈钱〉。废纸没有价值，不能存进银行。"}, {"text": "妈妈把废纸挂在客厅里。", "explanation": "这里应该用〈奖状〉。废纸没有用处，不能当作荣誉挂在客厅里。"}, {"text": "妈妈用一张废纸炒了一盘菜。", "explanation": "这里应该用〈食材〉。废纸没有用处，也不能吃；炒菜要用食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸把一根废纸收拾得很干净。", "corrected_sentence": "爸爸把一张废纸收拾得很干净。", "error_description": "量词错误：“废纸”应用“张”，不能用“根”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把用过废纸丢了。", "corrected_sentence": "他把用过的废纸丢了。", "error_description": "定语标记错误：“用过”修饰“废纸”时要加“的”，应说“用过的废纸”，漏掉“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
