INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有三个角的图形，像屋顶那样。", "primary_collocate": null, "pronunciation": "sān jiǎo xíng", "ipa": "san˥ tɕjau˨˩˦ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "孩子用积木搭了一个三角形的屋顶。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块饼干是三角形的。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上剪出一个三角形。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的屋顶是三角形的。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三角形的帽子戴在小狗头上很可爱。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小红把面包切成了两个三角形。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一块三角形的蛋糕。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画了一个三角形，又画了一个圆。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面三角形的小旗是红色的。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷从远处看像一个三角形。", "target_word": "三角形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个三角形", "label": "量词"}, {"form": "直角三角形", "label": "复合"}, {"form": "等边三角形", "label": "复合"}], "register": "中性", "sense_fingerprint": "像屋顶一样有三个角的形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '734ba1be-1b8e-436a-b024-5fdfa984a06b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三角形", "is_correct": true, "explanation": "三角形：屋顶的形状，积木可以搭成三角形，与句意一致。"}, {"text": "糖块", "is_correct": false, "explanation": "语义：用积木搭出的屋顶不可能是糖块做的。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能用来搭屋顶。"}, {"text": "人类", "is_correct": false, "explanation": "搭配：“人类”不能用来修饰“屋顶”，不构成搭配。"}], "explanations": {"三角形": "三角形：屋顶的形状，积木可以搭成三角形，与句意一致。", "糖块": "语义：用积木搭出的屋顶不可能是糖块做的。", "饼干": "语义：饼干不能用来搭屋顶。", "人类": "搭配：“人类”不能用来修饰“屋顶”，不构成搭配。"}, "sentence_index": 0, "correct_answer": "三角形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上挂着一把三角形。", "explanation": "这里量词应用〈个〉。三角形是图形，不能用〈把〉来计量。"}, {"text": "他带了一个三角形当午饭。", "explanation": "这里应该用〈三明治〉。三角形是图形，不能当午饭吃，午饭要说三明治。"}, {"text": "妈妈用一个三角形煮了一锅粥。", "explanation": "这里应该用〈锅〉。三角形是图形，不能用来煮粥，煮粥要用锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三角形", "is_correct": true, "explanation": "三角形：蛋糕的形状，与句中“一块”的搭配自然。"}, {"text": "铁", "is_correct": false, "explanation": "语义：蛋糕是食物，不可能是铁做的。"}, {"text": "木头", "is_correct": false, "explanation": "语义：蛋糕不能是木头做的，与放在桌上可以吃的语境不符。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“手机”不能用来修饰“蛋糕”，不构成搭配。"}], "explanations": {"三角形": "三角形：蛋糕的形状，与句中“一块”的搭配自然。", "铁": "语义：蛋糕是食物，不可能是铁做的。", "木头": "语义：蛋糕不能是木头做的，与放在桌上可以吃的语境不符。", "手机": "搭配：“手机”不能用来修饰“蛋糕”，不构成搭配。"}, "sentence_index": 6, "correct_answer": "三角形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用三角形缝好了胳膊上的伤口。", "explanation": "这里应该用〈针〉。三角形是图形，不能用来缝合伤口，缝伤口要用针。"}, {"text": "这里是河流的三角形。", "explanation": "这里应该用〈三角地带〉。三角形是几何图形，河流交汇的地区要说三角地带。"}, {"text": "他用三角形敲出了节奏。", "explanation": "这里应该用〈三角铁〉。三角形是图形，敲出节奏的是打击乐器三角铁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师教我们用直尺画一片三角形。", "corrected_sentence": "老师教我们用直尺画一个三角形。", "error_description": "量词错误：“三角形”应用“个”，不能用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐用彩纸叠了一个三角形得小帽子。", "corrected_sentence": "姐姐用彩纸叠了一个三角形的小帽子。", "error_description": "“的”写成了“得”。修饰名词要用“的”，应为“三角形的小帽子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
