INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爱惜就是好好保护自己喜欢的东西。", "primary_collocate": null, "pronunciation": "ài xī", "ipa": "ai˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "她很爱惜自己的新裙子。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥爱惜他的自行车，天天擦。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明爱惜每一本漫画书。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爱惜这双球鞋，下雨天不穿。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷爱惜他的老照相机。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她爱惜着妈妈留下的那条围巾。", "target_word": "爱惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱惜玩具，所以很快就坏了。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要爱惜朋友送你的礼物。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹特别爱惜她的小花园。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟很爱惜他的画笔，每次用完都放好。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "爱惜了", "label": "体标"}, {"form": "爱惜着", "label": "体标"}, {"form": "爱惜过", "label": "体标"}], "register": "中性", "sense_fingerprint": "爱惜：好好保护自己喜欢的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f991c77-0779-429c-842a-f2b0e9d821f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱惜", "is_correct": true, "explanation": "爱惜：好好保护、重视，“她很爱惜自己的新裙子”符合句意。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”多用于钱财，不用于形容对裙子的态度。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“她很撕自己的新裙子”描述的是破坏行为，与句意相反。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：“损坏自己的新裙子”与“很”和爱惜的态度矛盾。"}], "explanations": {"爱惜": "爱惜：好好保护、重视，“她很爱惜自己的新裙子”符合句意。", "挥霍": "搭配：“挥霍”多用于钱财，不用于形容对裙子的态度。", "撕": "语义：“她很撕自己的新裙子”描述的是破坏行为，与句意相反。", "损坏": "语义：“损坏自己的新裙子”与“很”和爱惜的态度矛盾。"}, "sentence_index": 0, "correct_answer": "爱惜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生气地爱惜了椅子。", "explanation": "这里应该用〈踢翻〉。“爱惜”表示重视而不糟蹋，不能用来描述发脾气时的动作。"}, {"text": "他故意爱惜了我的花园。", "explanation": "这里应该用〈踩坏〉。“爱惜”表示重视而不糟蹋，不能用来表示故意破坏。"}, {"text": "警察爱惜了那个小偷。", "explanation": "这里应该用〈逮捕〉。“爱惜”表示重视而不糟蹋，不能用来表示逮捕罪犯的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱惜", "is_correct": true, "explanation": "爱惜：重视而不糟蹋，“他不爱惜玩具，所以很快就坏了”中“不爱惜”与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“他不吃玩具”与玩具坏掉的因果关系不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：玩具不能用“煮”来处理，搭配不当。"}, {"text": "种", "is_correct": false, "explanation": "语义：玩具不能被“种”，与句意矛盾。"}], "explanations": {"爱惜": "爱惜：重视而不糟蹋，“他不爱惜玩具，所以很快就坏了”中“不爱惜”与句意相符。", "吃": "语义：“他不吃玩具”与玩具坏掉的因果关系不符。", "煮": "搭配：玩具不能用“煮”来处理，搭配不当。", "种": "语义：玩具不能被“种”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "爱惜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个小偷爱惜了我的钱包。", "explanation": "这里应该用〈偷走〉。“爱惜”表示重视而不糟蹋，不能用来描述偷窃行为。"}, {"text": "这场比赛输了，大家都很爱惜。", "explanation": "这里应该用〈惋惜〉。“爱惜”指重视而不糟蹋，不能用来表示对失利的遗憾。"}, {"text": "他很爱惜地摔碎了画笔。", "explanation": "这里“爱惜”表示保护、不糟蹋，与“摔碎”矛盾；如果是不小心，应说〈不小心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我总是爱惜得我的书包。", "corrected_sentence": "我总是爱惜我的书包。", "error_description": "错误形式：“爱惜得我的书包”；正确形式：“爱惜我的书包”。“爱惜”后应直接接宾语，“得”不能插在动词与宾语之间；“爱惜得”只能接程度补语，如“爱惜得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹很爱惜了她的画笔。", "corrected_sentence": "妹妹很爱惜她的画笔。", "error_description": "错误形式：“很爱惜了”；正确形式：“很爱惜”。“很”后面的动词通常不加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
