INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24642, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像天空的颜色。", "primary_collocate": null, "pronunciation": "lán", "ipa": "lan˧˥", "syllable_count": 1, "sentences": [{"text": "晴天的天空蓝得让人开心。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿了一件像天空一样蓝的外套。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的杯子是蓝的，和今天的天一样。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的海很蓝，我们去游泳。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个外国孩子的眼睛是蓝的，像大海。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛仔裤洗了很多次，已经不太蓝了。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服的颜色比天空还蓝。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画家把纸涂成蓝的，像晴朗的天空。", "target_word": "蓝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的湖水又蓝又干净。", "target_word": "蓝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有云的天，看上去特别蓝。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓝色", "label": "复合"}, {"form": "蓝天", "label": "复合"}, {"form": "蓝蓝", "label": "重叠"}, {"form": "藍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蓝：像天空的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f991c77-0779-429c-842a-f2b0e9d821f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24642, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝（lán）：像天空的颜色，是本词条的读音与意义。"}, {"text": "难", "is_correct": false, "explanation": "nán（阳平）与 lán（阳平）声调相同，只差声母（n 与 l），意思是困难。"}, {"text": "狼", "is_correct": false, "explanation": "韵母 an 与 ang 不同（láng），意思是狼。"}, {"text": "懒", "is_correct": false, "explanation": "lǎn（上声）与 lán（阳平）声调不同，意思是懒惰。"}, {"text": "赖", "is_correct": false, "explanation": "韵母 an 与 ai 不同（lài），意思是赖皮、抵赖。"}], "explanations": {"蓝": "蓝（lán）：像天空的颜色，是本词条的读音与意义。", "难": "nán（阳平）与 lán（阳平）声调相同，只差声母（n 与 l），意思是困难。", "狼": "韵母 an 与 ang 不同（láng），意思是狼。", "懒": "lǎn（上声）与 lán（阳平）声调不同，意思是懒惰。", "赖": "韵母 an 与 ai 不同（lài），意思是赖皮、抵赖。"}, "sentence_index": null, "correct_answer": "蓝"}, "level_3": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝作补语，用“得”引出，形容天空的颜色，句意通顺。"}, {"text": "圆", "is_correct": false, "explanation": "语义：圆指形状，不指颜色，不能形容天空的颜色。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容人或动物的体态，不能形容天空的颜色，句意不通。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容质地，不用来形容天空的颜色。"}], "explanations": {"蓝": "蓝作补语，用“得”引出，形容天空的颜色，句意通顺。", "圆": "语义：圆指形状，不指颜色，不能形容天空的颜色。", "胖": "语义：“胖”形容人或动物的体态，不能形容天空的颜色，句意不通。", "硬": "搭配：“硬”形容质地，不用来形容天空的颜色。"}, "sentence_index": 0, "correct_answer": "蓝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最喜欢这只蓝，所以买了很多衣服。", "explanation": "这里应该用〈种〉。颜色类名词的量词是“种”，不用“只”。"}, {"text": "他的字写得很蓝，老师都看不懂。", "explanation": "这里应该用〈潦草〉。“蓝”只表示颜色，不能用来形容字迹。"}, {"text": "这个方案很蓝，我们明天就开始做。", "explanation": "这里应该用〈可行〉。“蓝”没有“可行”的意思，这里是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24642, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝（lán）：像天空的颜色，是本词条的读音与意义。"}, {"text": "男", "is_correct": false, "explanation": "nán（阳平）与 lán（阳平）声调相同，只差声母（n 与 l），意思是男人。"}, {"text": "南", "is_correct": false, "explanation": "nán 与 lán 声母不同，意思是南方。"}, {"text": "烂", "is_correct": false, "explanation": "làn（去声）与 lán（阳平）声调不同，意思是腐烂。"}, {"text": "滥", "is_correct": false, "explanation": "làn（去声）与 lán（阳平）声调不同，意思是泛滥。"}], "explanations": {"蓝": "蓝（lán）：像天空的颜色，是本词条的读音与意义。", "男": "nán（阳平）与 lán（阳平）声调相同，只差声母（n 与 l），意思是男人。", "南": "nán 与 lán 声母不同，意思是南方。", "烂": "làn（去声）与 lán（阳平）声调不同，意思是腐烂。", "滥": "làn（去声）与 lán（阳平）声调不同，意思是泛滥。"}, "sentence_index": null, "correct_answer": "蓝"}, "level_3": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝用于“比天空还”的比较句，形容衣服的颜色，与比较对象相符。"}, {"text": "绿", "is_correct": false, "explanation": "语义：天空不是绿色，与“比天空还”的比较矛盾。"}, {"text": "棕", "is_correct": false, "explanation": "语义：天空通常不是棕色，“比天空还棕”与句意不合。"}, {"text": "紫", "is_correct": false, "explanation": "语义：天空通常不是紫色，“比天空还紫”不构成自然的颜色比较。"}], "explanations": {"蓝": "蓝用于“比天空还”的比较句，形容衣服的颜色，与比较对象相符。", "绿": "语义：天空不是绿色，与“比天空还”的比较矛盾。", "棕": "语义：天空通常不是棕色，“比天空还棕”与句意不合。", "紫": "语义：天空通常不是紫色，“比天空还紫”不构成自然的颜色比较。"}, "sentence_index": 6, "correct_answer": "蓝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的回答很蓝，没人听得懂。", "explanation": "这里应该用〈含糊〉。“蓝”只表示颜色，不能用来形容说话的内容。"}, {"text": "这份报告的思路很蓝，领导看不懂。", "explanation": "这里应该用〈混乱〉。“蓝”只表示颜色，不能形容思路的条理。"}, {"text": "他的脾气很蓝，一点就着。", "explanation": "这里应该用〈暴躁〉。“蓝”只表示颜色，不能形容脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_