INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的眼睛得蓝很漂亮。", "corrected_sentence": "他的眼睛蓝得很漂亮。", "error_description": "错误形式：“眼睛得蓝很漂亮”；正确形式：“眼睛蓝得很漂亮”。“得”应紧跟形容词“蓝”之后引出补语，不能放在主语与“蓝”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
