INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24644, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以再次使用的。", "primary_collocate": null, "pronunciation": "kě huí shōu", "ipa": "kʰɤ˨˩˦ xweɪ˧˥ ʂoʊ˥˥", "syllable_count": 3, "sentences": [{"text": "旧报纸是可回收的，不要扔掉。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些可回收的盒子还能再用。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家有很多可回收的东西。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁罐是可回收的材料。", "target_word": "可回收", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的包装都是可回收的。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，旧书是可回收的。", "target_word": "可回收", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "把可回收的瓶子洗干净。", "target_word": "可回收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸可回收，也可以再做新纸。", "target_word": "可回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪些东西是可回收的？", "target_word": "可回收", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把可回收的纸箱放在门口。", "target_word": "可回收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可回收物", "label": "复合"}, {"form": "可回收垃圾", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以再次使用的，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e003bea1-9a51-40cb-91ca-bdd0a7fd19d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锋利", "is_correct": false, "explanation": "语义：报纸不是锋利的东西，句子说的是能否再利用。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不与报纸搭配。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”说的是温度，与“不要扔掉”的理由无关。"}, {"text": "可回收", "is_correct": true, "explanation": "旧报纸可以再次利用，所以不要扔掉，符合“可回收”的意思。"}], "explanations": {"锋利": "语义：报纸不是锋利的东西，句子说的是能否再利用。", "嘹亮": "搭配：“嘹亮”形容声音，不与报纸搭配。", "冰冷": "语义：“冰冷”说的是温度，与“不要扔掉”的理由无关。", "可回收": "旧报纸可以再次利用，所以不要扔掉，符合“可回收”的意思。"}, "sentence_index": 0, "correct_answer": "可回收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法很可回收。", "explanation": "这里应该用〈可取〉。“可回收”指物品能再次使用，形容方法好不好要说可取。"}, {"text": "这首歌很可回收。", "explanation": "这里不能用〈可回收〉。“可回收”只指物品能再次使用，形容歌曲应说好听。"}, {"text": "居民要把旧书送到可回收站。", "explanation": "这里应该用〈回收站〉。“可回收”描述物品属性，不能用来指地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉默", "is_correct": false, "explanation": "语义：瓶子不会“沉默”，与“洗干净”的动作无关。"}, {"text": "悲哀", "is_correct": false, "explanation": "语义：“悲哀”描写情绪，不能用来形容瓶子。"}, {"text": "严肃", "is_correct": false, "explanation": "搭配：“严肃”多形容人或神情，不说瓶子严肃。"}, {"text": "可回收", "is_correct": true, "explanation": "瓶子可以再次利用，所以要先洗干净，符合“可回收”的意思。"}], "explanations": {"沉默": "语义：瓶子不会“沉默”，与“洗干净”的动作无关。", "悲哀": "语义：“悲哀”描写情绪，不能用来形容瓶子。", "严肃": "搭配：“严肃”多形容人或神情，不说瓶子严肃。", "可回收": "瓶子可以再次利用，所以要先洗干净，符合“可回收”的意思。"}, "sentence_index": 6, "correct_answer": "可回收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个可回收的朋友。", "explanation": "这里不能用〈可回收〉。“可回收”只用来说物品能否再利用，不能用来形容人。"}, {"text": "这场考试是可回收的。", "explanation": "这里不能用〈可回收〉。“可回收”只用于能再利用的物品，考试是活动，不能说可回收。"}, {"text": "太阳能是可回收的能源。", "explanation": "这里应该用〈可再生〉。太阳能是自然持续产生的能源，不是经处理后再利用的物品，应该说可再生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些玻璃罐是可回收。", "corrected_sentence": "这些玻璃罐是可回收的。", "error_description": "漏“的”：用“是”作判断时，“可回收”后要加“的”，应说“是可回收的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批旧书没可回收。", "corrected_sentence": "这批旧书不可回收。", "error_description": "否定词错误：“可回收”前要用“不”，不能用“没”，应说“不可回收”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
