INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想着别人，希望他们好。", "primary_collocate": null, "pronunciation": "guān xīn", "ipa": "kwan˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "朋友生病了，我很关心他。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸每天打电话关心我吃得好不好。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈关心地问我冷不冷。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你一直这么关心我。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都很关心那个新来的女孩。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出远门时，家人都关心他路上安不安全。", "target_word": "关心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，妈妈怎么会不关心呢？", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很关心朋友，朋友有事她总是第一个帮忙。", "target_word": "关心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多关心一个人住的老人。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师关心着每个孩子是否快乐。", "target_word": "关心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关心了", "label": "体标"}, {"form": "关心着", "label": "体标"}, {"form": "关心关心", "label": "重叠"}, {"form": "關心", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关心：心里想着别人，希望他们过得好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42917911-9350-48ef-8d24-179b3d6d9c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关心", "is_correct": true, "explanation": "正确：“关心”表示心里挂念、希望对方好，与朋友生病的语境相符。"}, {"text": "利用", "is_correct": false, "explanation": "语义：“利用”含有索取的意味，与朋友生病时的善意不符。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”指冷淡对待，与朋友生病时的关切语境相反。"}, {"text": "咒骂", "is_correct": false, "explanation": "语域：“咒骂”语气粗暴，与句中温和的关切语域不协调。"}], "explanations": {"关心": "正确：“关心”表示心里挂念、希望对方好，与朋友生病的语境相符。", "利用": "语义：“利用”含有索取的意味，与朋友生病时的善意不符。", "冷落": "语义：“冷落”指冷淡对待，与朋友生病时的关切语境相反。", "咒骂": "语域：“咒骂”语气粗暴，与句中温和的关切语域不协调。"}, "sentence_index": 0, "correct_answer": "关心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很关心你的帮助。", "explanation": "这里应该用〈感谢〉。关心表示挂念对方，不用于对帮助表示谢意。"}, {"text": "孩子们关心了一碗饭。", "explanation": "这里应该用〈吃〉。关心表示心里想着别人、希望他们好，不能表示把食物吃下去。"}, {"text": "他一生气就关心了杯子。", "explanation": "这里应该用〈摔〉。关心表示心里想着别人、希望他们好，不能表示把东西摔碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关心", "is_correct": true, "explanation": "正确：反问句“怎么会不关心呢”表达母亲对生病孩子的挂念，符合语境。"}, {"text": "计算", "is_correct": false, "explanation": "配价：“计算”的宾语是数量或结果，不能接“孩子”作宾语。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：“挥霍”指浪费钱财，与母亲对生病孩子的态度不符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”指讥笑，与孩子生病时的关心语境相反。"}], "explanations": {"关心": "正确：反问句“怎么会不关心呢”表达母亲对生病孩子的挂念，符合语境。", "计算": "配价：“计算”的宾语是数量或结果，不能接“孩子”作宾语。", "挥霍": "语义：“挥霍”指浪费钱财，与母亲对生病孩子的态度不符。", "嘲笑": "语义：“嘲笑”指讥笑，与孩子生病时的关心语境相反。"}, "sentence_index": 6, "correct_answer": "关心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我关心了一张机票。", "explanation": "这里应该用〈预订〉。关心表示挂念，不能表示提前订购。"}, {"text": "他关心了三遍课文。", "explanation": "这里应该用〈抄写〉。关心不能表示把文字写下来。"}, {"text": "工人们关心了那堆砖。", "explanation": "这里应该用〈搬〉。关心不能表示搬运物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家人出差了，我关心着了他的安全。", "corrected_sentence": "家人出差了，我关心着他的安全。", "error_description": "错误：“关心着”之后多加了“了”，不能说“关心着了”。“着”表示持续的挂念，应为“关心着他的安全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班主任关心每个学生着是否吃饱。", "corrected_sentence": "班主任关心每个学生是否吃饱。", "error_description": "错误：“着”放在了宾语“学生”之后，位置不对。“着”应紧跟动词“关心”，但这句话不需要“着”，应为“班主任关心每个学生是否吃饱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
