INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24652, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "我们周围的水、空气和土地变脏了，不好看了。", "primary_collocate": null, "pronunciation": "huán jìng wū rǎn wèn tí", "ipa": "xwan˧˥ tɕiŋ˥˩ u˥ ʐan˨˩˦ wən˥˩ tʰi˧˥", "syllable_count": 6, "sentences": [{"text": "河水变脏了，这是环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气不好，水也很脏，这就是环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的土地和水都脏了，环境污染问题很大。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住的地方空气很差，环境污染问题很大。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的河很脏，有环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走在路上，到处是垃圾，环境污染问题让大家担心。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空是灰色的，环境污染问题很明显。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护水和空气，别再有环境污染问题了。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把脏水倒进河里，带来环境污染问题。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下的水又黑又臭，环境污染问题很严重。", "target_word": "环境污染问题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境污染問題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水、空气、土地变脏的日常污染情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9757e9d-1d75-48ad-ba0e-2752e1a658ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境污染问题", "is_correct": true, "explanation": "指水、空气、土地变脏的日常污染情况，与“河水变脏了”的判断相符。"}, {"text": "空气净化器", "is_correct": false, "explanation": "语义：空气净化器是设备，不是一种污染状况，“这是空气净化器”与河水变脏不符。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆是场所，与河水变脏无关，不能用来说明这一情况。"}, {"text": "清洁剂", "is_correct": false, "explanation": "搭配：清洁剂用于清洁，不能用来说明河水已经变脏这一状况。"}], "explanations": {"环境污染问题": "指水、空气、土地变脏的日常污染情况，与“河水变脏了”的判断相符。", "空气净化器": "语义：空气净化器是设备，不是一种污染状况，“这是空气净化器”与河水变脏不符。", "体育馆": "语义：体育馆是场所，与河水变脏无关，不能用来说明这一情况。", "清洁剂": "搭配：清洁剂用于清洁，不能用来说明河水已经变脏这一状况。"}, "sentence_index": 0, "correct_answer": "环境污染问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的电脑有环境污染问题，经常死机。", "explanation": "这里应该用〈故障〉。“环境污染问题”指水、空气和土地变脏，不能用来说电脑的故障。"}, {"text": "这件衣服有环境污染问题，穿了一天就破了。", "explanation": "这里应该用〈质量问题〉。“环境污染问题”指水、空气和土地变脏，不能用来说衣服的质量。"}, {"text": "我的朋友有环境污染问题，最近总是不开心。", "explanation": "这里应该用〈心事〉。“环境污染问题”指水、空气和土地变脏，不能用来指人的心事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境污染问题", "is_correct": true, "explanation": "指水、空气、土地变脏的明显情况，与“天空是灰色的，很明显”相符。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩是考核结果，不能用来描述天空的状况，与“天空是灰色的”不搭。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：灰色的天空与鲜花的形象相矛盾，不能用来说明天空的状况。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很明显”多修饰现象或状态，“身高”是人的身体指标，不能用来描述天空。"}], "explanations": {"环境污染问题": "指水、空气、土地变脏的明显情况，与“天空是灰色的，很明显”相符。", "成绩": "语义：成绩是考核结果，不能用来描述天空的状况，与“天空是灰色的”不搭。", "鲜花": "语义：灰色的天空与鲜花的形象相矛盾，不能用来说明天空的状况。", "身高": "搭配：“很明显”多修饰现象或状态，“身高”是人的身体指标，不能用来描述天空。"}, "sentence_index": 6, "correct_answer": "环境污染问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山下的学生常常迟到，环境污染问题很严重。", "explanation": "这里应该用〈纪律问题〉。“环境污染问题”指水、空气和土地变脏，不能用来说学生迟到；迟到属于纪律问题。"}, {"text": "山上的人家常常吵架，环境污染问题很严重。", "explanation": "这里应该用〈家庭矛盾〉。“环境污染问题”指水、空气和土地变脏，不能用来指家里的吵架等人际冲突。"}, {"text": "山下的小店经常缺货，环境污染问题很严重。", "explanation": "这里应该用〈缺货〉。“环境污染问题”指水、空气和土地变脏，不能用来指商店的货物供应问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要尽快解决这条环境污染问题。", "corrected_sentence": "我们要尽快解决这个环境污染问题。", "error_description": "量词错误：“问题”应用“个”，“条”用于河流、路等细长的东西，不能用来计量“问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要尽快治理这只环境污染问题。", "corrected_sentence": "我们要尽快治理这个环境污染问题。", "error_description": "量词错误：“问题”应用“个”，“只”用于动物或成对、单个的小件物品，不能用来计量“问题”。正确说法是“这个环境污染问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
