INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设计师是画图、想主意，然后做出新东西的人。", "primary_collocate": null, "pronunciation": "shè jì shī", "ipa": "ʂɤ˥˩ tɕi˥˩ ʂɨ˥", "syllable_count": 3, "sentences": [{"text": "我姐姐是一位有名的设计师。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师正在电脑前画图。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是一位年轻设计师做的。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师想了很久，才决定用蓝色。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当设计师。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是设计师自己做的。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师给我们看了新房子的图。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在一家公司做设计师。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的设计师会听客人的想法。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位设计师给我们做了一把新椅子。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "服装设计师", "label": "复合"}, {"form": "設計師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从事设计工作的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0cc0c3-2668-4386-9dc2-289c59985202') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不说“一位房子”。"}, {"text": "设计师", "is_correct": true, "explanation": "正确：设计师是从事设计工作的人，可以用“一位有名的”修饰。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“位”只能计人，“一位石头”不能说。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不是人，不能作“我姐姐”的职业身份。"}], "explanations": {"房子": "搭配：量词“位”只用于人，不说“一位房子”。", "设计师": "正确：设计师是从事设计工作的人，可以用“一位有名的”修饰。", "石头": "搭配：“位”只能计人，“一位石头”不能说。", "电脑": "语义：电脑是机器，不是人，不能作“我姐姐”的职业身份。"}, "sentence_index": 0, "correct_answer": "设计师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "设计师在路口指挥交通。", "explanation": "这里应该用〈警察〉。指挥交通是警察的工作，设计师的工作是画图和设计。"}, {"text": "他把设计师放进了冰箱。", "explanation": "这里应该用〈牛奶〉。设计师是人，不能放进冰箱；「牛奶」才是可以放进冰箱的东西。"}, {"text": "我爸爸在设计师工作。", "explanation": "这里应该用〈设计院〉。设计师是职业，不是工作的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能给人看图，句子不合常理。"}, {"text": "设计师", "is_correct": true, "explanation": "正确：设计师能给人看设计好的图，符合语境。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能给人看新房子的图纸，句子不合常理。"}, {"text": "名字", "is_correct": false, "explanation": "配价：“给我们看”需要能动的施事，“名字”不能作施事。"}], "explanations": {"窗户": "语义：窗户是建筑部件，不能给人看图，句子不合常理。", "设计师": "正确：设计师能给人看设计好的图，符合语境。", "小猫": "语义：小猫不能给人看新房子的图纸，句子不合常理。", "名字": "配价：“给我们看”需要能动的施事，“名字”不能作施事。"}, "sentence_index": 6, "correct_answer": "设计师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "用设计师做了一把椅子。", "explanation": "这里应该用〈木头〉。做椅子要用木头等材料，设计师是人，不能当材料。"}, {"text": "设计师给我们看了病。", "explanation": "这里应该用〈医生〉。看病的是医生，设计师不看病。"}, {"text": "设计师帮我们打了官司。", "explanation": "这里应该用〈律师〉。打官司要找律师，设计师不做这个工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位很有名设计师住在隔壁。", "corrected_sentence": "这位很有名的设计师住在隔壁。", "error_description": "“很有名”修饰“设计师”时中间要加“的”，应说“很有名的设计师”；漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请来了一只设计师。", "corrected_sentence": "我们请来了一位设计师。", "error_description": "“设计师”指人，量词应用“位”或“个”，“只”用于动物等，不能说“一只设计师”；应说“一位设计师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
