INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24660, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以前用过的东西。", "primary_collocate": null, "pronunciation": "jiù wù", "ipa": "tɕjou˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "床下面堆着很多旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旧物放进了纸箱。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我想清理一下旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到旧物，他想起了小时候。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了一次旧物交换活动。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧物还能用，别扔掉。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在旧物里找到了一张老照片。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用旧物布置了一个小咖啡店。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧物可以送给需要的人。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈舍不得丢掉这些旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "旧物改造", "label": "复合"}, {"form": "舊物", "label": "繁体"}], "register": "通用", "sense_fingerprint": "以前用过的东西，常带有回忆或可再利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9757e9d-1d75-48ad-ba0e-2752e1a658ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旧物", "is_correct": true, "explanation": "正确：旧物是以前用过的东西，可以堆在床下，符合语境。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是天上的水汽，不可能堆在床下。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是声音，不是有形的东西，不能堆放。"}, {"text": "微风", "is_correct": false, "explanation": "搭配：“堆”用于有形的物体，微风无形，不能堆放。"}], "explanations": {"旧物": "正确：旧物是以前用过的东西，可以堆在床下，符合语境。", "云朵": "语义：云朵是天上的水汽，不可能堆在床下。", "歌声": "语义：歌声是声音，不是有形的东西，不能堆放。", "微风": "搭配：“堆”用于有形的物体，微风无形，不能堆放。"}, "sentence_index": 0, "correct_answer": "旧物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他晚上做了一个旧物，醒来后很害怕。", "explanation": "这里应该用〈梦〉。旧物指过去用过的东西，不能用“做”来说，做梦应说“梦”。"}, {"text": "看到照片，他的心里充满了旧物。", "explanation": "这里应该用〈回忆〉。回忆是心里的记忆，旧物是实物，不能充满在心里。"}, {"text": "妈妈在厨房里切了一个旧物，准备做晚饭。", "explanation": "这里应该用〈蔬菜〉或〈食材〉。旧物指过去用过的物品，不指可以切来做饭的食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧物", "is_correct": true, "explanation": "正确：旧物是以前用过的东西，“在旧物里找到照片”符合语境。"}, {"text": "电流", "is_correct": false, "explanation": "语义：电流是电的流动，不是可以容纳照片的处所。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不能像柜子一样放照片。"}, {"text": "星星", "is_correct": false, "explanation": "搭配：“在……里找到”需要能容纳东西的处所，星星不能容纳照片。"}], "explanations": {"旧物": "正确：旧物是以前用过的东西，“在旧物里找到照片”符合语境。", "电流": "语义：电流是电的流动，不是可以容纳照片的处所。", "空气": "语义：空气是看不见的气体，不能像柜子一样放照片。", "星星": "搭配：“在……里找到”需要能容纳东西的处所，星星不能容纳照片。"}, "sentence_index": 6, "correct_answer": "旧物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷在院子里唱起了旧物，大家都很开心。", "explanation": "这里应该用〈歌〉。旧物指过去用过的东西，不能用“唱”来说，唱的是歌。"}, {"text": "爷爷讲了一个古老的旧物。", "explanation": "这里应该用〈故事〉。故事是可以讲述的内容，旧物是实物，不能被讲述。"}, {"text": "爷爷临终前朗读了旧物，说出了他的心愿。", "explanation": "这里应该用〈信〉。朗读的是文字；旧物是实物，不能朗读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在阁楼里翻出了一把旧物。", "corrected_sentence": "她在阁楼里翻出了一件旧物。", "error_description": "量词错误：“旧物”应用“件”计量，“把”用于有柄的器具，不能用来计量旧物。正确说法是“一件旧物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把两张旧物捐给学校。", "corrected_sentence": "我想把两件旧物捐给学校。", "error_description": "量词用错：“旧物”应用“件”计量，“张”用于纸张、桌子等扁平物，应说“两件旧物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
