INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重要性说的是一个东西有多么重要。", "primary_collocate": null, "pronunciation": "zhòng yào xìng", "ipa": "ʈʂʊŋ˥˩ jɑʊ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这件事的重要性，你一定要记住。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "健康的重要性，每个人都应该明白。", "target_word": "重要性", "complexity_tier": "T3", "furigana": "jiàn kāng de zhòng yào xìng, měi gè rén dōu yīng gāi míng bái", "sentence_source": "generated"}, {"text": "你们每个人都知道水的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不懂这个工作的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈常说吃饭的重要性。", "target_word": "重要性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的话让我看到朋友的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能说说这个问题的重要性吗？", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都说安全的重要性很大。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先想一想每件事的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把时间的重要性告诉孩子。", "target_word": "重要性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "重要性：一个东西有多么重要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8ddd3f-1e11-496c-a1ad-5495bc12503a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重要性", "is_correct": true, "explanation": "正确：“这件事的重要性”指它的价值，句意是要记住这一点。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，与“这件事”不搭。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不能用来要求一件事“一定要记住”。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指外形，不能指一件事的价值。"}], "explanations": {"重要性": "正确：“这件事的重要性”指它的价值，句意是要记住这一点。", "颜色": "语义：“颜色”指事物的色彩，与“这件事”不搭。", "速度": "搭配：“速度”说快慢，不能用来要求一件事“一定要记住”。", "形状": "语义：“形状”指外形，不能指一件事的价值。"}, "sentence_index": 0, "correct_answer": "重要性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次检查的重要性很便宜。", "explanation": "这里应该用〈高〉。“便宜”说价钱，不能用来形容“重要性”；“重要性”说程度，应说“很高”。"}, {"text": "这句话的重要性很深。", "explanation": "这里应该用〈意义〉。“深”形容意义，不形容“重要性”，这句话要说“意义很深”。"}, {"text": "这件礼物的重要性很甜，我很喜欢。", "explanation": "这里应该用〈大〉。“甜”说味道，不能用来形容“重要性”；“重要性”说程度，应说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重要性", "is_correct": true, "explanation": "正确：“这个问题的重要性”指它有多重要，符合“说说”的语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，不能用于问题。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指饮食的感受，不能用于问题。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不能说“这个问题的速度”。"}], "explanations": {"重要性": "正确：“这个问题的重要性”指它有多重要，符合“说说”的语境。", "体重": "语义：“体重”指人或动物的重量，不能用于问题。", "味道": "语义：“味道”指饮食的感受，不能用于问题。", "速度": "搭配：“速度”说快慢，不能说“这个问题的速度”。"}, "sentence_index": 6, "correct_answer": "重要性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟是家里的重要性。", "explanation": "这里不能指人。〈重要性〉是抽象的程度，不能用“是”把人说成它。"}, {"text": "那只狗是我们家的重要性。", "explanation": "这里不能指动物。〈重要性〉是抽象的程度，不能用来指一只狗。"}, {"text": "这辆自行车是我们家的重要性。", "explanation": "这里不能指具体物品。〈重要性〉是抽象的程度，不能用“是”来指一辆自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水重要性很大，大家都要明白。", "corrected_sentence": "水的重要性很大，大家都要明白。", "error_description": "结构助词错误：“水”与“重要性”之间要用“的”，应说“水的重要性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你能说楚清这个问题的重要性吗？", "corrected_sentence": "你能说清楚这个问题的重要性吗？", "error_description": "补语语序错误：结果补语“清楚”要放在动词“说”后面，应说“说清楚”，不能说“说楚清”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
