INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人要小心或者注意。", "primary_collocate": null, "pronunciation": "tí xǐng", "ipa": "tʰi˨˦ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈提醒我带伞。", "target_word": "提醒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你明天提醒我给他打电话。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机每天提醒我吃药。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师提醒大家，明天要考试。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你提醒我，我差点忘了。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提醒过我，路上要小心。", "target_word": "提醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，请提醒我一下。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "闹钟响了，提醒我该起床了。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我提醒他别忘了带钥匙。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，爸爸提醒我关好门窗。", "target_word": "提醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提醒了", "label": "完成体"}, {"form": "提醒过", "label": "经验体"}, {"form": "提醒一下", "label": "动量短时"}], "register": "中性", "sense_fingerprint": "对人说话，使其注意某事或不要忘记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39e035a-dda2-4ec6-9ffc-89dfa7d4a654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提醒", "is_correct": true, "explanation": "正确答案。“提醒”tí xǐng 指让对方注意或不要忘记。"}, {"text": "题型", "is_correct": false, "explanation": "xíng（第二声）与 xǐng（第三声）声调不同，意思是题目的类型。"}, {"text": "体型", "is_correct": false, "explanation": "tǐ 与 tí、xíng 与 xǐng 的声调都不同，意思是身材的样子。"}, {"text": "梯形", "is_correct": false, "explanation": "tī 与 tí、xíng 与 xǐng 的声调都不同，意思是梯形。"}, {"text": "提请", "is_correct": false, "explanation": "qǐng 与 xǐng 声母不同（q 与 x），意思是向上级提出请求。"}], "explanations": {"提醒": "正确答案。“提醒”tí xǐng 指让对方注意或不要忘记。", "题型": "xíng（第二声）与 xǐng（第三声）声调不同，意思是题目的类型。", "体型": "tǐ 与 tí、xíng 与 xǐng 的声调都不同，意思是身材的样子。", "梯形": "tī 与 tí、xíng 与 xǐng 的声调都不同，意思是梯形。", "提请": "qǐng 与 xǐng 声母不同（q 与 x），意思是向上级提出请求。"}, "sentence_index": null, "correct_answer": "提醒"}, "level_3": {"options": [{"text": "提醒", "is_correct": true, "explanation": "“提醒”表示让对方注意，与“妈妈……我带伞”的关切语境相符，是唯一合适的选项。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指出错误并加以责备，而“带伞”是正常行为，句意不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示忘掉某事，“妈妈忘记我带伞”与提醒的语境不符。"}, {"text": "发明", "is_correct": false, "explanation": "配价：“发明”的宾语应是被创造出来的事物，不能接“我带伞”这样的小句。"}], "explanations": {"提醒": "“提醒”表示让对方注意，与“妈妈……我带伞”的关切语境相符，是唯一合适的选项。", "批评": "语义：“批评”指出错误并加以责备，而“带伞”是正常行为，句意不通。", "忘记": "语义：“忘记”表示忘掉某事，“妈妈忘记我带伞”与提醒的语境不符。", "发明": "配价：“发明”的宾语应是被创造出来的事物，不能接“我带伞”这样的小句。"}, "sentence_index": 0, "correct_answer": "提醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提醒他，他考上了大学。", "explanation": "这里是告知新消息，应该用〈告诉〉。“提醒”是让对方注意或不要忘记已知的事，不能用来通报新消息。"}, {"text": "老师提醒我们，这道题我们都做对了。", "explanation": "这里是陈述已经发生的结果，应该用〈说明〉。“提醒”是请对方注意或不要忘记，不用于陈述结果。"}, {"text": "我提醒他生日快乐。", "explanation": "这里是送祝福，应该用〈祝〉。“提醒”是让对方注意某事，不能用来表示祝福。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提醒", "is_correct": true, "explanation": "“提醒”表示请对方注意某事，与“开会前，请……我一下”的礼貌请求相符，是唯一合适的选项。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对他人帮助表示谢意，请别人感谢说话人与语境不符。"}, {"text": "指责", "is_correct": false, "explanation": "语域：“指责”语气严厉，与“请……一下”的礼貌请求不协调。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：“威胁”是以恶果相逼，与“开会前，请……我一下”的请求语境不符。"}], "explanations": {"提醒": "“提醒”表示请对方注意某事，与“开会前，请……我一下”的礼貌请求相符，是唯一合适的选项。", "感谢": "语义：“感谢”是对他人帮助表示谢意，请别人感谢说话人与语境不符。", "指责": "语域：“指责”语气严厉，与“请……一下”的礼貌请求不协调。", "威胁": "语义：“威胁”是以恶果相逼，与“开会前，请……我一下”的请求语境不符。"}, "sentence_index": 6, "correct_answer": "提醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们提醒他个子矮。", "explanation": "这里是讥笑对方，应该用〈嘲笑〉。“提醒”是善意地让对方注意，不含讥讽。"}, {"text": "我提醒了他一份礼物。", "explanation": "这里是把东西交给别人，应该用〈送〉。“提醒”不能带“礼物”这样的物品作宾语表示给予。"}, {"text": "他提醒我的眼睛很大。", "explanation": "这里是称赞对方，应该用〈夸〉。“提醒”是让对方注意某事，不含称赞的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师提醒我们一趟。", "corrected_sentence": "老师提醒我们一次。", "error_description": "错误：“提醒我们一趟”，“趟”指往返的行程，提醒的次数应用“次”。正确：“提醒我们一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他提醒我了三次。", "corrected_sentence": "他提醒了我三次。", "error_description": "错误：“了”放在了宾语“我”后面，应紧跟动词，说“提醒了我”。“了”是动词的体标记，不能放在宾语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "金属罐是一个用铁或铝做成的圆筒，可以装饮料或食物。", "primary_collocate": null, "pronunciation": "jīn shǔ guàn", "ipa": "tɕin˥˥ ʂu˨˩˦ kuan˥˩", "syllable_count": 3, "sentences": [{"text": "妈妈买了一个金属罐，用来装糖。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐可以装饮料，也可以装食物。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把喝完的金属罐压扁了。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一个红色的金属罐。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个金属罐的盖子打不开了。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐是用铁或铝做的。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把金属罐洗干净，再放进回收桶。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的架子上有三个金属罐。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐掉在地上，发出很大的声音。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在金属罐里种了一株小花。", "target_word": "金属罐", "complexity_tier": "T3", "furigana": "tā zài jīn shǔ guàn lǐ zhòng le yì zhū xiǎo huā", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "金屬罐", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用铁或铝做成的圆筒，用来装饮料或食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9757e9d-1d75-48ad-ba0e-2752e1a658ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金属罐", "is_correct": true, "explanation": "正确：金属罐是可以装东西的容器，能用来装糖。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表是计时的物件，不能用来装糖，与“用来装糖”冲突。"}, {"text": "台灯", "is_correct": false, "explanation": "搭配：“装”需要容器，台灯不是容器，不能说“用来装糖”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具用来玩耍，不是用来装糖的器具，与后半句不符。"}], "explanations": {"金属罐": "正确：金属罐是可以装东西的容器，能用来装糖。", "手表": "语义：手表是计时的物件，不能用来装糖，与“用来装糖”冲突。", "台灯": "搭配：“装”需要容器，台灯不是容器，不能说“用来装糖”。", "玩具": "语义：玩具用来玩耍，不是用来装糖的器具，与后半句不符。"}, "sentence_index": 0, "correct_answer": "金属罐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈透过金属罐看见了里面的糖。", "explanation": "这里应该用〈玻璃罐〉。玻璃罐透明，能透过它看见里面的东西；金属罐不透明，看不见里面的糖。"}, {"text": "他一口咬碎了金属罐，吞了下去。", "explanation": "这里应该用〈饼干〉。咬碎后吞下的是食物；金属罐是硬质圆筒，咬不碎，也不能吞下。"}, {"text": "水从金属罐里一直流过去。", "explanation": "这里应该用〈金属管〉。金属管两端相通，水能流过；金属罐是封闭的圆筒，水不能从中穿过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金属罐", "is_correct": true, "explanation": "正确：金属罐体积小，洗干净后可以放进回收桶。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱体积太大，放不进回收桶，与后半句冲突。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发体积太大，即使洗干净也放不进回收桶，与“再放进回收桶”不符。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“放进回收桶”要求物品能装进桶中，书桌不能放进回收桶。"}], "explanations": {"金属罐": "正确：金属罐体积小，洗干净后可以放进回收桶。", "冰箱": "语义：冰箱体积太大，放不进回收桶，与后半句冲突。", "沙发": "语义：沙发体积太大，即使洗干净也放不进回收桶，与“再放进回收桶”不符。", "书桌": "搭配：“放进回收桶”要求物品能装进桶中，书桌不能放进回收桶。"}, "sentence_index": 6, "correct_answer": "金属罐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着金属罐去上学。", "explanation": "这里应该用〈自行车〉。骑的是车；金属罐是装饮料或食物的圆筒，不能骑。"}, {"text": "金属罐把炉子里的烟排到了屋外。", "explanation": "这里应该用〈烟囱〉。烟囱专门排出烟气；金属罐不起排烟的作用。"}, {"text": "这个金属罐是用来接收信件的。", "explanation": "这里应该用〈信箱〉。信箱用来收信；金属罐是装饮料或食物的容器，不能用来收信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了两张金属罐，准备装饮料。", "corrected_sentence": "他买了两个金属罐，准备装饮料。", "error_description": "量词用错：“金属罐”应搭配量词“个”，“张”用于纸张、桌子等扁平物，应说“两个金属罐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把一条金属罐放进了柜子里。", "corrected_sentence": "妈妈把一个金属罐放进了柜子里。", "error_description": "量词用错：金属罐是圆筒形容器，应用“个”；“条”用于细长的物体，不能计量金属罐。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
