INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸箱是放东西的盒子，用纸做的。", "primary_collocate": null, "pronunciation": "zhǐ xiāng", "ipa": "ʈʂɨ˨˩˦ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "妈妈在纸箱里放了一些水果。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸箱是用来装衣服的。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一个小纸箱。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了一个纸箱装玩具。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把纸箱当成小房子玩。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸箱打开以后，里面是一双新鞋。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸箱外面写上了自己的名字。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些纸箱很轻，女孩也能拿起来。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用旧纸箱做了一个小书架。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里堆着很多纸箱。", "target_word": "纸箱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "纸箱子", "label": "复合"}, {"form": "紙箱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用纸做的、放东西的盒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2add0e14-7aad-4c53-8a62-eca53035b254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸箱", "is_correct": true, "explanation": "正确：“纸箱”是能装东西的容器，与“里”“放了一些水果”相合。"}, {"text": "思想", "is_correct": false, "explanation": "语义：“思想”不是能装水果的容器，“里”后不能接它。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不是容器，不能用来装水果。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空里”不说在里面放东西，装东西要用容器。"}], "explanations": {"纸箱": "正确：“纸箱”是能装东西的容器，与“里”“放了一些水果”相合。", "思想": "语义：“思想”不是能装水果的容器，“里”后不能接它。", "小猫": "语义：“小猫”不是容器，不能用来装水果。", "天空": "搭配：“天空里”不说在里面放东西，装东西要用容器。"}, "sentence_index": 0, "correct_answer": "纸箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我找了一块纸箱装玩具。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，纸箱是立体的箱子。"}, {"text": "我找了一把纸箱装玩具。", "explanation": "这里应该用〈个〉。“把”多用于有柄或可握持的器具，纸箱不用“把”计量。"}, {"text": "我找了一座纸箱装玩具。", "explanation": "这里应该用〈个〉。“座”用于山、桥、建筑等大型固定物，纸箱不用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸箱", "is_correct": true, "explanation": "正确：“纸箱”可以在外面写字，与“写上了自己的名字”相合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“写”需要一个能书写的表面，“空气”不能作为书写的载体。"}, {"text": "影子", "is_correct": false, "explanation": "语义：“影子”是光线造成的暗色，不能被写上名字。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：“闪电”是瞬间的光，不能用来写名字。"}], "explanations": {"纸箱": "正确：“纸箱”可以在外面写字，与“写上了自己的名字”相合。", "空气": "搭配：“写”需要一个能书写的表面，“空气”不能作为书写的载体。", "影子": "语义：“影子”是光线造成的暗色，不能被写上名字。", "闪电": "语义：“闪电”是瞬间的光，不能用来写名字。"}, "sentence_index": 6, "correct_answer": "纸箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仓库里堆着很多本纸箱。", "explanation": "这里不用〈本〉。“本”用于书籍，纸箱不用“本”计量。"}, {"text": "仓库里堆着很多颗纸箱。", "explanation": "这里不用〈颗〉。“颗”用于小而圆的东西，纸箱不用“颗”计量。"}, {"text": "仓库里堆着很多根纸箱。", "explanation": "这里不用〈根〉。“根”用于细长的条状物，纸箱不用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里放着一本纸箱。", "corrected_sentence": "仓库里放着一个纸箱。", "error_description": "“本”用于书籍，纸箱的量词应为“个”，应说“一个纸箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了三根纸箱。", "corrected_sentence": "他买了三个纸箱。", "error_description": "量词错误：“根”用于细长的东西，纸箱应配量词“个”，应说“三个纸箱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
