INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全世界都有的东西或事情。", "primary_collocate": null, "pronunciation": "quán qiú xìng", "ipa": "tɕʰɥɛn˧˥ tɕʰiou˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "水资源短缺是全球性的事情。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题不是一个国家的，而是全球性的。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这个现象有全球性，各国都有。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理是全球性的难题。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年出现了好几件全球性的大事。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料污染是全球性的，海边都能看到。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粮食不够是全球性的事，不只是我们国家。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是全球性的问题，需要各国一起解决。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上谈了几件全球性的事。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络安全也是全球性的问题。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指全世界各地都有的事情或问题，如全球性的事、全球性的难题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全球性", "is_correct": true, "explanation": "全球性指全世界都有的事情，与“水资源短缺”这种普遍存在的问题相合。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指偶然发生，而水资源短缺是长期存在的问题，两者矛盾。"}, {"text": "个人性", "is_correct": false, "explanation": "搭配：“个人性”只用于说个人的事，不能与“水资源短缺”这类社会问题搭配。"}, {"text": "突发性", "is_correct": false, "explanation": "语义：“突发性”指突然出现，与水资源短缺的长期性不符。"}], "explanations": {"全球性": "全球性指全世界都有的事情，与“水资源短缺”这种普遍存在的问题相合。", "偶然性": "语义：“偶然性”指偶然发生，而水资源短缺是长期存在的问题，两者矛盾。", "个人性": "搭配：“个人性”只用于说个人的事，不能与“水资源短缺”这类社会问题搭配。", "突发性": "语义：“突发性”指突然出现，与水资源短缺的长期性不符。"}, "sentence_index": 0, "correct_answer": "全球性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条小河是全球性的。", "explanation": "这里用错了范围。“全球性”指全世界都有的东西或事情，这条小河只在本地，应说“地方性”。"}, {"text": "我们班的校服是全球性的。", "explanation": "这里用错了范围。校服只在班里统一穿着，并不是全世界都有，应说“班级统一的”。"}, {"text": "这个方言是全球性的。", "explanation": "这里用错了范围。方言只在某些地区使用，不是全世界都有，应说“地方性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全球性", "is_correct": true, "explanation": "全球性指影响遍及全世界，与“不只是我们国家”的说法相合。"}, {"text": "地方性", "is_correct": false, "explanation": "语义：“地方性”指局限于某地，与句中“不只是我们国家”的意思正相反。"}, {"text": "局部性", "is_correct": false, "explanation": "语义：“局部性”指只涉及一部分，与句中“不只是我们国家”的范围说法矛盾。"}, {"text": "随机性", "is_correct": false, "explanation": "搭配：“随机性”说的是偶然不确定，粮食不够是长期现象，不用这个词修饰。"}], "explanations": {"全球性": "全球性指影响遍及全世界，与“不只是我们国家”的说法相合。", "地方性": "语义：“地方性”指局限于某地，与句中“不只是我们国家”的意思正相反。", "局部性": "语义：“局部性”指只涉及一部分，与句中“不只是我们国家”的范围说法矛盾。", "随机性": "搭配：“随机性”说的是偶然不确定，粮食不够是长期现象，不用这个词修饰。"}, "sentence_index": 6, "correct_answer": "全球性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题正在走向全球性。", "explanation": "这里应该用〈全球化〉。“走向”后接的是过程，“全球化”指走向全球的进程；“全球性”只表示范围性质。"}, {"text": "这种习惯在我们学校的全球性很高，几乎每个学生都有。", "explanation": "这里应该用〈普遍〉。“全球性”指东西或事情全世界都有，习惯在一所学校流行要用“普遍”。"}, {"text": "这位同学的性格很全球性。", "explanation": "这里误把〈全球性〉当成描写性格的词。“全球性”只说东西或事情全世界都有，形容人的性格应改用〈开朗〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事全球性的。", "corrected_sentence": "这件事是全球性的。", "error_description": "错误形式“这件事全球性的”，正确形式“这件事是全球性的”。“全球性的”作谓语时，前面要加“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一件全球性地事。", "corrected_sentence": "这是一件全球性的事。", "error_description": "错误形式“全球性地事”，正确形式“全球性的事”。“地”用于修饰动词，名词前的修饰语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
