INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24684, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫困", "is_correct": true, "explanation": "“富有”的反义词，指缺少钱财、生活困难。"}, {"text": "诚实", "is_correct": false, "explanation": "不是反义词：“诚实”形容为人真实可靠，与财富无关。"}, {"text": "大方", "is_correct": false, "explanation": "不是反义词：“大方”形容不吝啬，与财富的多少无关。"}, {"text": "胆小", "is_correct": false, "explanation": "不是反义词：“胆小”形容害怕、不敢做事，与财富无关。"}], "correct_answer": "贫困", "explanations": {"贫困": "“富有”的反义词，指缺少钱财、生活困难。", "诚实": "不是反义词：“诚实”形容为人真实可靠，与财富无关。", "大方": "不是反义词：“大方”形容不吝啬，与财富的多少无关。", "胆小": "不是反义词：“胆小”形容害怕、不敢做事，与财富无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24684, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有很多钱或东西。", "primary_collocate": null, "pronunciation": "fù yǒu", "ipa": "fu˥˩ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位老人很富有，有三座房子。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买得起大房子，因为他很富有。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富有的人不一定快乐。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的叔叔富有，开着两辆好车。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小生活在一个富有的家庭里。", "target_word": "富有", "complexity_tier": "T3", "furigana": "fùyǒu", "sentence_source": "generated"}, {"text": "村里最富有的人是王先生。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠做生意越来越富有了。", "target_word": "富有", "complexity_tier": "T3", "furigana": "fùyǒu", "sentence_source": "generated"}, {"text": "他很富有，每年都去国外旅行。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富有的邻居送给孩子们很多玩具。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不富有，但是过得很开心。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有很多钱或财物，能买得起很多东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富有", "is_correct": true, "explanation": "正确答案：fù yǒu，指有很多钱或东西。"}, {"text": "互有", "is_correct": false, "explanation": "hù 与 fù 声母不同（h／f），意思是互相拥有，与“富有”不同。"}, {"text": "固有", "is_correct": false, "explanation": "gù 与 fù 声母不同（g／f），意思是本来就有，与“富有”不同。"}, {"text": "复又", "is_correct": false, "explanation": "yòu 与 yǒu 声调不同（第四声与第三声），意思是又、再一次，与“富有”不同。"}], "explanations": {"富有": "正确答案：fù yǒu，指有很多钱或东西。", "互有": "hù 与 fù 声母不同（h／f），意思是互相拥有，与“富有”不同。", "固有": "gù 与 fù 声母不同（g／f），意思是本来就有，与“富有”不同。", "复又": "yòu 与 yǒu 声调不同（第四声与第三声），意思是又、再一次，与“富有”不同。"}, "sentence_index": null, "correct_answer": "富有"}, "level_3": {"options": [{"text": "富有", "is_correct": true, "explanation": "与“有三座房子”一致，说明老人拥有大量财产。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”与“老人”矛盾，句意不通。"}, {"text": "年幼", "is_correct": false, "explanation": "搭配：“年幼”只用于孩子，不能用来形容老人。"}, {"text": "贫穷", "is_correct": false, "explanation": "语义：“贫穷”与后面的“有三座房子”矛盾，句意不通。"}], "explanations": {"富有": "与“有三座房子”一致，说明老人拥有大量财产。", "年轻": "语义：“年轻”与“老人”矛盾，句意不通。", "年幼": "搭配：“年幼”只用于孩子，不能用来形容老人。", "贫穷": "语义：“贫穷”与后面的“有三座房子”矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "富有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的成本富有了。", "explanation": "这里应该用〈降低〉。富有形容人或家庭的财产，成本的减少要用降低。"}, {"text": "这张桌子很富有。", "explanation": "这里应该用〈结实〉。富有形容人或家庭拥有的钱财，桌子的牢固程度要用结实。"}, {"text": "这家公司的规模富有了。", "explanation": "这里应该用〈扩大〉。富有说人或家庭的财产，规模的扩张要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富有", "is_correct": true, "explanation": "与“做生意”相符，说明他的财富不断增加。"}, {"text": "富饶", "is_correct": false, "explanation": "搭配：“富饶”多用于土地、地区，不用来形容个人。"}, {"text": "繁荣", "is_correct": false, "explanation": "搭配：“繁荣”说市场、城市，不说人。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：“破旧”形容物品陈旧，不能用来形容人的财富变化。"}], "explanations": {"富有": "与“做生意”相符，说明他的财富不断增加。", "富饶": "搭配：“富饶”多用于土地、地区，不用来形容个人。", "繁荣": "搭配：“繁荣”说市场、城市，不说人。", "破旧": "语义：“破旧”形容物品陈旧，不能用来形容人的财富变化。"}, "sentence_index": 6, "correct_answer": "富有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的服务质量富有了。", "explanation": "这里应该用〈提高〉。富有形容人或家庭的财产，服务质量这类水平要用提高。"}, {"text": "这把椅子很富有。", "explanation": "这里应该用〈舒适〉。富有形容人或家庭拥有的钱财，椅子的舒适程度要用舒适。"}, {"text": "这家公司的开支富有了。", "explanation": "这里应该用〈减少〉。富有说人或家庭的财产，开支的缩减要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老板是当地很富有人。", "corrected_sentence": "这位老板是当地很富有的人。", "error_description": "错误形式“很富有人”，正确形式“很富有的人”。“富有”是形容词，修饰名词“人”时后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个商人做生意以后变得很富有钱。", "corrected_sentence": "这个商人做生意以后变得很富有。", "error_description": "错误：“富有”是形容词，后面不能直接带“钱”作宾语。应去掉“钱”，说“变得很富有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24686, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大事", "is_correct": true, "explanation": "正确：「小事」指不重要的事，「大事」指重要的事，二者构成反义。"}, {"text": "书籍", "is_correct": false, "explanation": "无关：「书籍」是名词，与「小事」的意思没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：「河流」指水流，与「小事」没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "无关：「天空」指地面以上的空间，与「小事」没有反义关系。"}], "correct_answer": "大事", "explanations": {"大事": "正确：「小事」指不重要的事，「大事」指重要的事，二者构成反义。", "书籍": "无关：「书籍」是名词，与「小事」的意思没有反义关系。", "河流": "无关：「河流」指水流，与「小事」没有反义关系。", "天空": "无关：「天空」指地面以上的空间，与「小事」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24686, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大事", "is_correct": true, "explanation": "正确：「小事」指不重要的事，「大事」指重要的事，二者构成反义。"}, {"text": "石头", "is_correct": false, "explanation": "无关：「石头」是矿物或岩块，与「小事」没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：「窗户」是房屋的构件，与「小事」没有反义关系。"}, {"text": "云朵", "is_correct": false, "explanation": "无关：「云朵」指天上的云，与「小事」没有反义关系。"}], "correct_answer": "大事", "explanations": {"大事": "正确：「小事」指不重要的事，「大事」指重要的事，二者构成反义。", "石头": "无关：「石头」是矿物或岩块，与「小事」没有反义关系。", "窗户": "无关：「窗户」是房屋的构件，与「小事」没有反义关系。", "云朵": "无关：「云朵」指天上的云，与「小事」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不重要的事情。", "primary_collocate": null, "pronunciation": "xiǎo shì", "ipa": "ɕiaʊ˨˩˦ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这只是一件小事，别担心。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要为小事生气。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常因为小事和朋友吵架。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我来说，这是小事。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小事不用问老师，你自己做吧。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件小事我已经处理好了。", "target_word": "小事", "complexity_tier": "T3", "furigana": "zhè jiàn xiǎoshì wǒ yǐjīng chǔlǐ hǎo le.", "sentence_source": "generated"}, {"text": "她连小事也做得很认真。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活中的小事让我很开心。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把小事看得太大。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的小事，我来帮你吧。", "target_word": "小事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}], "register": "中性", "sense_fingerprint": "无关紧要、不重要的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0cc0c3-2668-4386-9dc2-289c59985202') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小事", "is_correct": true, "explanation": "正确：「小事」指不重要的事情，即本条释义的词。"}, {"text": "小时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，「小时」意思是一小时，不是小事。"}, {"text": "小石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，「小石」意思是小石头。"}, {"text": "小食", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，「小食」意思是小吃。"}], "explanations": {"小事": "正确：「小事」指不重要的事情，即本条释义的词。", "小时": "shí（第二声）与 shì（第四声）声调不同，「小时」意思是一小时，不是小事。", "小石": "shí（第二声）与 shì（第四声）声调不同，「小石」意思是小石头。", "小食": "shí（第二声）与 shì（第四声）声调不同，「小食」意思是小吃。"}, "sentence_index": null, "correct_answer": "小事"}, "level_3": {"options": [{"text": "小事", "is_correct": true, "explanation": "正确：「这只是一件小事，别担心」中，「小事」既是不重要的事，又与「别担心」一致。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：「灾难」是严重的事，与「别担心」矛盾。"}, {"text": "明天", "is_correct": false, "explanation": "语义：「明天」是时间，不是可以用「件」计量的事物，「一件明天」不通。"}, {"text": "地震", "is_correct": false, "explanation": "搭配：「地震」与量词「件」不搭配，应说「一场地震」。"}], "explanations": {"小事": "正确：「这只是一件小事，别担心」中，「小事」既是不重要的事，又与「别担心」一致。", "灾难": "语义：「灾难」是严重的事，与「别担心」矛盾。", "明天": "语义：「明天」是时间，不是可以用「件」计量的事物，「一件明天」不通。", "地震": "搭配：「地震」与量词「件」不搭配，应说「一场地震」。"}, "sentence_index": 0, "correct_answer": "小事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只是一只小事，别担心。", "explanation": "这里应该用〈件〉。「小事」是抽象的事，量词用「件」，「只」用于动物等，不能计量它。"}, {"text": "我们在街上买了很多小事。", "explanation": "这里应该用〈小吃〉。「小事」是不重要的事情，不能买，买的是「小吃」。"}, {"text": "他最喜欢读小事。", "explanation": "这里应该用〈小说〉。「小事」不是可以读的作品，读的是「小说」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24686, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小事", "is_correct": true, "explanation": "正确：「小事」指不重要的事情，即本条释义的词。"}, {"text": "小诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，「小诗」意思是短诗。"}, {"text": "小狮", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，「小狮」意思是小狮子。"}, {"text": "小史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，「小史」意思是简短的历史书。"}], "explanations": {"小事": "正确：「小事」指不重要的事情，即本条释义的词。", "小诗": "shī（第一声）与 shì（第四声）声调不同，「小诗」意思是短诗。", "小狮": "shī（第一声）与 shì（第四声）声调不同，「小狮」意思是小狮子。", "小史": "shǐ（第三声）与 shì（第四声）声调不同，「小史」意思是简短的历史书。"}, "sentence_index": null, "correct_answer": "小事"}, "level_3": {"options": [{"text": "小事", "is_correct": true, "explanation": "正确：「她连小事也做得很认真」中，「小事」指不重要的事，「连……也」强调连小事都认真。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「天空」不是可以「做」得认真的事情，句子语义不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」不能被「做」，与「认真」的语境不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「石头」不能被「做」得认真，句子语义不通。"}], "explanations": {"小事": "正确：「她连小事也做得很认真」中，「小事」指不重要的事，「连……也」强调连小事都认真。", "天空": "语义：「天空」不是可以「做」得认真的事情，句子语义不通。", "河流": "语义：「河流」不能被「做」，与「认真」的语境不符。", "石头": "语义：「石头」不能被「做」得认真，句子语义不通。"}, "sentence_index": 6, "correct_answer": "小事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开车要小事。", "explanation": "这里应该用〈小心〉。「小心」表示注意、谨慎，是形容词或动词，不能说「小事」。"}, {"text": "他们在小事里买东西。", "explanation": "这里应该用〈小店〉。买东西要去「小店」，「小事」不是地方。"}, {"text": "小事在树上唱歌。", "explanation": "这里应该用〈小鸟〉。会唱歌的是「小鸟」，「小事」不能唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小事你不用担心。", "corrected_sentence": "这件小事你不用担心。", "error_description": "量词错误：「小事」的量词用「件」，应说「这件小事」，不能说「这只小事」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些小事们我们都要注意。", "corrected_sentence": "这些小事我们都要注意。", "error_description": "词尾错误：「小事」是抽象名词，表示复数时用「这些」，不能再加「们」，应说「这些小事」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
