INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话里藏着的意思。", "primary_collocate": null, "pronunciation": "shēn yì", "ipa": "ʂən˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他这句话有深意，你听出来了吗？", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没说完，但话里有深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这话，一定有他的深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不懂他话里的深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友笑着说了一句话，好像有深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的话很简单，却有深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为什么这样说？我想知道话里的深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说“早点回家”，这句话有深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别猜了，我这句话没有什么深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答听起来很平常，其实有深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}], "register": "书面", "sense_fingerprint": "说话人没有明说、藏在话语里的真实意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深意", "is_correct": true, "explanation": "正确答案：shēn yì，指话里藏着的、没有明说的意思。"}, {"text": "神意", "is_correct": false, "explanation": "shén 与 shēn 声调不同（第二声与第一声），意思是神的旨意，与“深意”不同。"}, {"text": "生意", "is_correct": false, "explanation": "shēng 与 shēn 韵尾不同（ng／n），意思是买卖或生计，与“深意”不同。"}, {"text": "深夜", "is_correct": false, "explanation": "yè 与 yì 韵母不同（e／i），意思是夜深的时候，与“深意”不同。"}], "explanations": {"深意": "正确答案：shēn yì，指话里藏着的、没有明说的意思。", "神意": "shén 与 shēn 声调不同（第二声与第一声），意思是神的旨意，与“深意”不同。", "生意": "shēng 与 shēn 韵尾不同（ng／n），意思是买卖或生计，与“深意”不同。", "深夜": "yè 与 yì 韵母不同（e／i），意思是夜深的时候，与“深意”不同。"}, "sentence_index": null, "correct_answer": "深意"}, "level_3": {"options": [{"text": "深意", "is_correct": true, "explanation": "与“听出来”搭配，指话里藏着的意思，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能被听出来，与“听出来”不相容。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：说话有“分量”，不说“有重量”，也不能被听出来。"}, {"text": "形状", "is_correct": false, "explanation": "语义：话没有形状，无法被听出来。"}], "explanations": {"深意": "与“听出来”搭配，指话里藏着的意思，符合句意。", "颜色": "语义：“颜色”不能被听出来，与“听出来”不相容。", "重量": "搭配：说话有“分量”，不说“有重量”，也不能被听出来。", "形状": "语义：话没有形状，无法被听出来。"}, "sentence_index": 0, "correct_answer": "深意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的深意很快。", "explanation": "这里应该用〈速度〉。深意指话里藏着的意思，电脑的快慢要用速度。"}, {"text": "这座山的深意很高。", "explanation": "这里应该用〈高度〉。深意指话里藏着的意思，山的高矮要用高度。"}, {"text": "这张桌子的深意很结实。", "explanation": "这里应该用〈结实〉。深意指话里藏着的意思，桌子的牢固程度要用结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深意", "is_correct": true, "explanation": "与“话里的”搭配，指话中藏着的意思，与前句的追问相呼应。"}, {"text": "价格", "is_correct": false, "explanation": "语义：话里不含价格，“话里的价格”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：话没有年龄，“话里的年龄”不成立。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“音量”说声音的大小，不指话里的内容。"}], "explanations": {"深意": "与“话里的”搭配，指话中藏着的意思，与前句的追问相呼应。", "价格": "语义：话里不含价格，“话里的价格”说不通。", "年龄": "语义：话没有年龄，“话里的年龄”不成立。", "音量": "搭配：“音量”说声音的大小，不指话里的内容。"}, "sentence_index": 6, "correct_answer": "深意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对工作的深意很认真。", "explanation": "这里应该用〈态度〉。深意指话里藏着的意思，人做事的认真程度要说态度。"}, {"text": "这盆花的深意很好。", "explanation": "这里应该用〈长势〉。深意指话里藏着的意思，花的生长状况要用长势。"}, {"text": "这道菜的深意很咸，我吃不下。", "explanation": "这里应该用〈味道〉。深意指话里藏着的意思，菜的咸淡、口味要用味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没听出他话里有一根深意。", "corrected_sentence": "我没听出他话里有一层深意。", "error_description": "量词错误：深意应说“一层深意”，“根”用于细长的东西，不能用于深意。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说的每句话都有一颗深意。", "corrected_sentence": "他说的每句话都有一层深意。", "error_description": "量词错误：深意应说“一层深意”；“颗”用于圆粒状的东西，不能用于深意。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24690, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "复杂与“简洁”相反，指构成部分多、不简单。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足，与物品样子的简繁无关。"}, {"text": "轻便", "is_correct": false, "explanation": "轻便指重量轻、便于携带，与样子的简繁无关。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄指空间小，与样子的简繁无关。"}], "correct_answer": "复杂", "explanations": {"复杂": "复杂与“简洁”相反，指构成部分多、不简单。", "明亮": "明亮形容光线充足，与物品样子的简繁无关。", "轻便": "轻便指重量轻、便于携带，与样子的简繁无关。", "狭窄": "狭窄指空间小，与样子的简繁无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24690, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "复杂与“简洁”相反，指构成部分多、不简单。"}, {"text": "柔和", "is_correct": false, "explanation": "柔和形容温和、不刺激，与物品样子的简繁无关。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙指事情多、忙碌，与物品样子的简繁无关。"}, {"text": "厚重", "is_correct": false, "explanation": "厚重指分量大或质地厚，与物品样子的简繁无关。"}], "correct_answer": "复杂", "explanations": {"复杂": "复杂与“简洁”相反，指构成部分多、不简单。", "柔和": "柔和形容温和、不刺激，与物品样子的简繁无关。", "繁忙": "繁忙指事情多、忙碌，与物品样子的简繁无关。", "厚重": "厚重指分量大或质地厚，与物品样子的简繁无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24690, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "物品的样子少，不复杂，容易明白。", "primary_collocate": null, "pronunciation": "jiǎn jié", "ipa": "tɕjɛn˨˩˦ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这个房间的设计很简洁。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢简洁的白色衣服。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子样子简洁，用起来方便。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机的外形非常简洁。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的家具都很简洁，没有多余的东西。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店的装修简洁大方。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个简洁的书包。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标志的图案很简洁，容易记住。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子的样子简洁，没有花。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简洁的厨房让做饭变得轻松。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物品、设计、外形样子简单，不复杂，没有多余装饰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24690, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简洁", "is_correct": true, "explanation": "jiǎn jié，指物品的样子少、不复杂，容易明白。"}, {"text": "简介", "is_correct": false, "explanation": "jié 与 jiè 声调不同（第二声与第四声），意思是简要的介绍。"}, {"text": "间接", "is_correct": false, "explanation": "jiǎn 与 jiàn、jié 与 jiē 声调都不同，意思是不直接。"}, {"text": "紧接", "is_correct": false, "explanation": "jiǎn 与 jǐn 韵母不同（ian 与 in），意思是紧跟着。"}], "explanations": {"简洁": "jiǎn jié，指物品的样子少、不复杂，容易明白。", "简介": "jié 与 jiè 声调不同（第二声与第四声），意思是简要的介绍。", "间接": "jiǎn 与 jiàn、jié 与 jiē 声调都不同，意思是不直接。", "紧接": "jiǎn 与 jǐn 韵母不同（ian 与 in），意思是紧跟着。"}, "sentence_index": null, "correct_answer": "简洁"}, "level_3": {"options": [{"text": "简洁", "is_correct": true, "explanation": "简洁修饰“设计”，指样子简单、没有多余装饰，与“很”搭配自然。"}, {"text": "冗长", "is_correct": false, "explanation": "搭配：“冗长”说的是讲话或文章的篇幅，不用来形容设计。"}, {"text": "啰嗦", "is_correct": false, "explanation": "语域：“啰嗦”口语色彩较重，且只用于说话，不形容设计。"}, {"text": "喧闹", "is_correct": false, "explanation": "语义：“喧闹”形容声音大、场面吵，不能用来形容设计。"}], "explanations": {"简洁": "简洁修饰“设计”，指样子简单、没有多余装饰，与“很”搭配自然。", "冗长": "搭配：“冗长”说的是讲话或文章的篇幅，不用来形容设计。", "啰嗦": "语域：“啰嗦”口语色彩较重，且只用于说话，不形容设计。", "喧闹": "语义：“喧闹”形容声音大、场面吵，不能用来形容设计。"}, "sentence_index": 0, "correct_answer": "简洁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很简洁。", "explanation": "这里应该用〈简单〉。“简洁”只形容物品的样子少、不复杂，形容人的性格要用“简单”。"}, {"text": "这家餐厅的菜价很简洁。", "explanation": "这里应该用〈便宜〉或〈贵〉之类形容价格的词。“简洁”只形容物品的样子少、不复杂，不能用来形容价格。"}, {"text": "这个房间的温度很简洁。", "explanation": "这里应该用〈暖和〉或〈凉快〉之类形容温度的词。“简洁”只形容物品的样子少、不复杂，不能用来形容温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24690, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "简洁", "is_correct": true, "explanation": "jiǎn jié，指物品的样子少、不复杂，容易明白。"}, {"text": "减价", "is_correct": false, "explanation": "jié 与 jià 韵母不同（ie 与 ia），意思是降低价格。"}, {"text": "剪接", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是把影片剪开再接起来。"}, {"text": "剪辑", "is_correct": false, "explanation": "jié 与 jí 韵母不同（ie 与 i），意思是对影片或录音进行剪裁编辑。"}], "explanations": {"简洁": "jiǎn jié，指物品的样子少、不复杂，容易明白。", "减价": "jié 与 jià 韵母不同（ie 与 ia），意思是降低价格。", "剪接": "jié 与 jiē 声调不同，意思是把影片剪开再接起来。", "剪辑": "jié 与 jí 韵母不同（ie 与 i），意思是对影片或录音进行剪裁编辑。"}, "sentence_index": null, "correct_answer": "简洁"}, "level_3": {"options": [{"text": "简洁", "is_correct": true, "explanation": "简洁修饰“书包”，指样子简单、不繁复，与“想买”的语境相合。"}, {"text": "繁琐", "is_correct": false, "explanation": "搭配：“繁琐”多用于手续或文字，不用来形容书包的样子。"}, {"text": "深奥", "is_correct": false, "explanation": "搭配：“深奥”用于道理或学问，不能用来形容书包。"}, {"text": "抽象", "is_correct": false, "explanation": "语义：“抽象”指没有具体形象，与“书包”这种具体实物相反。"}], "explanations": {"简洁": "简洁修饰“书包”，指样子简单、不繁复，与“想买”的语境相合。", "繁琐": "搭配：“繁琐”多用于手续或文字，不用来形容书包的样子。", "深奥": "搭配：“深奥”用于道理或学问，不能用来形容书包。", "抽象": "语义：“抽象”指没有具体形象，与“书包”这种具体实物相反。"}, "sentence_index": 6, "correct_answer": "简洁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班级的人数很简洁。", "explanation": "这里应该用〈多〉或〈少〉之类形容数量的词。“简洁”只形容物品的样子少、不复杂，不能用来形容人数。"}, {"text": "这首歌的音量很简洁。", "explanation": "这里应该用〈大〉或〈小〉之类形容音量的词。“简洁”只形容物品的样子，不能用来形容声音。"}, {"text": "这次考试的难度很简洁。", "explanation": "这里应该用〈简单〉或〈难〉之类形容难度的词。“简洁”只形容物品的样子少、不复杂，不能用来形容难度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间的设计简洁很。", "corrected_sentence": "这个房间的设计简洁得很。", "error_description": "错误形式“简洁很”，正确形式“简洁得很”。形容词后接“很”表程度时，中间要加“得”，应说“简洁得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一个简洁地书包。", "corrected_sentence": "我买了一个简洁的书包。", "error_description": "错误形式“简洁地书包”，正确形式“简洁的书包”。“地”用于修饰动词，名词前的修饰语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物产生的根源或来历。", "primary_collocate": null, "pronunciation": "qǐ yuán", "ipa": "tɕʰi˨˩˦ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "你知道端午节的起源吗？", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的起源要追溯到几百年前。", "target_word": "起源", "complexity_tier": "T3", "furigana": "zhè ge yóuxì de qǐyuán yào zhuīsù dào jǐ bǎi nián qián", "sentence_source": "generated"}, {"text": "他喜欢查各种东西的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解中国功夫的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的起源可以追溯到一千年前。", "target_word": "起源", "complexity_tier": "T3", "furigana": "zhè zuò chéngshì de qǐyuán kěyǐ zhuīsù dào yìqiān nián qián", "sentence_source": "generated"}, {"text": "这个姓的起源是什么？大家都很想知道。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我，月饼的起源是什么。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种文化都有自己的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是语言的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要了解一件事，先看它的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物产生的根源或来历", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e537b3a3-a277-4ca0-8ff4-0623d2e2b09c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源（qǐ yuán）指事物发生的源头或开始，是本题的正确答案。"}, {"text": "奇缘", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇妙的缘分，与起源不同。"}, {"text": "祈愿", "is_correct": false, "explanation": "祈愿（qíyuàn）的两个音节声调都与起源不同，意思是祈祷和希望。"}, {"text": "气源", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是气体的来源。"}], "explanations": {"起源": "起源（qǐ yuán）指事物发生的源头或开始，是本题的正确答案。", "奇缘": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇妙的缘分，与起源不同。", "祈愿": "祈愿（qíyuàn）的两个音节声调都与起源不同，意思是祈祷和希望。", "气源": "qì（第四声）与 qǐ（第三声）声调不同，意思是气体的来源。"}, "sentence_index": null, "correct_answer": "起源"}, "level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源指事物最初的发生，能与“端午节的”搭配，并符合“你知道……吗”的问句，填入此处正确。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人，不能说“端午节的身高”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，节日没有脾气，句子不通。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：节日没有尺寸，“端午节的尺寸”无法理解。"}], "explanations": {"起源": "起源指事物最初的发生，能与“端午节的”搭配，并符合“你知道……吗”的问句，填入此处正确。", "身高": "体貌：“身高”只用于人，不能说“端午节的身高”。", "脾气": "语义：“脾气”指人的性情，节日没有脾气，句子不通。", "尺寸": "语义：节日没有尺寸，“端午节的尺寸”无法理解。"}, "sentence_index": 0, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那次登山是我人生中最难忘的起源。", "explanation": "这里应该用〈经历〉。“起源”指事物最初的来源，不指亲身遭遇的事，“最难忘的”应搭配“经历”。"}, {"text": "他每月的起源很稳定。", "explanation": "这里应该用〈收入〉。“每月”和“稳定”描述的是收入，“起源”不能按月计算，也不能说稳定。"}, {"text": "他的辛苦终于换来了好的起源。", "explanation": "这里应该用〈结果〉。“换来”的是收获或结果，“起源”指最开始的阶段，不能用来换取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源指事物最初的来历，“月饼的”后接“是什么”，问的是来历，填入此处正确。"}, {"text": "学历", "is_correct": false, "explanation": "配价：“学历”需要有人作为持有者，不能用于“月饼”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”只用于人或动物，不能说“月饼的体重是什么”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人或动物的个性，月饼没有性格，句子不通。"}], "explanations": {"起源": "起源指事物最初的来历，“月饼的”后接“是什么”，问的是来历，填入此处正确。", "学历": "配价：“学历”需要有人作为持有者，不能用于“月饼”。", "体重": "体貌：“体重”只用于人或动物，不能说“月饼的体重是什么”。", "性格": "语义：“性格”指人或动物的个性，月饼没有性格，句子不通。"}, "sentence_index": 6, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件大衣的起源很便宜。", "explanation": "这里应该用〈价格〉。“便宜”描述价格，“起源”指事物的源头，不能说便宜。"}, {"text": "这台冰箱的起源很高。", "explanation": "这里应该用〈高度〉。“很高”说的是物体的高矮，“起源”指事物的源头或开始，不能用来说高矮。"}, {"text": "这个孩子的起源有一米八。", "explanation": "这里应该用〈身高〉。“有一米八”说的是人的身高，“起源”指事物的源头或开始，不能用来说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个节日的一把起源可以追溯到古代。", "corrected_sentence": "这个节日的起源可以追溯到古代。", "error_description": "量词错误：“把”用于有柄、可以握持的东西，不能用来数“起源”这样的抽象名词；应说“这个节日的起源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌的一只起源和一个雨天有关。", "corrected_sentence": "这首歌的起源和一个雨天有关。", "error_description": "量词错误：“只”多用于动物，或指成对器官、器物中的一个，不能用来数“起源”这样的抽象名词；应说“这首歌的起源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
