INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人做同一类事情的工作范围。", "primary_collocate": null, "pronunciation": "háng yè", "ipa": "xɑŋ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "餐饮行业周末特别忙。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在建筑行业做了很多年。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业里的人都很辛苦。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个行业最适合我？", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哥哥是汽车行业的工程师。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业是一个很老的行业。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业的老师傅都很有经验。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后他进了服装行业。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个行业的人常常互相帮忙。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个行业一点儿也不了解。", "target_word": "行业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "行业标准", "label": "复合"}, {"form": "行業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人从事同一类工作的范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e537b3a3-a277-4ca0-8ff4-0623d2e2b09c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24702, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "寒夜", "is_correct": false, "explanation": "hán（第二声）与 háng 的韵尾不同（n 与 ng），意思是寒冷的夜晚。"}, {"text": "行业", "is_correct": true, "explanation": "háng yè 是“行业”，指很多人做同一类事情的工作范围。"}, {"text": "糖业", "is_correct": false, "explanation": "táng 与 háng 的声母不同（t 与 h），意思是制糖的行业。"}, {"text": "黄叶", "is_correct": false, "explanation": "huáng 比 háng 多一个介音 u，意思是黄色的树叶。"}], "explanations": {"寒夜": "hán（第二声）与 háng 的韵尾不同（n 与 ng），意思是寒冷的夜晚。", "行业": "háng yè 是“行业”，指很多人做同一类事情的工作范围。", "糖业": "táng 与 háng 的声母不同（t 与 h），意思是制糖的行业。", "黄叶": "huáng 比 háng 多一个介音 u，意思是黄色的树叶。"}, "sentence_index": null, "correct_answer": "行业"}, "level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是行业，不能说“餐饮感冒周末特别忙”。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“餐饮”不能修饰“眼睛”，句子说的是经营的忙碌。"}, {"text": "行业", "is_correct": true, "explanation": "行业：“餐饮行业”指餐饮这一类工作范围，可以“周末特别忙”。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒不是工作范围，“餐饮病毒”说不通，与“周末特别忙”的语境不符。"}], "explanations": {"感冒": "语义：感冒是疾病，不是行业，不能说“餐饮感冒周末特别忙”。", "眼睛": "搭配：“餐饮”不能修饰“眼睛”，句子说的是经营的忙碌。", "行业": "行业：“餐饮行业”指餐饮这一类工作范围，可以“周末特别忙”。", "病毒": "语义：病毒不是工作范围，“餐饮病毒”说不通，与“周末特别忙”的语境不符。"}, "sentence_index": 0, "correct_answer": "行业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在语言学行业很有名。", "explanation": "这里应该用〈领域〉。学术方面的范围用领域，行业指职业所属的行当。"}, {"text": "他大学读的是计算机行业。", "explanation": "这里应该用〈专业〉。学习的方向说专业，不说行业。"}, {"text": "他在工厂里担任一个关键行业。", "explanation": "这里应该用〈岗位〉。岗位是具体的职位，行业指一类职业的总称，不能说“担任一个行业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是工作范围，“这个天气的老师傅”说不通。"}, {"text": "行业", "is_correct": true, "explanation": "行业：“这个行业的老师傅”指这一行的老师傅，与“很有经验”相符。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日不是职业范围，“这个节日的老师傅”不成立。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“这个星期”不能修饰“老师傅”，两者不搭配。"}], "explanations": {"天气": "语义：天气不是工作范围，“这个天气的老师傅”说不通。", "行业": "行业：“这个行业的老师傅”指这一行的老师傅，与“很有经验”相符。", "节日": "语义：节日不是职业范围，“这个节日的老师傅”不成立。", "星期": "搭配：“这个星期”不能修饰“老师傅”，两者不搭配。"}, "sentence_index": 6, "correct_answer": "行业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的行业是护士。", "explanation": "这里应该用〈职业〉。行业指一类职业的总称，说某人从事的具体工作要用职业。"}, {"text": "历史是一个很重要的行业。", "explanation": "这里应该用〈学科〉。历史是学科，不是职业的领域。"}, {"text": "这个行业每天早上都去跑步。", "explanation": "这里应该用〈人〉。行业是抽象的工作范围，不能做“跑步”这类动作，动作的主体应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一支行业的新人很多。", "corrected_sentence": "这个行业的新人很多。", "error_description": "量词错误：“支”用于队伍、乐器等，不能用来数行业；应说“这个行业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多行业们都在招人。", "corrected_sentence": "很多行业都在招人。", "error_description": "“们”只用于指人的名词，“行业”不能加“们”；应说“很多行业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
