INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "标识就是让人知道是什么的记号。", "primary_collocate": null, "pronunciation": "biāo shí", "ipa": "piɑʊ˥ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这个标识是什么意思？", "target_word": "标识", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "衣服的标识上写着不能用热水洗。", "target_word": "标识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的地上有方向标识。", "target_word": "标识", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们班的标识是一只小鸟。", "target_word": "标识", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看到这个标识，你就知道这里是医院。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个箱子都要有清楚的标识。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯旁边的标识不见了。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在书包上做了一个标识，免得拿错。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绿色的标识代表可以回收。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的标识很容易记住。", "target_word": "标识", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "標識", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：让人知道是什么的记号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0af34a-b903-4db2-b774-445d6bfb1c29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "标识", "is_correct": true, "explanation": "正确答案。标识（biāo shí）指让人知道是什么的记号。"}, {"text": "表示", "is_correct": false, "explanation": "biǎo（第三声）与 biāo（第一声）声调不同，shì（第四声）与 shí（第二声）声调也不同，意思是“表明”。"}, {"text": "镖师", "is_correct": false, "explanation": "第二个音节 shī 与 shí 声调不同，意思是“护送财物的人”。"}, {"text": "漂石", "is_correct": false, "explanation": "piāo 与 biāo 声母不同（p 与 b），意思是“被水流或冰川搬运来的大石块”。"}], "explanations": {"标识": "正确答案。标识（biāo shí）指让人知道是什么的记号。", "表示": "biǎo（第三声）与 biāo（第一声）声调不同，shì（第四声）与 shí（第二声）声调也不同，意思是“表明”。", "镖师": "第二个音节 shī 与 shí 声调不同，意思是“护送财物的人”。", "漂石": "piāo 与 biāo 声母不同（p 与 b），意思是“被水流或冰川搬运来的大石块”。"}, "sentence_index": null, "correct_answer": "标识"}, "level_3": {"options": [{"text": "标识", "is_correct": true, "explanation": "正确答案。“这个标识是什么意思”询问记号的含义，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是记号，不能问“这个天气是什么意思”。"}, {"text": "爱情", "is_correct": false, "explanation": "语义：爱情是抽象的情感，不能用来问“是什么意思”的记号。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不是需要解释含义的记号。"}], "explanations": {"标识": "正确答案。“这个标识是什么意思”询问记号的含义，符合语境。", "天气": "语义：天气不是记号，不能问“这个天气是什么意思”。", "爱情": "语义：爱情是抽象的情感，不能用来问“是什么意思”的记号。", "窗户": "语义：窗户是建筑部件，不是需要解释含义的记号。"}, "sentence_index": 0, "correct_answer": "标识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的标识是一百二十页。", "explanation": "这里应该用〈页数〉。标识指让人知道是什么的记号，不能用来说书有多少页。"}, {"text": "我的标识是一只猫，它喜欢睡觉。", "explanation": "这里应该用〈宠物〉。标识指记号，不能说成动物。"}, {"text": "这封信是我的标识。", "explanation": "这里应该用〈证件〉。标识只指让人知道是什么的记号，不能当作证件来证明身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标识", "is_correct": true, "explanation": "正确答案。“电梯旁边的标识不见了”指电梯旁的记号不见了，符合语境。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不会出现在电梯旁边，与语境不合。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不会出现在电梯旁边，与语境不合。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪不会出现在电梯旁边，与语境不合。"}], "explanations": {"标识": "正确答案。“电梯旁边的标识不见了”指电梯旁的记号不见了，符合语境。", "星星": "语义：星星不会出现在电梯旁边，与语境不合。", "云朵": "语义：云朵不会出现在电梯旁边，与语境不合。", "海浪": "语义：海浪不会出现在电梯旁边，与语境不合。"}, "sentence_index": 6, "correct_answer": "标识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的标识很高，大家都很尊敬他。", "explanation": "这里应该用〈标准〉。标识指记号，不能用来说人的高低，应说标准。"}, {"text": "今天的标识很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。标识指记号，“今天的标识很好”说不通；说今天的天气好要用天气。"}, {"text": "这次考试的标识很高，大家都很失望。", "explanation": "这里应该用〈分数〉。标识指记号，不能用来说考试成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上贴着一只标识，写着出口。", "corrected_sentence": "墙上贴着一个标识，写着出口。", "error_description": "错误形式：“一只标识”。正确形式：“一个标识”。标识一般用〈个〉；〈只〉多用于动物、成对的物件，或船、碗等特定物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口点着一个标识，让大家看到。", "corrected_sentence": "门口挂着一个标识，让大家看到。", "error_description": "错误形式：“点着一个标识”。正确形式：“挂着一个标识”。标识是挂或立在某处的记号，“点”不能搭配标识。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
