INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "很容易，不觉得难。", "primary_collocate": null, "pronunciation": "yì yú", "ipa": "i˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这道题的答案易于找到。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他性格开朗，易于相处。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些规则简单，易于记住。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "干木头易于燃烧，要小心用火。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个系统易于操作，一学就会。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话简单清楚，大家易于接受。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条山路平坦，易于行走。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新词一般易于传播，尤其是在网上。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜谱步骤很少，易于学会。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图画得很清楚，易于辨认。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "易於", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "易于+动词：很容易，不觉得难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0af34a-b903-4db2-b774-445d6bfb1c29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。易于（yì yú）表示很容易、不觉得难。"}, {"text": "意欲", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“想要”。"}, {"text": "立于", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是“站立在”。"}, {"text": "一语", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，yǔ 与 yú 声调也不同，意思是“一句话”。"}, {"text": "异域", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“外国、异乡”。"}], "explanations": {"易于": "正确答案。易于（yì yú）表示很容易、不觉得难。", "意欲": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“想要”。", "立于": "lì 与 yì 声母不同，意思是“站立在”。", "一语": "yī（第一声）与 yì（第四声）声调不同，yǔ 与 yú 声调也不同，意思是“一句话”。", "异域": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“外国、异乡”。"}, "sentence_index": null, "correct_answer": "易于"}, "level_3": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。“答案易于找到”表示答案很容易找到。"}, {"text": "善于", "is_correct": false, "explanation": "搭配：“善于”说人擅长某事，不能说“答案善于找到”。"}, {"text": "勇于", "is_correct": false, "explanation": "搭配：“勇于”表示敢于做某事，不能用来说答案好不好找。"}, {"text": "勤于", "is_correct": false, "explanation": "搭配：“勤于”说人勤奋，不能用来修饰“找到”这一动作。"}], "explanations": {"易于": "正确答案。“答案易于找到”表示答案很容易找到。", "善于": "搭配：“善于”说人擅长某事，不能说“答案善于找到”。", "勇于": "搭配：“勇于”表示敢于做某事，不能用来说答案好不好找。", "勤于": "搭配：“勤于”说人勤奋，不能用来修饰“找到”这一动作。"}, "sentence_index": 0, "correct_answer": "易于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他易于帮别人搬家，每次都抱怨累得要命。", "explanation": "这里应该用〈乐于〉。易于说事情做起来不费力，说愿意做某事要用乐于；句中“累得要命”与“不费力”矛盾。"}, {"text": "小王易于讲故事，每次都要反复练习。", "explanation": "这里应该用〈善于〉。易于说做起来不费力，与“每次都要反复练习”矛盾；说人擅长某件事要用善于。"}, {"text": "她易于做账，每个月都要反复核对。", "explanation": "这里应该用〈精于〉。易于说做起来不费力，与“每个月都要反复核对”矛盾；说在某方面很内行要用精于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。易于（yì yú）表示很容易、不觉得难。"}, {"text": "利于", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是“有利于”。"}, {"text": "依于", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是“依靠、取决于”。"}, {"text": "意语", "is_correct": false, "explanation": "第二个音节 yǔ（第三声）与 yú（第二声）声调不同，意思是“意大利语”。"}], "explanations": {"易于": "正确答案。易于（yì yú）表示很容易、不觉得难。", "利于": "lì 与 yì 声母不同，意思是“有利于”。", "依于": "yī（第一声）与 yì（第四声）声调不同，意思是“依靠、取决于”。", "意语": "第二个音节 yǔ（第三声）与 yú（第二声）声调不同，意思是“意大利语”。"}, "sentence_index": null, "correct_answer": "易于"}, "level_3": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。“平坦的山路易于行走”表示走起来不费力。"}, {"text": "难于", "is_correct": false, "explanation": "语义：“平坦”的路应当好走，“难于行走”与前句相矛盾。"}, {"text": "疏于", "is_correct": false, "explanation": "搭配：“疏于”表示疏忽、忽视，不能用来修饰“行走”。"}, {"text": "惯于", "is_correct": false, "explanation": "语义：“惯于行走”说的是人习惯走，与“山路平坦”的说明不相符。"}], "explanations": {"易于": "正确答案。“平坦的山路易于行走”表示走起来不费力。", "难于": "语义：“平坦”的路应当好走，“难于行走”与前句相矛盾。", "疏于": "搭配：“疏于”表示疏忽、忽视，不能用来修饰“行走”。", "惯于": "语义：“惯于行走”说的是人习惯走，与“山路平坦”的说明不相符。"}, "sentence_index": 6, "correct_answer": "易于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她易于弹钢琴，每次练琴都要反复练习。", "explanation": "这里应该用〈擅长〉。易于说做起来不费力，与“每次练琴都要反复练习”矛盾；说人在某方面做得好要用擅长。"}, {"text": "我易于早起，每天都要反复按闹钟。", "explanation": "这里应该用〈习惯〉。易于说做起来不费力，与“每天都要反复按闹钟”矛盾；说一个人常做某事要用习惯。"}, {"text": "孩子易于画画，每次画到一半都要歇好久。", "explanation": "这里应该用〈喜欢〉。易于表示做起来不费力，与“每次画到一半都要歇好久”矛盾；表示喜爱某事应用〈喜欢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份资料易于了查找，同学们都很方便。", "corrected_sentence": "这份资料易于查找，同学们都很方便。", "error_description": "错误形式：“易于了查找”。正确形式：“易于查找”。易于是后接动词的动词（表示“容易”），后面不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张表格被易于填写，老人也能看懂。", "corrected_sentence": "这张表格易于填写，老人也能看懂。", "error_description": "错误形式：“被易于填写”。正确形式：“易于填写”。易于是表示“容易”的动词，不能用在“被”字句里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
