INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24718, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请大家把需要的东西或想法说出来。", "primary_collocate": null, "pronunciation": "zhēng jí", "ipa": "ʈʂɤŋ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "班长在群里征集大家的意见。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要征集活动的好主意。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校向家长征集了意见。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司征集过员工的想法。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区正在征集宠物的名字。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想征集一些旧玩具送给孩子。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "餐厅向顾客征集新菜的名字。", "target_word": "征集", "complexity_tier": "T3", "furigana": "cān tīng xiàng gù kè zhēng jí xīn cài de míng zi", "sentence_source": "generated"}, {"text": "电台今天征集听众对新节目的建议。", "target_word": "征集", "complexity_tier": "T3", "furigana": "diàn tái jīn tiān zhēng jí tīng zhòng duì xīn jié mù de jiàn yì", "sentence_source": "generated"}, {"text": "他们把征集到的建议都写下来了。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生会征集同学们对食堂的看法。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征集了", "label": "体标"}, {"form": "征集过", "label": "体标"}, {"form": "征集令", "label": "复合"}], "register": "书面", "sense_fingerprint": "征集|请大家提出需要的东西或想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0af34a-b903-4db2-b774-445d6bfb1c29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：征集（zhēng jí），请大家把需要的东西或想法说出来。"}, {"text": "中级", "is_correct": false, "explanation": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是中级。"}, {"text": "争执", "is_correct": false, "explanation": "zhí 与 jí 声母不同（zh 与 j），意思是争论、纠纷。"}, {"text": "政绩", "is_correct": false, "explanation": "zhèng 与 zhēng 声调不同，jì 与 jí 声调也不同，意思是政绩。"}, {"text": "症结", "is_correct": false, "explanation": "jié 与 jí 韵母不同（ie 与 i），意思是问题的关键所在。"}], "explanations": {"征集": "正确答案：征集（zhēng jí），请大家把需要的东西或想法说出来。", "中级": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是中级。", "争执": "zhí 与 jí 声母不同（zh 与 j），意思是争论、纠纷。", "政绩": "zhèng 与 zhēng 声调不同，jì 与 jí 声调也不同，意思是政绩。", "症结": "jié 与 jí 韵母不同（ie 与 i），意思是问题的关键所在。"}, "sentence_index": null, "correct_answer": "征集"}, "level_3": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：“班长在群里征集大家的意见”指请大家在群里提出意见，与“意见”搭配。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”是把种子撒入土中，与“意见”无关。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”针对房屋或房间，不能用于“意见”。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”针对可见的人或物，不能拍摄意见。"}], "explanations": {"征集": "正确答案：“班长在群里征集大家的意见”指请大家在群里提出意见，与“意见”搭配。", "播种": "语义：“播种”是把种子撒入土中，与“意见”无关。", "装修": "搭配：“装修”针对房屋或房间，不能用于“意见”。", "拍摄": "搭配：“拍摄”针对可见的人或物，不能拍摄意见。"}, "sentence_index": 0, "correct_answer": "征集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在菜市场征集了一条鱼。", "explanation": "这里应该用〈买〉。征集是请大家提出需要的东西或想法，妈妈在菜市场买鱼要用买。"}, {"text": "他终于征集了这座高山。", "explanation": "这里应该用〈征服〉。征集的对象是东西或想法，不能用于高山。"}, {"text": "税务局征集了一笔税。", "explanation": "这里应该用〈征收〉。税款要强制征收，不是请大家自愿提出，不能用征集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24718, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：征集（zhēng jí），请大家把需要的东西或想法说出来。"}, {"text": "升级", "is_correct": false, "explanation": "shēng 与 zhēng 声母不同（sh 与 zh），意思是提高等级。"}, {"text": "终极", "is_correct": false, "explanation": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是最后的、最高的。"}, {"text": "正极", "is_correct": false, "explanation": "zhèng 与 zhēng 声调不同，意思是电池或电路的正极。"}, {"text": "整机", "is_correct": false, "explanation": "zhěng 与 zhēng 声调不同，jī 与 jí 声调也不同，意思是完整的机器。"}], "explanations": {"征集": "正确答案：征集（zhēng jí），请大家把需要的东西或想法说出来。", "升级": "shēng 与 zhēng 声母不同（sh 与 zh），意思是提高等级。", "终极": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是最后的、最高的。", "正极": "zhèng 与 zhēng 声调不同，意思是电池或电路的正极。", "整机": "zhěng 与 zhēng 声调不同，jī 与 jí 声调也不同，意思是完整的机器。"}, "sentence_index": null, "correct_answer": "征集"}, "level_3": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：“餐厅向顾客征集新菜的名字”指请顾客提出新菜的名字，与“名字”搭配。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”针对商品，名字不能拿来出售。"}, {"text": "盘点", "is_correct": false, "explanation": "搭配：“盘点”针对货物或账目，不说盘点菜名。"}, {"text": "批发", "is_correct": false, "explanation": "语义：“批发”是成批卖货，与请顾客提出菜名的意思无关。"}], "explanations": {"征集": "正确答案：“餐厅向顾客征集新菜的名字”指请顾客提出新菜的名字，与“名字”搭配。", "出售": "语义：“出售”针对商品，名字不能拿来出售。", "盘点": "搭配：“盘点”针对货物或账目，不说盘点菜名。", "批发": "语义：“批发”是成批卖货，与请顾客提出菜名的意思无关。"}, "sentence_index": 6, "correct_answer": "征集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府征集了这块土地。", "explanation": "这里应该用〈征用〉。土地由政府强制使用，不是请大家提出需要的东西，要用征用。"}, {"text": "他征集了今天的天气预报。", "explanation": "这里应该用〈查询〉。个人查找信息要用查询，征集是请大家提出东西或想法。"}, {"text": "工厂征集了一千台机器。", "explanation": "这里应该用〈生产〉。征集是请大家提出需要的东西或想法，工厂制造机器要用生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长在群里认真的征集了大家的意见。", "corrected_sentence": "班长在群里认真地征集了大家的意见。", "error_description": "“认真”作状语修饰动词“征集”，应用“地”，不能用“的”。应改为“班长在群里认真地征集了大家的意见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生会正在向同学们征集了对食堂的看法。", "corrected_sentence": "学生会正在向同学们征集对食堂的看法。", "error_description": "“正在”表示动作正在进行，不能与“了”同用。应去掉“了”，说“正在向同学们征集对食堂的看法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24720, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "年老", "is_correct": true, "explanation": "正确答案：“年老”与“年轻”在年龄义上构成反义。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”是形容词，但与“年轻”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”是形容词，与“年轻”的年龄义无反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”是“吵闹”的反义词，与“年轻”无反义关系。"}], "correct_answer": "年老", "explanations": {"年老": "正确答案：“年老”与“年轻”在年龄义上构成反义。", "简单": "“简单”是形容词，但与“年轻”没有反义关系。", "热情": "“热情”是形容词，与“年轻”的年龄义无反义关系。", "安静": "“安静”是“吵闹”的反义词，与“年轻”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24720, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "年老", "is_correct": true, "explanation": "正确答案：“年老”与“年轻”在年龄义上构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”是形容词，但与“年轻”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”指表面不光滑，与“年轻”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”指清楚分明，与“年轻”没有反义关系。"}], "correct_answer": "年老", "explanations": {"年老": "正确答案：“年老”与“年轻”在年龄义上构成反义。", "聪明": "“聪明”是形容词，但与“年轻”没有反义关系。", "粗糙": "“粗糙”指表面不光滑，与“年轻”没有反义关系。", "清晰": "“清晰”指清楚分明，与“年轻”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24720, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "年纪不大，比如小孩或年轻人。", "primary_collocate": null, "pronunciation": "nián qīng", "ipa": "njɛn˧˥ tɕʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "她太年轻了，不能一个人去。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的妈妈抱着孩子。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻，所以什么都想试一试。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的队伍很年轻，平均才十八岁。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么年轻就当经理，真不容易。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的老师和学生玩得很开心。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑起来像个年轻的女孩。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还年轻，路还很长。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的爸爸每天送孩子上学。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然年轻，但是做事很认真。", "target_word": "年轻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年轻人", "label": "复合"}, {"form": "年轻化", "label": "复合"}], "register": "中性", "sense_fingerprint": "年轻|年纪不大的人，如孩子、青年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0af34a-b903-4db2-b774-445d6bfb1c29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年轻", "is_correct": true, "explanation": "正确答案：“她太年轻了，不能一个人去”指年纪小，不宜独自出行，符合语境。"}, {"text": "狭小", "is_correct": false, "explanation": "语义：“狭小”形容空间，不能用来形容人的年龄。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地形，不能形容人。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境，不能用来形容人。"}], "explanations": {"年轻": "正确答案：“她太年轻了，不能一个人去”指年纪小，不宜独自出行，符合语境。", "狭小": "语义：“狭小”形容空间，不能用来形容人的年龄。", "陡峭": "搭配：“陡峭”形容地形，不能形容人。", "潮湿": "语义：“潮湿”形容环境，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "年轻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部手机很年轻，才买一个月。", "explanation": "这里应该用〈新〉。“年轻”只指人，形容手机新要用新。"}, {"text": "这本笔记本很年轻，用了好几年。", "explanation": "这里应该用〈旧〉。笔记本不是人，说用得久要用旧。"}, {"text": "这家商店很年轻，开了三十年。", "explanation": "这里应该用〈陈旧〉。商店不是人，说经营已久要用陈旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年轻", "is_correct": true, "explanation": "正确答案：“像个年轻的女孩”指外表或年纪显得小，符合语境。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”形容时间，不能形容女孩。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”多用于空间或道路，不说像个狭窄的女孩。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指能看透，不能用来形容女孩。"}], "explanations": {"年轻": "正确答案：“像个年轻的女孩”指外表或年纪显得小，符合语境。", "漫长": "语义：“漫长”形容时间，不能形容女孩。", "狭窄": "搭配：“狭窄”多用于空间或道路，不说像个狭窄的女孩。", "透明": "语义：“透明”指能看透，不能用来形容女孩。"}, "sentence_index": 6, "correct_answer": "年轻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早晨的微风很年轻，吹得人很舒服。", "explanation": "这里应该用〈清新〉。微风没有年龄，形容微风清爽要用清新。"}, {"text": "这盘水果很年轻，刚摘下来。", "explanation": "这里应该用〈新鲜〉。水果没有年龄，形容刚摘下来要用新鲜。"}, {"text": "这把青菜很年轻，炒起来很脆。", "explanation": "这里应该用〈嫩〉。青菜没有年龄，形容蔬菜鲜嫩要用嫩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个年轻地孩子很聪明。", "corrected_sentence": "这个年轻的孩子很聪明。", "error_description": "“年轻”修饰名词“孩子”，应用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说话像个年轻过的老师。", "corrected_sentence": "她说话像个年轻的老师。", "error_description": "“年轻”是形容词，修饰名词时要用“的”，不能加“过”。应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
