INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家一起想出的一个主意或计划。", "primary_collocate": null, "pronunciation": "tí àn", "ipa": "tʰi˧˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "我对周末活动有一个提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的提案听起来不错。", "target_word": "提案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都喜欢小李的提案。", "target_word": "提案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们每个人都想了一个旅行提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个提案又简单又好玩。", "target_word": "提案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的提案是去海边野餐。", "target_word": "提案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们的提案很多，我们选了一个。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁有更好的提案，请现在说。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请大家写下自己的提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起讨论，想出了三个提案。", "target_word": "提案", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "提案人", "label": "复合"}], "register": "中性", "sense_fingerprint": "提案：大家想出来的主意或计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '142dd450-e208-4e20-a103-c67974c95972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提案", "is_correct": true, "explanation": "提案：指关于周末活动的主意或计划，与句意相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能作为对周末活动的主意。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不能当作对活动的计划。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“有一个体温”不能用来说对活动的看法。"}], "explanations": {"提案": "提案：指关于周末活动的主意或计划，与句意相符。", "感冒": "语义：感冒是疾病，不能作为对周末活动的主意。", "字典": "语义：字典是工具书，不能当作对活动的计划。", "体温": "搭配：“有一个体温”不能用来说对活动的看法。"}, "sentence_index": 0, "correct_answer": "提案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题的提案是十二。", "explanation": "这里应该用〈答案〉。提案指大家想出的主意或计划，数学题的结果要说“答案”。"}, {"text": "我们每人想了一把旅行提案。", "explanation": "这里应该用〈个〉。提案用“个”计量，“把”多用于有柄的器具。"}, {"text": "我家的提案很重，两个人才搬得动。", "explanation": "这里应该用〈桌子〉。提案指大家想出的主意或计划，是抽象的，不能用来说“重”或“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提案", "is_correct": true, "explanation": "提案：同学们想出的主意或计划，与“选了一个”相符。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然现象，不能作为同学们提出的主意。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是行走的动作，不能作为提出的计划。"}, {"text": "口水", "is_correct": false, "explanation": "搭配：“口水”多与“多”“流”搭配，不与“选”搭配。"}], "explanations": {"提案": "提案：同学们想出的主意或计划，与“选了一个”相符。", "雨水": "语义：雨水是自然现象，不能作为同学们提出的主意。", "脚步": "语义：脚步是行走的动作，不能作为提出的计划。", "口水": "搭配：“口水”多与“多”“流”搭配，不与“选”搭配。"}, "sentence_index": 6, "correct_answer": "提案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们想出了三根提案。", "explanation": "这里应该用〈个〉。提案用“个”计量，“根”用于细长的东西。"}, {"text": "我们做完实验，得出了一个提案。", "explanation": "这里应该用〈结论〉。提案指大家想出的主意或计划，实验得出的是结论。"}, {"text": "这本书的提案很有趣。", "explanation": "这里应该用〈书名〉。提案指大家想出的主意或计划，书的名字要说“书名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一起想出了一条周末提案。", "corrected_sentence": "我们一起想出了一个周末提案。", "error_description": "量词错误：“提案”应用“个”，不能用“条”（“条”多用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每人都交了一本提案。", "corrected_sentence": "我们每人都交了一个提案。", "error_description": "量词错误：“提案”应用“个”或“份”，不能用“本”（“本”用于书册）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
