INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像手镯一样可以戴在身上的圆形饰物。", "primary_collocate": null, "pronunciation": "huán", "ipa": "xwan˧˥", "syllable_count": 1, "sentences": [{"text": "她手腕上戴着一个银环。", "target_word": "环", "complexity_tier": "T3", "furigana": "huán", "sentence_source": "generated"}, {"text": "这个环套在手上正好。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他送给妈妈一个银色的环。", "target_word": "环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的银环掉在地上了。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩喜欢那个红色的环。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把环戴在左手上。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个环是奶奶留给我的。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐买了一个很漂亮的环。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她摘下环，放在桌子上。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手腕上那个环是木头做的。", "target_word": "环", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个环", "label": "量词"}, {"form": "環", "label": "繁体"}], "register": "中性", "sense_fingerprint": "像手镯一样可以戴的圆形饰物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '142dd450-e208-4e20-a103-c67974c95972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "环", "is_correct": true, "explanation": "环：huán（第二声），指像手镯一样的圆形饰物，是正确答案。"}, {"text": "欢", "is_correct": false, "explanation": "huān（第一声）与 huán（第二声）声调不同，意思是高兴、喜欢。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn（第三声）与 huán（第二声）声调不同，意思是缓慢。"}, {"text": "黄", "is_correct": false, "explanation": "huáng 与 huán 韵尾不同（-ng 与 -n），意思是黄色。"}, {"text": "全", "is_correct": false, "explanation": "quán 与 huán 声母不同（q 与 h），意思是全部。"}], "explanations": {"环": "环：huán（第二声），指像手镯一样的圆形饰物，是正确答案。", "欢": "huān（第一声）与 huán（第二声）声调不同，意思是高兴、喜欢。", "缓": "huǎn（第三声）与 huán（第二声）声调不同，意思是缓慢。", "黄": "huáng 与 huán 韵尾不同（-ng 与 -n），意思是黄色。", "全": "quán 与 huán 声母不同（q 与 h），意思是全部。"}, "sentence_index": null, "correct_answer": "环"}, "level_3": {"options": [{"text": "环", "is_correct": true, "explanation": "“手腕上戴着一个银环”，环是戴在手腕上的圆形饰物，符合句意。"}, {"text": "帽", "is_correct": false, "explanation": "语义：手腕上戴的不是帽子，“帽”不是手饰，句意不通。"}, {"text": "盒", "is_correct": false, "explanation": "语义：“银盒”不能戴在手腕上，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“戴”的宾语应是饰物、手表等，不说“戴书”。"}], "explanations": {"环": "“手腕上戴着一个银环”，环是戴在手腕上的圆形饰物，符合句意。", "帽": "语义：手腕上戴的不是帽子，“帽”不是手饰，句意不通。", "盒": "语义：“银盒”不能戴在手腕上，句意不通。", "书": "搭配：“戴”的宾语应是饰物、手表等，不说“戴书”。"}, "sentence_index": 0, "correct_answer": "环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在手腕上画了一个环。", "explanation": "这里应该用〈圈〉。“画圈”指画出圆圈的痕迹；“环”指戴在身上的饰物，不用来指画出的圆圈。"}, {"text": "这副眼镜的环很轻，戴着很舒服。", "explanation": "这里应该用〈框〉。“框”指眼镜镜片周围的框架，“环”指环形饰物，不指眼镜框。"}, {"text": "她把手镯环在手腕上。", "explanation": "这里应该用〈套〉。“环”作动词是环绕的意思，把手镯套上手腕要用“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "环", "is_correct": true, "explanation": "环：huán（第二声），指像手镯一样的圆形饰物，是正确答案。"}, {"text": "换", "is_correct": false, "explanation": "huàn（第四声）与 huán（第二声）声调不同，意思是交换、更换。"}, {"text": "唤", "is_correct": false, "explanation": "huàn（第四声）与 huán（第二声）声调不同，意思是呼唤。"}, {"text": "悬", "is_correct": false, "explanation": "xuán 与 huán 声母不同（x 与 h），意思是悬挂、悬空。"}, {"text": "患", "is_correct": false, "explanation": "huàn（第四声）与 huán（第二声）声调不同，意思是患病、忧虑。"}], "explanations": {"环": "环：huán（第二声），指像手镯一样的圆形饰物，是正确答案。", "换": "huàn（第四声）与 huán（第二声）声调不同，意思是交换、更换。", "唤": "huàn（第四声）与 huán（第二声）声调不同，意思是呼唤。", "悬": "xuán 与 huán 声母不同（x 与 h），意思是悬挂、悬空。", "患": "huàn（第四声）与 huán（第二声）声调不同，意思是患病、忧虑。"}, "sentence_index": null, "correct_answer": "环"}, "level_3": {"options": [{"text": "环", "is_correct": true, "explanation": "“这个环是奶奶留给我的”，环是可以传给别人的饰物，符合句意。"}, {"text": "云", "is_correct": false, "explanation": "配价：“留给”要求可以转交的物件，云不能被留给人。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以被留下来的物品，句意不通。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾不能被留给别人，句意不通。"}], "explanations": {"环": "“这个环是奶奶留给我的”，环是可以传给别人的饰物，符合句意。", "云": "配价：“留给”要求可以转交的物件，云不能被留给人。", "雨": "语义：雨不是可以被留下来的物品，句意不通。", "雾": "语义：雾不能被留给别人，句意不通。"}, "sentence_index": 6, "correct_answer": "环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案的第三个环出了问题。", "explanation": "这里应该用〈环节〉。“环”单用指戴在身上的圆形饰物，指步骤时要说“环节”。"}, {"text": "他把钥匙环在墙上。", "explanation": "这里应该用〈挂〉。“环”作动词指环绕，此处是把钥匙挂在墙上，要用“挂”。"}, {"text": "她是这个环里的名人。", "explanation": "这里应该用〈圈子〉。“圈子”指一群人或某个范围，“环”指环形物或环节，不指人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈手上戴着一朵旧银环。", "corrected_sentence": "妈妈手上戴着一个旧银环。", "error_description": "量词错误：“朵”用于花等物，环是圆形饰物，应用“个”。正确说法是“一个旧银环”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶手上戴着一颗银环。", "corrected_sentence": "奶奶手上戴着一个银环。", "error_description": "量词错误：“颗”用于粒状的小物，环是圆形饰物，应用“个”。正确说法是“一个银环”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
