INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "画画时画出的细长的线。", "primary_collocate": null, "pronunciation": "xiàn tiáo", "ipa": "ɕjɛn⁵¹ tʰjɑʊ³⁵", "syllable_count": 2, "sentences": [{"text": "他用铅笔在纸上画线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画的线条又细又长。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明画了很多弯弯的线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先画出线条，再涂上颜色。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画的线条很轻，几乎看不见。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么画粗线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的线条在白纸上很清楚。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画错的线条可以用橡皮擦掉。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把线条画得很直。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些线条都是用毛笔画的。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "線條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "画画时画出的细长的线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a822219-d160-4040-9f20-f9a414303bd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线条", "is_correct": true, "explanation": "线条：画出的细长线，与“画”搭配，符合句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“画”不能用于歌曲。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能被画在纸上。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“画”一般不与“声音”搭配，声音不能用铅笔画出来。"}], "explanations": {"线条": "线条：画出的细长线，与“画”搭配，符合句意。", "歌曲": "语义：“画”不能用于歌曲。", "时间": "语义：时间不能被画在纸上。", "声音": "搭配：“画”一般不与“声音”搭配，声音不能用铅笔画出来。"}, "sentence_index": 0, "correct_answer": "线条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的线条很好听。", "explanation": "这里应该用〈旋律〉。“线条”指画画时画出的细长线，不能用来形容歌曲。"}, {"text": "她用线条绣了一朵花。", "explanation": "这里应该用〈丝线〉。“线条”指画画时画出的细长线，绣花用的线要说“丝线”，不能说“线条”。"}, {"text": "先画出一座线条，再涂上颜色。", "explanation": "这里量词用错了，应该用〈条〉。“座”多用于山、楼、桥等大型物体，线条应该用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线条", "is_correct": true, "explanation": "线条：画在纸上的细长线，与“白纸上很清楚”相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能画在白纸上，也不能被看到“很清楚”。"}, {"text": "脸庞", "is_correct": false, "explanation": "体貌：“脸庞”指人的脸，不能用于画在纸上的东西。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不是可以在纸上看到的东西。"}], "explanations": {"线条": "线条：画在纸上的细长线，与“白纸上很清楚”相合。", "味道": "语义：味道不能画在白纸上，也不能被看到“很清楚”。", "脸庞": "体貌：“脸庞”指人的脸，不能用于画在纸上的东西。", "体重": "语义：体重不是可以在纸上看到的东西。"}, "sentence_index": 6, "correct_answer": "线条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信的线条很工整，看得出是认真写的。", "explanation": "这里应该用〈字迹〉。写字留下的痕迹用“字迹”，“线条”指画出的细长线。"}, {"text": "这把线条都是用毛笔画的。", "explanation": "这里应该用〈些〉。“把”用于有柄的东西，线条是一组，应说“这些线条”。"}, {"text": "墙里埋着线条，不能钉钉子。", "explanation": "这里应该用〈电线〉。“线条”指画出的细长线，墙里埋着的实物线要用“电线”，不是画出的线条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子用蜡笔画出了几只彩色线条。", "corrected_sentence": "孩子用蜡笔画出了几条彩色线条。", "error_description": "量词错误：“线条”应该用量词“条”，不能用“只”。正确说法是“几条彩色线条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候过画很多线条。", "corrected_sentence": "他小时候画过很多线条。", "error_description": "“过”的位置错误：动态助词“过”应紧跟动词，应说“画过”，不能放在动词之前。正确说法是“画过很多线条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
