INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24736, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是又细致又巧妙，让人觉得很厉害。", "primary_collocate": null, "pronunciation": "jīng miào", "ipa": "tɕiŋ˥ miaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个房间的布置真精妙。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她绣的花鸟精妙极了。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位师傅雕的小龙很精妙。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜的做法非常精妙。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的计划很精妙，没有人发现问题。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器的内部结构十分精妙。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首曲子的节奏安排得很精妙。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她回答得精妙，大家都笑了。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事的结尾写得太精妙了。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块手表的设计精妙又好看。", "target_word": "精妙", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "又细致又巧妙，令人佩服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba9e274-b8ab-4e4c-bbe4-4a904cae9285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沉默寡言", "is_correct": false, "explanation": "搭配：“沉默寡言”形容人不爱说话，不能用来形容房间的布置。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色，布置不是颜色，不能说它雪白。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”指人想吃东西，与房间的布置无关。"}, {"text": "精妙", "is_correct": true, "explanation": "“精妙”形容布置细致巧妙、让人觉得很厉害，符合句意。"}], "explanations": {"沉默寡言": "搭配：“沉默寡言”形容人不爱说话，不能用来形容房间的布置。", "雪白": "体貌：“雪白”形容颜色，布置不是颜色，不能说它雪白。", "饥饿": "语义：“饥饿”指人想吃东西，与房间的布置无关。", "精妙": "“精妙”形容布置细致巧妙、让人觉得很厉害，符合句意。"}, "sentence_index": 0, "correct_answer": "精妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员很精妙，每位客人都很满意。", "explanation": "这里应该用〈热情〉。精妙形容手法、构思，不能评价服务员的态度；说服务态度好要用〈热情〉。"}, {"text": "这杯水很精妙，喝下去特别暖和。", "explanation": "这里应该用〈温〉。精妙形容手法、构思，不能形容水的温度；说水不冷不热要用〈温〉。"}, {"text": "这块毛巾很精妙，擦脸特别舒服。", "explanation": "这里应该用〈柔软〉。精妙说巧妙的构思或手法，不能形容毛巾的触感；说毛巾软要用〈柔软〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直率", "is_correct": false, "explanation": "搭配：“直率”形容人说话坦白，不能用来形容节奏的安排。"}, {"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”形容人不愿做事，不能用于形容曲子的安排。"}, {"text": "瘦长", "is_correct": false, "explanation": "体貌：“瘦长”形容人或物的体形，不能描述节奏的安排。"}, {"text": "精妙", "is_correct": true, "explanation": "“精妙”形容安排细致巧妙，符合句中“安排得很”的评价。"}], "explanations": {"直率": "搭配：“直率”形容人说话坦白，不能用来形容节奏的安排。", "懒惰": "搭配：“懒惰”形容人不愿做事，不能用于形容曲子的安排。", "瘦长": "体貌：“瘦长”形容人或物的体形，不能描述节奏的安排。", "精妙": "“精妙”形容安排细致巧妙，符合句中“安排得很”的评价。"}, "sentence_index": 6, "correct_answer": "精妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每次都很精妙，从来不迟到。", "explanation": "这里应该用〈准时〉。精妙说构思或手法，不能形容人守时；说人守时要用〈准时〉。"}, {"text": "这里的空气很精妙，我每天都想深呼吸。", "explanation": "这里应该用〈清新〉。精妙形容手法、构思，不能形容空气；说空气清新、让人想深呼吸，要用〈清新〉。"}, {"text": "这只猫很精妙，每天都在窗台上晒太阳。", "explanation": "这里应该用〈可爱〉。精妙形容手法、构思，不能形容动物的样子；说猫可爱，要用〈可爱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位厨师把菜做很精妙。", "corrected_sentence": "这位厨师把菜做得很精妙。", "error_description": "表示程度的补语要用“动词+得+形容词”，应说“做得很精妙”；“做很精妙”漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一个精妙地机关，很多人都来看。", "corrected_sentence": "这里有一个精妙的机关，很多人都来看。", "error_description": "“地”用于修饰动词，名词前的修饰语应用“的”，“精妙地机关”应说“精妙的机关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
