INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "不需要", "primary_collocate": null, "pronunciation": "wú xū", "ipa": "u˧˥ ɕy˥", "syllable_count": 2, "sentences": [{"text": "这道菜做起来很简单，无需太多时间。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用这个应用，无需注册账号。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人乘公交车无需付钱。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子已经长大了，你无需为他操心。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上就能看病，无需去医院。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "此事无需多说。", "target_word": "无需", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门票免费，无需预约。", "target_word": "无需", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器无需维修，可以用很多年。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说得很清楚，我无需再问了。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无需帮忙，我自己来。", "target_word": "无需", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "表示不需要某物或不需要做某事，常放在动词短语前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a822219-d160-4040-9f20-f9a414303bd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无需", "is_correct": true, "explanation": "正确：「无需」表示不需要，句意是这道菜不用花太多时间。"}, {"text": "无奈", "is_correct": false, "explanation": "语义：「无奈」表示没有办法，不能用来修饰时间，「无奈太多时间」不成话。"}, {"text": "无数", "is_correct": false, "explanation": "语义：「无数」形容数量多到数不清，与「太多时间」搭配不当，句子不通。"}, {"text": "无助", "is_correct": false, "explanation": "语义：「无助」形容没有依靠，不能用来说明时间的需求，句子不通。"}], "explanations": {"无需": "正确：「无需」表示不需要，句意是这道菜不用花太多时间。", "无奈": "语义：「无奈」表示没有办法，不能用来修饰时间，「无奈太多时间」不成话。", "无数": "语义：「无数」形容数量多到数不清，与「太多时间」搭配不当，句子不通。", "无助": "语义：「无助」形容没有依靠，不能用来说明时间的需求，句子不通。"}, "sentence_index": 0, "correct_answer": "无需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病房里无需保持安静。", "explanation": "这里应该用〈应该〉。病房里应该保持安静，「无需」表示不必，句子却说病房里不必保持安静，意思不对。"}, {"text": "考场上，学生无需遵守纪律。", "explanation": "这里应该用〈必须〉。考场上学生必须遵守纪律，「无需」只表示不必，与「必须」的要求相反。"}, {"text": "伤口在流血，无需包扎。", "explanation": "这里应该用〈需要〉。伤口流血时需要包扎，「无需」表示不必，与「需要」意思相反，句子说不必包扎，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无需", "is_correct": true, "explanation": "正确：「无需」表示不需要，句意是门票免费，不用提前预约。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示强制要求，与「无需」正相反，句子会变成必须预约。"}, {"text": "务必", "is_correct": false, "explanation": "语义：「务必」表示一定要做，与「无需」意思相反，句子会变成必须提前预约。"}, {"text": "只得", "is_correct": false, "explanation": "语义：「只得」表示没有办法而不得不做，与「门票免费」的轻松语境不符，也与「无需」的意思相反。"}], "explanations": {"无需": "正确：「无需」表示不需要，句意是门票免费，不用提前预约。", "必须": "语义：「必须」表示强制要求，与「无需」正相反，句子会变成必须预约。", "务必": "语义：「务必」表示一定要做，与「无需」意思相反，句子会变成必须提前预约。", "只得": "语义：「只得」表示没有办法而不得不做，与「门票免费」的轻松语境不符，也与「无需」的意思相反。"}, "sentence_index": 6, "correct_answer": "无需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客无需爱护公物。", "explanation": "这里应该用〈要〉。游客要爱护公物，「无需」表示不必，句子变成「游客不必爱护公物」，与「要」的要求相反。"}, {"text": "司机无需在红灯前停车。", "explanation": "这里应该用〈不能〉。红灯前司机不能通行，「无需」表示不必，句子却说司机不必在红灯前停车，意思不对。"}, {"text": "他快饿死了，无需吃饭。", "explanation": "这里应该用〈最好〉。他快饿死了，最好吃饭，「无需」表示不必，与「最好」的建议正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告不无需修改，直接提交就行。", "corrected_sentence": "这份报告无需修改，直接提交就行。", "error_description": "「不」与「无需」构成双重否定，句意变为需要修改，与后句「直接提交就行」矛盾。应去掉「不」，改为「无需修改」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动无需了报名，到场就行。", "corrected_sentence": "这次活动无需报名，到场就行。", "error_description": "「无需」后面不能接「了」。应去掉「了」，改为「无需报名」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
