INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "提出一个想法让大家一起做。", "primary_collocate": null, "pronunciation": "chàng yì", "ipa": "ʈʂʰɑŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "班长提出倡议，周末一起去打扫公园。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李倡议大家每天走路上班。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都同意他的倡议，明天早上一起跑步。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发出倡议，请大家带旧书来学校。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的倡议很简单：每周一起做一次饭。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们响应了这个倡议，一起种了花。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里有人倡议大家少开车。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个倡议很好，我愿意参加。", "target_word": "倡议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们接受了小王的倡议，一起帮助老人。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的倡议是，大家每天喝八杯水。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倡议书", "label": "复合"}, {"form": "倡议者", "label": "复合"}, {"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "日常里提出的、请大家一起参加的想法或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '144bdcb8-b634-4814-93d5-bb47c40a03fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "倡议：提出一个想法请大家一起做，与“提出”搭配，也与后面“周末一起去打扫公园”相合。"}, {"text": "证据", "is_correct": false, "explanation": "语义：“证据”是用来证明事情的材料，不能指向“周末一起去打扫公园”这样的行动安排。"}, {"text": "疑问", "is_correct": false, "explanation": "语义：“疑问”是对某事不明白而提出的问题，不是请大家一起去做的想法，与“周末一起去打扫公园”不相合。"}, {"text": "问卷", "is_correct": false, "explanation": "搭配：“提出”一般不和“问卷”搭配，问卷通常说“发出”。"}], "explanations": {"倡议": "倡议：提出一个想法请大家一起做，与“提出”搭配，也与后面“周末一起去打扫公园”相合。", "证据": "语义：“证据”是用来证明事情的材料，不能指向“周末一起去打扫公园”这样的行动安排。", "疑问": "语义：“疑问”是对某事不明白而提出的问题，不是请大家一起去做的想法，与“周末一起去打扫公园”不相合。", "问卷": "搭配：“提出”一般不和“问卷”搭配，问卷通常说“发出”。"}, "sentence_index": 0, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生倡议我多睡觉。", "explanation": "这里应该用〈建议〉。倡议是向大家提出一起参与的做法，对一个人的劝告要用建议。"}, {"text": "学校倡议暑假从下周五开始。", "explanation": "这里应该用〈宣布〉。倡议是请大家自愿参与的想法，学校确定暑假的开始时间要用宣布。"}, {"text": "老师倡议我早点睡。", "explanation": "这里应该用〈劝告〉。倡议用于向大家提出共同的做法，老师对某个学生的劝告要用劝告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "倡议：提出一个想法请大家一起做，与“大家少开车”这种提议相合。"}, {"text": "拆解", "is_correct": false, "explanation": "搭配：“拆解”是把物体拆开，不能用来指“大家少开车”这样的想法。"}, {"text": "抄袭", "is_correct": false, "explanation": "语义：“抄袭”是照搬他人的作品，与提出少开车的想法意思不通。"}, {"text": "诅咒", "is_correct": false, "explanation": "语域：“诅咒”是强烈的贬义词，用在公司里的普通说法中语域不合，且意思也不通。"}], "explanations": {"倡议": "倡议：提出一个想法请大家一起做，与“大家少开车”这种提议相合。", "拆解": "搭配：“拆解”是把物体拆开，不能用来指“大家少开车”这样的想法。", "抄袭": "语义：“抄袭”是照搬他人的作品，与提出少开车的想法意思不通。", "诅咒": "语域：“诅咒”是强烈的贬义词，用在公司里的普通说法中语域不合，且意思也不通。"}, "sentence_index": 6, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我倡议你周末和我一起去看电影。", "explanation": "这里应该用〈提议〉。倡议是向大家提出一起参与的想法，只向一个人发出邀请时要用提议。"}, {"text": "校长倡议全体学生在操场集合。", "explanation": "这里应该用〈命令〉。倡议只是请大家自愿参与的想法，不带强制性；要全体立即执行的事要用命令。"}, {"text": "班主任倡议我明天开会。", "explanation": "这里应该用〈通知〉。倡议用于向大家提出想法，班主任告诉学生开会的时间要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很好地倡议，我们都支持。", "corrected_sentence": "这是一个很好的倡议，我们都支持。", "error_description": "“很好”修饰名词“倡议”，应用“的”而不是“地”：应为“很好的倡议”。“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她提出了一只倡议，希望大家少用塑料袋。", "corrected_sentence": "她提出了一项倡议，希望大家少用塑料袋。", "error_description": "量词用错：“只”用于动物、成对的器官等，不能用来数“倡议”；“倡议”是抽象的想法，应用量词“项”，应为“一项倡议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旋律", "is_correct": false, "explanation": "无关：旋律指乐音的连续进行，与抽象性不构成反义或近义关系。"}, {"text": "资金", "is_correct": false, "explanation": "无关：资金指用于经营的钱，与抽象性无关。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。"}, {"text": "区域", "is_correct": false, "explanation": "无关：区域指一定范围的地方，与抽象性无关。"}], "correct_answer": "具体性", "explanations": {"旋律": "无关：旋律指乐音的连续进行，与抽象性不构成反义或近义关系。", "资金": "无关：资金指用于经营的钱，与抽象性无关。", "具体性": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。", "区域": "无关：区域指一定范围的地方，与抽象性无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矿石", "is_correct": false, "explanation": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：厨房是做饭的地方，与抽象性无关。"}, {"text": "电压", "is_correct": false, "explanation": "无关：电压是电路中的物理量，与抽象性无关。"}], "correct_answer": "具体性", "explanations": {"矿石": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。", "具体性": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。", "厨房": "无关：厨房是做饭的地方，与抽象性无关。", "电压": "无关：电压是电路中的物理量，与抽象性无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "事物不依赖具体形象，摸不到、看不到，只能靠想象或思维把握的特点，如‘爱’‘想法’这类概念。", "primary_collocate": null, "pronunciation": "chōu xiàng xìng", "ipa": "ʈʂʰoʊ˥ ɕjɑŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "“爱”的抽象性很强，很难用一句话说清楚。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不容易理解想法的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的抽象性，让我很难画出它的样子。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，爱和自由都有抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有抽象性，我们看不到也摸不到“友情”。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们常用图画来降低概念的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字有抽象性，因为你看不到“三”本身。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了“美”这个概念的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说，“时间”的抽象性让人觉得很神奇。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为“梦想”有抽象性，所以它没有样子。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "抽象性|摸不到看不到、只能想到的东西的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。“抽象性很强”指爱没有具体形象，所以很难用一句话说清楚。"}, {"text": "透明度", "is_correct": false, "explanation": "语义：透明度指清楚可见，与“很难用一句话说清楚”相矛盾。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体占的空间，“爱”没有体积，这样说不通。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：“硬度”多用于材料，不用来形容爱这样的概念。"}], "explanations": {"抽象性": "正确。“抽象性很强”指爱没有具体形象，所以很难用一句话说清楚。", "透明度": "语义：透明度指清楚可见，与“很难用一句话说清楚”相矛盾。", "体积": "语义：体积指物体占的空间，“爱”没有体积，这样说不通。", "硬度": "搭配：“硬度”多用于材料，不用来形容爱这样的概念。"}, "sentence_index": 0, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小册子的抽象性很高，连小学生都能看懂。", "explanation": "这里应该用〈通俗性〉。通俗性指浅显易懂；抽象性指不依赖具体形象，与“连小学生都能看懂”相矛盾。"}, {"text": "这首诗的抽象性很强，读起来很有画面感。", "explanation": "这里应该用〈生动〉。生动指鲜明有画面感；抽象性不依赖具体形象，与“很有画面感”相矛盾。"}, {"text": "这杯水的抽象性很强，喝起来很清爽。", "explanation": "这里应该用〈具体〉。抽象性指看不见、摸不着、靠想象把握的特点，水是看得见、摸得着的实物，应说具体的口感或状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。因为看不到“三”本身，所以说数字有抽象性。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是看得见的，与“看不到”相矛盾。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状也是可以看见的，与句中“看不到”相矛盾。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“有气味”用于可以闻到的事物，数字不与“气味”搭配。"}], "explanations": {"抽象性": "正确。因为看不到“三”本身，所以说数字有抽象性。", "颜色": "语义：颜色是看得见的，与“看不到”相矛盾。", "形状": "语义：形状也是可以看见的，与句中“看不到”相矛盾。", "气味": "搭配：“有气味”用于可以闻到的事物，数字不与“气味”搭配。"}, "sentence_index": 6, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片的抽象性很强，观众一眼就能认出里面的人。", "explanation": "这里应该用〈形象性〉。形象性指能让人看到具体样子；照片里的人能被认出，抽象性说的是看不见的特点，说不通。"}, {"text": "这个想法的抽象性很强，大家一听就懂。", "explanation": "这里应该用〈直观〉。直观指一听就能明白；抽象性指不依赖具体形象的特点，与“一听就懂”相矛盾。"}, {"text": "这辆汽车的抽象性很高，开起来很稳。", "explanation": "这里说的是错误的对象。汽车是看得见、摸得着的机器，不具有抽象性，应说具体的、实用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个概念有一片很强的抽象性，学生很难理解。", "corrected_sentence": "这个概念有一种很强的抽象性，学生很难理解。", "error_description": "量词用错：“片”多用于平面的东西，抽象性应用“种”，即“一种很强的抽象性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个概念的抽象性强很，孩子们很难想象。", "corrected_sentence": "这个概念的抽象性很强，孩子们很难想象。", "error_description": "补语位置错：程度副词“很”应放在形容词前，正确说法是“很强”，不能说“强很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
