INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "说一个事情是真的。", "primary_collocate": null, "pronunciation": "shì shí shàng", "ipa": "ʂɻ̩˥˩ ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我不是开玩笑，事实上我真的要搬家了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上去不累，事实上他已经跑了十公里。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可能不信，事实上这是我第一次坐飞机。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实上，我昨天就把作业做完了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说她会做饭，事实上她做得很好吃。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都知道，事实上汉语没有那么难。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没骗你，事实上他真的赢了比赛。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实上，这本书我已经看了三遍。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，事实上这个病很容易好。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很少说话，事实上她是个很热情的人。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话人强调某件事是真的、确实如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：「事实上」强调「我真的要搬家」确实如此，与「不是开玩笑」的语气一致。"}, {"text": "明明", "is_correct": false, "explanation": "搭配：「明明」通常与后文的「却」或「还」呼应，这里没有，搭配不当。"}, {"text": "也许", "is_correct": false, "explanation": "语义：「也许」表示推测，与「不是开玩笑」所强调的确定语气相矛盾。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：「幸亏」表示庆幸避免了不利，句中没有这层意思。"}], "explanations": {"事实上": "正确：「事实上」强调「我真的要搬家」确实如此，与「不是开玩笑」的语气一致。", "明明": "搭配：「明明」通常与后文的「却」或「还」呼应，这里没有，搭配不当。", "也许": "语义：「也许」表示推测，与「不是开玩笑」所强调的确定语气相矛盾。", "幸亏": "语义：「幸亏」表示庆幸避免了不利，句中没有这层意思。"}, "sentence_index": 0, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事实上，快把窗户关上！", "explanation": "这里应表示〈命令〉，而「事实上」在「说一个事情是真的」的意思下只用来确认事情属实，不能用来直接发出命令。"}, {"text": "事实上，祝你生日快乐！", "explanation": "这里应表示〈祝福〉，而「事实上」只用来说明事情确实如此，不能用于祝福。"}, {"text": "事实上，好的，我马上去。", "explanation": "这里应表示〈应答〉，而「事实上」只用来确认事情是真的，不能用来回应别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：「事实上」强调「他真的赢了比赛」，与「没骗你」的辩白语气一致。"}, {"text": "或许", "is_correct": false, "explanation": "语义：「或许」表示不确定，与「没骗你」所强调的确定性相矛盾。"}, {"text": "反而", "is_correct": false, "explanation": "搭配：「反而」要求前文有出乎意料的情况作对照，这里没有，搭配不当。"}, {"text": "势必", "is_correct": false, "explanation": "语域：「势必」是书面语，表示必然，与这句口语化的辩白不搭。"}], "explanations": {"事实上": "正确：「事实上」强调「他真的赢了比赛」，与「没骗你」的辩白语气一致。", "或许": "语义：「或许」表示不确定，与「没骗你」所强调的确定性相矛盾。", "反而": "搭配：「反而」要求前文有出乎意料的情况作对照，这里没有，搭配不当。", "势必": "语域：「势必」是书面语，表示必然，与这句口语化的辩白不搭。"}, "sentence_index": 6, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事实上，对不起，我来晚了。", "explanation": "这里应表示〈道歉〉，而「事实上」只用来确认事情是真的，不能用来开头表示道歉。"}, {"text": "事实上，你要去哪儿？", "explanation": "这里应表示〈询问〉，而「事实上」只用来确认事情是真的，不能引出疑问句。"}, {"text": "事实上，咱们一起去吃饭吧。", "explanation": "这里应表示〈建议〉，而「事实上」只用来确认事情是真的，不能用来提出建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我本以为今天会下雨，事实上了天气很好。", "corrected_sentence": "我本以为今天会下雨，事实上天气很好。", "error_description": "错误：「事实上」后面多加了「了」，写成「事实上了」。正确：「事实上」是副词，修饰后面的分句，不带「了」，应写成「事实上天气很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都以为他已经回家了，事实上却他还在公司。", "corrected_sentence": "大家都以为他已经回家了，事实上他却还在公司。", "error_description": "错误：「却」放在了主语「他」前面。正确：「却」应放在主语之后，写成「事实上他却还在公司」；「事实上却他」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "趋异", "is_correct": true, "explanation": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。"}, {"text": "效率", "is_correct": false, "explanation": "“效率”指单位时间内的工作成果，与“趋同”没有反义关系。"}, {"text": "节奏", "is_correct": false, "explanation": "“节奏”指事物有规律的快慢变化，与“趋同”不构成反义。"}, {"text": "规律", "is_correct": false, "explanation": "“规律”指事物内在的必然联系，与“趋同”不构成反义。"}], "correct_answer": "趋异", "explanations": {"趋异": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。", "效率": "“效率”指单位时间内的工作成果，与“趋同”没有反义关系。", "节奏": "“节奏”指事物有规律的快慢变化，与“趋同”不构成反义。", "规律": "“规律”指事物内在的必然联系，与“趋同”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "趋异", "is_correct": true, "explanation": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。"}, {"text": "方向", "is_correct": false, "explanation": "“方向”指事物所朝的位置，与“趋同”不构成反义。"}, {"text": "结构", "is_correct": false, "explanation": "“结构”指各组成部分的组织和排列，与“趋同”不构成反义。"}, {"text": "年龄", "is_correct": false, "explanation": "“年龄”指人已经活过的年数，与“趋同”不构成反义。"}], "correct_answer": "趋异", "explanations": {"趋异": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。", "方向": "“方向”指事物所朝的位置，与“趋同”不构成反义。", "结构": "“结构”指各组成部分的组织和排列，与“趋同”不构成反义。", "年龄": "“年龄”指人已经活过的年数，与“趋同”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指不同的事情慢慢变得一样。", "primary_collocate": null, "pronunciation": "qū tóng", "ipa": "tɕʰy˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "两个城市的样子慢慢趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在一起后，孩子和父母的想法慢慢趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间长了，两个人的口音趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家店的菜单越来越趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的穿衣风格正在慢慢趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的看法一开始不同，后来趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的爱好有趋同的特点。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢慢地，两种方言的说法趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司的产品渐渐趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，各地学校的做法趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨同", "label": "繁体"}, {"form": "趋同化", "label": "复合"}, {"form": "趋同性", "label": "复合"}], "register": "中性", "sense_fingerprint": "趋同|不同的事情慢慢变得一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确：趋同 qū tóng，指不同的事情慢慢变得一样。"}, {"text": "驱动", "is_correct": false, "explanation": "qū dòng 与 qū tóng 的声母不同（t 与 d），意思是推动机器或事物运转。"}, {"text": "去痛", "is_correct": false, "explanation": "qù tòng 与 qū tóng 两个音节的声调都不同，意思是减轻疼痛。"}, {"text": "驱虫", "is_correct": false, "explanation": "qū chóng 与 qū tóng 的第二音节声母不同（t 与 ch），意思是杀灭或驱赶害虫。"}], "explanations": {"趋同": "正确：趋同 qū tóng，指不同的事情慢慢变得一样。", "驱动": "qū dòng 与 qū tóng 的声母不同（t 与 d），意思是推动机器或事物运转。", "去痛": "qù tòng 与 qū tóng 两个音节的声调都不同，意思是减轻疼痛。", "驱虫": "qū chóng 与 qū tóng 的第二音节声母不同（t 与 ch），意思是杀灭或驱赶害虫。"}, "sentence_index": null, "correct_answer": "趋同"}, "level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确：“趋同”指不同的事情慢慢变得一样，与“慢慢”和“样子”搭配。"}, {"text": "对立", "is_correct": false, "explanation": "搭配：“对立”指双方或观点相互冲突，不能用来说城市的样子对立。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”只用于人或动物，不能说城市的样子发胖。"}, {"text": "比较", "is_correct": false, "explanation": "配价：“比较”需要被比较的双方，单独说“样子慢慢比较了”，句子不完整。"}], "explanations": {"趋同": "正确：“趋同”指不同的事情慢慢变得一样，与“慢慢”和“样子”搭配。", "对立": "搭配：“对立”指双方或观点相互冲突，不能用来说城市的样子对立。", "发胖": "体貌：“发胖”只用于人或动物，不能说城市的样子发胖。", "比较": "配价：“比较”需要被比较的双方，单独说“样子慢慢比较了”，句子不完整。"}, "sentence_index": 0, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司的业务越来越趋同，差别却越来越大。", "explanation": "这里应该用〈分化〉。趋同指原本不同的事物慢慢变得一样，与“差别越来越大”矛盾；说差别越来越大要用〈分化〉。"}, {"text": "这件红外套的颜色慢慢趋同了。", "explanation": "这里应该用〈褪色〉。趋同需要两个或以上的事物逐渐变得一样，单件外套的颜色变淡不能说趋同。"}, {"text": "两人的看法一向趋同。", "explanation": "这里应该用〈一致〉。“一向”表示长期保持的状态，趋同指原本不同的事物逐渐变一样，两者矛盾；描述一直相同用〈一致〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确：“趋同”修饰“特点”，指爱好逐渐变得一致的特点。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“年轻人”的说法相矛盾。"}, {"text": "苍老", "is_correct": false, "explanation": "体貌：“苍老”只说人的样貌，不能用来形容爱好的特点。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“年轻人”和“爱好”的意思不相符。"}], "explanations": {"趋同": "正确：“趋同”修饰“特点”，指爱好逐渐变得一致的特点。", "年迈": "语义：“年迈”指年纪很大，与“年轻人”的说法相矛盾。", "苍老": "体貌：“苍老”只说人的样貌，不能用来形容爱好的特点。", "退休": "语义：“退休”指离开工作岗位，与“年轻人”和“爱好”的意思不相符。"}, "sentence_index": 6, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个班的教材虽然一直相同，却越来越趋同。", "explanation": "这里应该用〈始终一致〉。趋同指原本不同的事物慢慢变一样，已经一直相同的教材不会“越来越趋同”，前后矛盾。"}, {"text": "这只碗的大小趋同了。", "explanation": "这里应该用〈一样〉。趋同需要两个或两个以上的事物慢慢靠近，单独一只碗不能趋同，比较两者相同要用〈一样〉。"}, {"text": "这两家公司已经趋同，合并成了一家。", "explanation": "这里应该用〈融合〉。趋同指原本不同的事物慢慢变得相近，并不是合成一个整体；说合为一体要用〈融合〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家店的装修风格逐渐被趋同了。", "corrected_sentence": "这两家店的装修风格逐渐趋同了。", "error_description": "“趋同”是不及物动词，不能用“被”字句表示被动。应去掉“被”，说“风格逐渐趋同了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，各地学校把教学方法逐渐趋同了。", "corrected_sentence": "这几年，各地学校的教学方法逐渐趋同了。", "error_description": "“趋同”是不及物动词，不能用“把”字句处理它的主语，应说“各地学校的教学方法逐渐趋同了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩小", "is_correct": true, "explanation": "“缩小”与“扩展”意思相反，指范围、规模变小。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“扩展”没有反义关系，指动脑子想问题。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”与“扩展”没有反义关系，指停下来不做事、恢复精力。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”与“扩展”没有反义关系，指仔细看、察看。"}], "correct_answer": "缩小", "explanations": {"缩小": "“缩小”与“扩展”意思相反，指范围、规模变小。", "思考": "“思考”与“扩展”没有反义关系，指动脑子想问题。", "休息": "“休息”与“扩展”没有反义关系，指停下来不做事、恢复精力。", "观察": "“观察”与“扩展”没有反义关系，指仔细看、察看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收缩", "is_correct": true, "explanation": "“收缩”与“扩展”意思相反，指面积、体积变小。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“扩展”没有反义关系，指在水中运动。"}, {"text": "回答", "is_correct": false, "explanation": "“回答”与“扩展”没有反义关系，指对问题作出应答。"}, {"text": "赞美", "is_correct": false, "explanation": "“赞美”与“扩展”没有反义关系，指称赞、夸奖。"}], "correct_answer": "收缩", "explanations": {"收缩": "“收缩”与“扩展”意思相反，指面积、体积变小。", "游泳": "“游泳”与“扩展”没有反义关系，指在水中运动。", "回答": "“回答”与“扩展”没有反义关系，指对问题作出应答。", "赞美": "“赞美”与“扩展”没有反义关系，指称赞、夸奖。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更大或更多。", "primary_collocate": null, "pronunciation": "kuò zhǎn", "ipa": "kʰuo⁵¹ ʈʂan²¹⁴", "syllable_count": 2, "sentences": [{"text": "学校想扩展这个操场。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司准备扩展新的市场。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把店扩展了一倍。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市在向外扩展。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们想扩展一下自己的知识。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算扩展生意。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂扩展以后，需要更多工人。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在扩展海外业务。", "target_word": "扩展", "complexity_tier": "T3", "furigana": "zhè jiā gōngsī zhèngzài kuòzhǎn hǎiwài yèwù", "sentence_source": "generated"}, {"text": "图书馆扩展了，书也多了。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园的面积还会继续扩展。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩展了", "label": "体标"}, {"form": "扩展过", "label": "体标"}, {"form": "扩展性", "label": "复合"}, {"form": "擴展", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使范围、规模、面积变大或变多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c432fe6-4db2-4f87-8eb1-bd238a86f80d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能说“吃这个操场”。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”要带感谢的对象（人或帮助），不能直接带“操场”。"}, {"text": "扩展", "is_correct": true, "explanation": "“扩展”指使操场的范围变大，与“学校想……这个操场”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱这个操场”。"}], "explanations": {"吃": "搭配：“吃”的对象应是食物，不能说“吃这个操场”。", "感谢": "配价：“感谢”要带感谢的对象（人或帮助），不能直接带“操场”。", "扩展": "“扩展”指使操场的范围变大，与“学校想……这个操场”的语境相合。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱这个操场”。"}, "sentence_index": 0, "correct_answer": "扩展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很扩展，大家都有点怕他。", "explanation": "这里应该用〈暴躁〉。扩展指范围、规模的扩大，形容脾气要用“暴躁”之类的词。"}, {"text": "这个孩子很扩展，老师都很喜欢他。", "explanation": "这里应该用〈活泼〉。扩展是动词，指范围、规模变大，不能用来形容孩子的性格。"}, {"text": "这盘菜很扩展，我吃得很香。", "explanation": "这里应该用〈鲜美〉。扩展指范围、规模变大，形容味道要用“鲜美”之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩减", "is_correct": false, "explanation": "语义：“缩减”与后半句“需要更多工人”的意思相矛盾，前后不合理。"}, {"text": "扩展", "is_correct": true, "explanation": "“扩展”指工厂规模变大，扩大后才需要更多工人，前后逻辑合理。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能说“工厂驾驶”。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是人或动物的动作，工厂不会咳嗽。"}], "explanations": {"缩减": "语义：“缩减”与后半句“需要更多工人”的意思相矛盾，前后不合理。", "扩展": "“扩展”指工厂规模变大，扩大后才需要更多工人，前后逻辑合理。", "驾驶": "搭配：“驾驶”的对象是车辆，不能说“工厂驾驶”。", "咳嗽": "搭配：“咳嗽”是人或动物的动作，工厂不会咳嗽。"}, "sentence_index": 6, "correct_answer": "扩展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的眼神很扩展，让人感到害怕。", "explanation": "这里应该用〈凶狠〉。扩展指范围、规模变大，形容眼神要用“凶狠”之类的词。"}, {"text": "这件衣服的颜色很扩展，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。扩展指范围、规模变大，形容颜色要用“鲜艳”之类的词。"}, {"text": "这首歌的旋律很扩展，听起来很舒服。", "explanation": "这里应该用〈优美〉。扩展指范围、规模变大，形容旋律要用“优美”之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把厂房扩展更大。", "corrected_sentence": "我们要把厂房扩展得更大。", "error_description": "错误：“扩展”后缺少补语标记“得”。正确：“扩展得更大”，“得”引出结果补语，说明扩展后的程度；学习者常漏掉“得”，应为“把……扩展得更大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司已经把海外业务扩展。", "corrected_sentence": "这家公司已经把海外业务扩展了。", "error_description": "错误：“把”字句的谓语动词“扩展”后缺少“了”，句子不完整。正确：“把海外业务扩展了”。“把”字句中动词后通常要有“了”或补语等成分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
