INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事做得更细致、更清楚。", "primary_collocate": null, "pronunciation": "xì huà", "ipa": "ɕi˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "这个问题要再细化，才能说清楚。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旅行计划细化到每个小时。", "target_word": "细化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们细化作文的第二段。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想做好，必须先细化步骤。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们细化过工作表，现在更清楚了。", "target_word": "细化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师把做菜的步骤细化了一遍。", "target_word": "细化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规定写得太简单，应该再细化。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请细化一下你说的第三点。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在细化新学期的课程安排。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "设计图细化以后，工人就容易看懂了。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "细化了", "label": "体标"}, {"form": "细化过", "label": "体标"}, {"form": "細化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "细化：把一件事做得更细致、更清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45df6f4-fea3-4a2d-97bd-60bf38d18862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "细化", "is_correct": true, "explanation": "正确：细化是把问题讲得更细致，“要再细化，才能说清楚”语境相符。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却指降低温度，与“问题”无关。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：装订用于纸张，“问题”不能被装订。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是去掉水分，与把问题说清楚无关。"}], "explanations": {"细化": "正确：细化是把问题讲得更细致，“要再细化，才能说清楚”语境相符。", "冷却": "语义：冷却指降低温度，与“问题”无关。", "装订": "搭配：装订用于纸张，“问题”不能被装订。", "烘干": "语义：烘干是去掉水分，与把问题说清楚无关。"}, "sentence_index": 0, "correct_answer": "细化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们细化了客厅，还换了新沙发。", "explanation": "这里应该用〈装修〉。细化指把事情做得更细致，不能用来指改造房间；装修房间要用〈装修〉。"}, {"text": "他每天细化厨房，很辛苦。", "explanation": "这里应该用〈清洁〉。细化指把事情做得更细致，不是打扫；打扫厨房要用〈清洁〉。"}, {"text": "他用布细化了桌子。", "explanation": "这里应该用〈擦拭〉。细化是把事情做得更细致，不表示擦拭东西；擦桌子要用〈擦拭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细化", "is_correct": true, "explanation": "正确：细化是使规定更具体，“应该再细化”与“写得太简单”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热食物，与规定的内容无关。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：晾晒用于衣物或食物，不能用于规定。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”的对象是表面，不能用于规定。"}], "explanations": {"细化": "正确：细化是使规定更具体，“应该再细化”与“写得太简单”的语境相符。", "煮": "语义：煮是加热食物，与规定的内容无关。", "晾晒": "语义：晾晒用于衣物或食物，不能用于规定。", "涂抹": "搭配：“涂抹”的对象是表面，不能用于规定。"}, "sentence_index": 6, "correct_answer": "细化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把一块石头细化了，然后扔进了河里。", "explanation": "这里应该用〈砸碎〉。细化指把事情做得更细致，不表示把石头弄碎；把石头弄碎要用〈砸碎〉。"}, {"text": "他不小心把花瓶细化了。", "explanation": "这里应该用〈打碎〉。细化不能表示把东西弄碎；花瓶碎了要用〈打碎〉。"}, {"text": "他在台上细化了一首歌。", "explanation": "这里应该用〈演唱〉。细化不能表示唱歌；在台上唱歌要用〈演唱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把作文细化很清楚。", "corrected_sentence": "老师把作文细化得很清楚。", "error_description": "补语错：程度补语前要加“得”，应说“细化得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把计划细化的很仔细。", "corrected_sentence": "我们把计划细化得很仔细。", "error_description": "补语错：程度补语前应用“得”，不能用“的”，应说“细化得很仔细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
