INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在主要的东西之外，再增加上别的东西。", "primary_collocate": null, "pronunciation": "fù jiā", "ipa": "fu˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "买蛋糕时，店员又附加了一张优惠券。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报名表后面要附加一张照片。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在课程之外，又附加了一节练习课。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份计划太复杂，请不要再附加新内容。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给了一个题目，还附加了一个小问题。", "target_word": "附加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏附加了很多有意思的功能。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一张纸条附加在报告后面。", "target_word": "附加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对这次活动附加了一项规定。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在文件后面附加一份身份证复印件。", "target_word": "附加", "complexity_tier": "T3", "furigana": "qǐng zài wén jiàn hòu miàn fù jiā yí fèn shēn fèn zhèng fù yìn jiàn.", "sentence_source": "generated"}, {"text": "菜单后面又附加了一页饮料单。", "target_word": "附加", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "附加了", "label": "体标"}, {"form": "附加过", "label": "体标"}, {"form": "附加条件", "label": "复合"}, {"form": "附加费", "label": "复合"}], "register": "书面", "sense_fingerprint": "附加：在主要的东西之外再增加别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45df6f4-fea3-4a2d-97bd-60bf38d18862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "附加", "is_correct": true, "explanation": "“附加”表示在买蛋糕的基础上另外再加上一张优惠券，与句中“又”的语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，优惠券不能被喝。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指使东西燃烧，与店员另外给予优惠券的意思不符。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：撕毁指撕破、毁坏，店员撕毁优惠券与“又附加”的意思不符。"}], "explanations": {"附加": "“附加”表示在买蛋糕的基础上另外再加上一张优惠券，与句中“又”的语境相符。", "喝": "搭配：“喝”的宾语是饮品，优惠券不能被喝。", "烧": "语义：“烧”指使东西燃烧，与店员另外给予优惠券的意思不符。", "撕毁": "语义：撕毁指撕破、毁坏，店员撕毁优惠券与“又附加”的意思不符。"}, "sentence_index": 0, "correct_answer": "附加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的人口附加了三百万。", "explanation": "这里应该用〈增加〉。附加用于另外加上条件或内容，人口数量的增长要用增加。"}, {"text": "我用力附加了那扇门。", "explanation": "这里应该用〈推开〉。附加指在主要的东西之外再增加别的东西，用力把门推开要用推开。"}, {"text": "科学家附加了一颗新星。", "explanation": "这里应该用〈发现〉。附加表示在已有的事物之外另加上东西，找到原本未知的天体要用发现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附加", "is_correct": true, "explanation": "“附加”表示把纸条另外加在报告后面，与“在报告后面”的位置相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，纸条不能被吃。"}, {"text": "炒", "is_correct": false, "explanation": "语义：“炒”指用锅加热烹调食物，纸条不能被炒。"}, {"text": "施", "is_correct": false, "explanation": "语域：“施”是书面词，用在这样的叙述里不协调。"}], "explanations": {"附加": "“附加”表示把纸条另外加在报告后面，与“在报告后面”的位置相符。", "吃": "搭配：“吃”的宾语是食物，纸条不能被吃。", "炒": "语义：“炒”指用锅加热烹调食物，纸条不能被炒。", "施": "语域：“施”是书面词，用在这样的叙述里不协调。"}, "sentence_index": 6, "correct_answer": "附加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水的水位附加了两米。", "explanation": "这里应该用〈下降〉。附加表示另外加上东西，水位降低要用下降。"}, {"text": "他一口气附加了一大碗饭。", "explanation": "这里应该用〈吃〉。附加指在主要的东西之外再增加别的东西，把饭吃下去要用吃。"}, {"text": "那场球赛他们附加了冠军。", "explanation": "这里应该用〈赢得〉。附加不能指取得荣誉，得到冠军要用赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把一道题附加考卷后面。", "corrected_sentence": "学校把一道题附加在考卷后面。", "error_description": "介词漏用：“附加”后面的处所要用“在”引出，应说“附加在考卷后面”，不能省掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员又附加了过一份赠品。", "corrected_sentence": "店员又附加过一份赠品。", "error_description": "错误：“附加了过”；正确：“附加过”。“了”表示完成，“过”表示经历，两者不能同时用在同一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
