INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得适合当地人的用法。", "primary_collocate": null, "pronunciation": "běn tǔ huà", "ipa": "pən˨˩˦ tʰu˨˩˦ xua˥˩", "syllable_count": 3, "sentences": [{"text": "这家店把外国菜本土化了。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把这个软件本土化。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国电影要本土化，才能让当地人喜欢。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在本土化这款手机游戏。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些外国品牌都在努力本土化。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板决定把菜单本土化，加入辣味。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动画片本土化以后，更受孩子欢迎。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饮料公司把广告语本土化了。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想在中国卖得好，就得本土化。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个外国节日已经本土化了。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本土化了", "label": "体标"}, {"form": "本土化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "本土化|动词|使外来东西适合当地人使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45df6f4-fea3-4a2d-97bd-60bf38d18862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本土化", "is_correct": true, "explanation": "正确：本土化作动词，表示使外国菜适应当地口味，句意通顺。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：装修用于房屋、店面，不用于菜品。"}, {"text": "扩建", "is_correct": false, "explanation": "语义：扩建指扩大建筑，与改变菜品的口味不符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除用于建筑、设施，不能用于菜品。"}], "explanations": {"本土化": "正确：本土化作动词，表示使外国菜适应当地口味，句意通顺。", "装修": "搭配：装修用于房屋、店面，不用于菜品。", "扩建": "语义：扩建指扩大建筑，与改变菜品的口味不符。", "拆除": "语义：拆除用于建筑、设施，不能用于菜品。"}, "sentence_index": 0, "correct_answer": "本土化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我本土化了一下午的作业，终于做完了。", "explanation": "这里应该用〈完成〉。本土化指使事物适应当地，做完作业要用完成。"}, {"text": "妈妈把这块蛋糕本土化成了面条。", "explanation": "这里应该用〈做成〉。本土化指使事物适应当地，把蛋糕变成面条是改变形态，要用做成。"}, {"text": "他本土化了那道数学题，很快就算出了答案。", "explanation": "这里应该用〈解答〉。本土化指使事物适应当地，算出数学题的答案要用解答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本土化", "is_correct": true, "explanation": "正确：本土化作动词，“动画片本土化以后，更受孩子欢迎”说的是经过适应当地的调整。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：生锈指金属氧化，动画片不会生锈。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁会让作品无法播放，与“更受孩子欢迎”矛盾。"}, {"text": "上漆", "is_correct": false, "explanation": "搭配：上漆用于物体表面，不用于动画片。"}], "explanations": {"本土化": "正确：本土化作动词，“动画片本土化以后，更受孩子欢迎”说的是经过适应当地的调整。", "生锈": "语义：生锈指金属氧化，动画片不会生锈。", "烧毁": "语义：烧毁会让作品无法播放，与“更受孩子欢迎”矛盾。", "上漆": "搭配：上漆用于物体表面，不用于动画片。"}, "sentence_index": 6, "correct_answer": "本土化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他本土化了那袋大米，全家人一顿就吃完了。", "explanation": "这里应该用〈煮〉。本土化指使事物适应当地，要把大米煮熟才能吃，要用煮。"}, {"text": "他本土化了那封信，很快就读完了。", "explanation": "这里应该用〈读〉。本土化指使事物适应当地，读信要用读。"}, {"text": "师傅本土化了断裂的桥，车又能通行了。", "explanation": "这里应该用〈修复〉。本土化是使事物适应当地，断裂的桥要修复才能通行，不能靠适应当地来恢复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把这款游戏本土化。", "corrected_sentence": "他们把这款游戏本土化了。", "error_description": "错误：“把”字句中，动词“本土化”后面缺少“了”等成分。正确：应说“把……本土化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司已经把菜单本土化着。", "corrected_sentence": "这家公司已经把菜单本土化了。", "error_description": "错误：“着”用错。正确：应用“了”。“已经”表示动作完成，要用完成标记“了”，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
