INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "符号学是研究记号怎么表达意思的学问。", "primary_collocate": null, "pronunciation": "fú hào xué", "ipa": "fu˧˥ xɑʊ˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "符号学告诉我们，路标是怎么表达意思的。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥在大学里学符号学。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学了符号学，我才明白表情也是一种符号。", "target_word": "符号学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号学课上，老师给我们看了很多交通标志。", "target_word": "符号学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本符号学入门书很容易懂。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说符号学很有意思。", "target_word": "符号学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "符号学可以解释为什么红色表示危险。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他明年想考符号学的研究生。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里有一排关于符号学的书。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道符号学是什么吗？", "target_word": "符号学", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "符號學", "label": "繁体"}, {"form": "符号学家", "label": "复合"}, {"form": "门", "label": "量词"}], "register": "中性", "sense_fingerprint": "研究记号如何表达意思的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32eff56-4792-44c1-a9a0-d093cf3792f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号学", "is_correct": true, "explanation": "正确：符号学是学问，能够“告诉我们”理论内容。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是自然现象，不能告诉我们路标的道理。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，无法告诉我们路标的道理。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“告诉”的主语须能传递信息，窗户不能传递知识。"}], "explanations": {"符号学": "正确：符号学是学问，能够“告诉我们”理论内容。", "海浪": "语义：海浪是自然现象，不能告诉我们路标的道理。", "冰箱": "语义：冰箱是家电，无法告诉我们路标的道理。", "窗户": "配价：“告诉”的主语须能传递信息，窗户不能传递知识。"}, "sentence_index": 0, "correct_answer": "符号学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看懂了路口的符号学。", "explanation": "这里应该用〈符号〉。符号学是学科，路口的具体标志要说〈符号〉，两者容易混淆。"}, {"text": "妈妈在厨房里放了一只符号学。", "explanation": "学科是抽象的，不能放进厨房；计量学科应用“门”，不能用“只”。"}, {"text": "她把符号学挂在墙上了。", "explanation": "这里应该用〈海报〉。符号学是抽象的学问，不能挂在墙上；“挂”只用于画、海报之类的具体物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号学", "is_correct": true, "explanation": "正确：符号学是学问，能够解释科学道理。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不能解释红色的含义。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚是清洁用品，无法解释红色表示危险的道理。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，不能解释红色的含义。"}], "explanations": {"符号学": "正确：符号学是学问，能够解释科学道理。", "钥匙": "语义：钥匙是开锁的工具，不能解释红色的含义。", "扫帚": "语义：扫帚是清洁用品，无法解释红色表示危险的道理。", "雨伞": "语义：雨伞是遮雨的用具，不能解释红色的含义。"}, "sentence_index": 6, "correct_answer": "符号学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用符号学煮了一锅粥。", "explanation": "这里应该用〈大米〉。符号学是学问，不是食材，不能用来煮粥。"}, {"text": "我每天早上洗符号学。", "explanation": "这里应该用〈衣服〉。符号学是抽象的学问，不能洗；“洗”只用于衣物、餐具等具体物件。"}, {"text": "她唱了一首符号学。", "explanation": "这里应该用〈歌〉。符号学是学科，不是可以演唱的作品，不能用“一首”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于学会了这符号学。", "corrected_sentence": "他终于学会了这门符号学。", "error_description": "“这”修饰学科名词时要带量词，应说“这门符号学”，不能直接说“这符号学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经研究了一符号学。", "corrected_sentence": "他曾经研究了一门符号学。", "error_description": "数量短语要带量词，学科名词应说“一门符号学”，不能说“一符号学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
