INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语义就是词语或句子表示的意思。", "primary_collocate": null, "pronunciation": "yǔ yì", "ipa": "y˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "请你说一说这个词的语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个词的语义很接近。", "target_word": "语义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩子慢慢学会了词语的语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话的语义不清楚。", "target_word": "语义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "查词典可以知道一个词的语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看懂了每个字，却不懂整句的语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语义不同，用法也不同。", "target_word": "语义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师用图片解释了这个词的语义。", "target_word": "语义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词有两个语义。", "target_word": "语义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把这段话的语义写在本子上。", "target_word": "语义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語義", "label": "繁体"}, {"form": "语义学", "label": "复合"}, {"form": "语义场", "label": "复合"}], "register": "书面", "sense_fingerprint": "词语或句子表示的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32eff56-4792-44c1-a9a0-d093cf3792f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "语义", "is_correct": true, "explanation": "正确答案：语义（yǔ yì）。"}, {"text": "语气", "is_correct": false, "explanation": "qì（第四声）与 yì（第四声）声母不同，意思是语气。"}, {"text": "雨衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是雨衣。"}, {"text": "雨季", "is_correct": false, "explanation": "jì 与 yì 声母不同，意思是雨季。"}, {"text": "语系", "is_correct": false, "explanation": "xì 与 yì 声母不同，意思是语系。"}], "explanations": {"语义": "正确答案：语义（yǔ yì）。", "语气": "qì（第四声）与 yì（第四声）声母不同，意思是语气。", "雨衣": "yī（第一声）与 yì（第四声）声调不同，意思是雨衣。", "雨季": "jì 与 yì 声母不同，意思是雨季。", "语系": "xì 与 yì 声母不同，意思是语系。"}, "sentence_index": null, "correct_answer": "语义"}, "level_3": {"options": [{"text": "语义", "is_correct": true, "explanation": "正确：语义指词语表示的意思，可以“说一说”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“说一说价格”指标价，不是词语表示的意思。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重属于身体特征，不是词语的属性。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：词语没有颜色，句中要说的是词语表示的意思。"}], "explanations": {"语义": "正确：语义指词语表示的意思，可以“说一说”。", "价格": "语义：“说一说价格”指标价，不是词语表示的意思。", "体重": "体貌：体重属于身体特征，不是词语的属性。", "颜色": "语义：词语没有颜色，句中要说的是词语表示的意思。"}, "sentence_index": 0, "correct_answer": "语义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话的语义很温和。", "explanation": "这里应该用〈语气〉。语义指词语或句子的意思，说话的温和程度要说〈语气〉，两者容易混淆。"}, {"text": "他今天的语义很好。", "explanation": "这里应该用〈心情〉。语义指意思，人的心情好坏不说语义。"}, {"text": "我把语义放进了冰箱。", "explanation": "这里应该用〈牛奶〉。语义是抽象的意思，不能装进冰箱，应说〈牛奶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语义", "is_correct": true, "explanation": "正确：语义与“用法”并列，说明词的两个不同方面。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，不能与“用法”相比。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是天气数据，不能说明词语之间的差别。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是词语的属性，与“用法”不对应。"}], "explanations": {"语义": "正确：语义与“用法”并列，说明词的两个不同方面。", "身高": "体貌：身高是身体特征，不能与“用法”相比。", "气温": "语义：气温是天气数据，不能说明词语之间的差别。", "天气": "语义：天气不是词语的属性，与“用法”不对应。"}, "sentence_index": 6, "correct_answer": "语义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的语义很高。", "explanation": "这里应该用〈身高〉。语义指意思，人的高矮要说〈身高〉。"}, {"text": "这件衣服的语义很贵。", "explanation": "这里应该用〈价格〉。语义指意思，东西贵贱要说〈价格〉。"}, {"text": "她唱了一首语义。", "explanation": "这里应该用〈歌〉。语义是抽象的意思，不能被演唱，应说〈歌〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把这句话的很语义说清楚了。", "corrected_sentence": "他终于把这句话的语义说清楚了。", "error_description": "“很”不能直接修饰名词“语义”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
